cd /workspace && python3 - <<'EOF' > /tmp/digest.txt
import json
d=json.load(open('contracts/openapi.contract.json'))
def fmt(s, ind=0, maxd=8):
    out=[]
    pad='  '*ind
    if not isinstance(s,dict): return pad+str(s)
    t=s.get('type')
    if 'enum' in s: return pad+f"{t} enum={s['enum']}"
    if t=='object' or 'properties' in s:
        req=s.get('required',[])
        out.append(pad+'object' + ('' if s.get('additionalProperties',True) else ' (closed)'))
        for k,v in (s.get('properties') or {}).items():
            out.append(pad+f"  {k}{'*' if k in req else ''}: "+fmt(v,ind+1).lstrip())
        return '\n'.join(out)
    if t=='array':
        return pad+'array of:\n'+fmt(s.get('items',{}),ind+1)
    if 'oneOf' in s: return pad+'oneOf:\n'+'\n'.join(fmt(x,ind+1) for x in s['oneOf'])
    if 'anyOf' in s: return pad+'anyOf:\n'+'\n'.join(fmt(x,ind+1) for x in s['anyOf'])
    if '$ref' in s: return pad+s['$ref']
    return pad+f"{t} {s.get('format','')}"
for p,ops in d['paths'].items():
    for m,op in ops.items():
        print('='*80)
        print(m.upper(),p,op.get('operationId'))
        for prm in op.get('parameters',[]):
            print(' PARAM',prm.get('name'),prm.get('in'),prm.get('required'),json.dumps(prm.get('schema',{})))
        rb=op.get('requestBody')
        if rb:
            sch=rb.get('content',{}).get('application/json',{}).get('schema',{})
            print(' REQUEST:'); print(fmt(sch,1))
        for code,r in (op.get('responses') or {}).items():
            sch=r.get('content',{}).get('application/json',{}).get('schema')
            print(f' RESP {code}:')
            if sch: print(fmt(sch,1))
print('='*80)
print('COMPONENTS:')
for k,v in (d.get('components',{}).get('schemas') or {}).items():
    print('--',k); print(fmt(v,1))
EOF
wc -l /tmp/digest.txt

