package main

import (
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"fmt"
	"math"
	"net/http"
	"time"
)

func newUUID() string {
	b := make([]byte, 16)
	rand.Read(b)
	b[6] = (b[6] & 0x0f) | 0x40
	b[8] = (b[8] & 0x3f) | 0x80
	return fmt.Sprintf("%x-%x-%x-%x-%x", b[0:4], b[4:6], b[6:8], b[8:10], b[10:16])
}

func hashPassword(pw, salt string) string {
	h := sha256.Sum256([]byte(salt + ":" + pw))
	return hex.EncodeToString(h[:])
}

func hashRequest(body []byte) string {
	h := sha256.Sum256(body)
	return hex.EncodeToString(h[:])
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func writeData(w http.ResponseWriter, status int, data any) {
	writeJSON(w, status, map[string]any{"data": data})
}

type apiErr struct {
	status int
	code   string
	msg    string
}

func (e *apiErr) Error() string { return e.msg }

func errOf(status int, code, msg string) *apiErr {
	return &apiErr{status: status, code: code, msg: msg}
}

func writeErr(w http.ResponseWriter, e *apiErr) {
	writeJSON(w, e.status, map[string]any{"error": e.msg, "code": e.code})
}

func parseTime(s string) (time.Time, bool) {
	if s == "" {
		return time.Time{}, false
	}
	t, err := time.Parse(time.RFC3339Nano, s)
	if err != nil {
		t, err = time.Parse(time.RFC3339, s)
	}
	if err != nil {
		return time.Time{}, false
	}
	return t.UTC(), true
}

func fmtTime(t time.Time) string {
	if t.IsZero() {
		return ""
	}
	return t.UTC().Format(time.RFC3339Nano)
}

func timePtr(t time.Time) any {
	if t.IsZero() {
		return nil
	}
	return fmtTime(t)
}

func nullTime(t *time.Time) any {
	if t == nil || t.IsZero() {
		return nil
	}
	return fmtTime(*t)
}

func haversineKm(lat1, lon1, lat2, lon2 float64) float64 {
	const R = 6371.0
	dLat := (lat2 - lat1) * math.Pi / 180
	dLon := (lon2 - lon1) * math.Pi / 180
	a := math.Sin(dLat/2)*math.Sin(dLat/2) +
		math.Cos(lat1*math.Pi/180)*math.Cos(lat2*math.Pi/180)*math.Sin(dLon/2)*math.Sin(dLon/2)
	return R * 2 * math.Atan2(math.Sqrt(a), math.Sqrt(1-a))
}

func strSlice(v json.RawMessage) []string {
	var out []string
	if len(v) > 0 {
		json.Unmarshal(v, &out)
	}
	if out == nil {
		out = []string{}
	}
	return out
}

func mustJSON(v any) string {
	b, _ := json.Marshal(v)
	return string(b)
}

func contains(s []string, v string) bool {
	for _, x := range s {
		if x == v {
			return true
		}
	}
	return false
}

// recordAudit writes an audit log row.
func recordAudit(actorID, role, action, entityType, entityID string, success bool, details map[string]any) {
	if details == nil {
		details = map[string]any{}
	}
	db.Exec(`INSERT INTO audit_log (actor_id, role, action, entity_type, entity_id, success, details) VALUES ($1,$2,$3,$4,$5,$6,$7)`,
		actorID, role, action, entityType, entityID, success, mustJSON(details))
}

// publishEvent writes a realtime event.
func publishEvent(typ, entityType, entityID, audienceRole string, payload map[string]any) {
	if payload == nil {
		payload = map[string]any{}
	}
	db.Exec(`INSERT INTO events (type, entity_type, entity_id, audience_role, payload) VALUES ($1,$2,$3,$4,$5)`,
		typ, entityType, entityID, audienceRole, mustJSON(payload))
}

func staleLocation(recordedAt *time.Time) bool {
	if recordedAt == nil {
		return false
	}
	return time.Since(*recordedAt) > 15*time.Minute
}

