	ID                  string
	Name                string
	Coord               Coordinate
	CoverageKm          float64
	HandlingMinutes     int
	Active              bool
	Functions           map[string]bool
	CapacityUnits       int
	CooledCapacityUnits int
	ReservedUnits       int
	CooledReservedUnits int
