	var l Location
	var fn []byte
	err := row.Scan(&l.ID, &l.Name, &l.Coord.Latitude, &l.Coord.Longitude, &l.CoverageKm, &l.HandlingMinutes, &l.Active, &fn, &l.CapacityUnits, &l.CooledCapacityUnits, &l.ReservedUnits, &l.CooledReservedUnits)
	if err != nil {
		return nil, err
	}
	l.Functions = map[string]bool{}
	json.Unmarshal(fn, &l.Functions)
	return &l, nil
