	rows, err := db.Query(`SELECT ` + locationCols + ` FROM locations ORDER BY created_at`)
	if err != nil {
		return nil
	}
	defer rows.Close()
	var out []*Location
	for rows.Next() {
		if l, err := scanLocation(rows); err == nil {
