	"time"
)

type Coordinate struct {
	Latitude  float64 `json:"latitude"`
	Longitude float64 `json:"longitude"`
}

type User struct {
	ID                 string
	Username           string
	PasswordHash       string
	Email              string
	FullName           string
	Phone              string
	Roles              []string
	Qualifications     []string
	Certifications     []map[string]any
	Active             bool
	AssignedLocationID *string
	Available          bool
	CapacityUnits      int
	DeclineCount       int
	LatestLocation     *Coordinate
	LocationRecordedAt *time.Time
}

func loadUser(id string) (*User, error) {
	var u User
	var roles, quals, certs []byte
	var loc []byte
	err := db.QueryRow(`SELECT id, username, password_hash, email, full_name, phone, roles, qualifications, certifications, active, assigned_location_id, available, capacity_units, decline_count, latest_location, location_recorded_at FROM users WHERE id=$1`, id).
		Scan(&u.ID, &u.Username, &u.PasswordHash, &u.Email, &u.FullName, &u.Phone, &roles, &quals, &certs, &u.Active, &u.AssignedLocationID, &u.Available, &u.CapacityUnits, &u.DeclineCount, &loc, &u.LocationRecordedAt)
	if err != nil {
		return nil, err
	}
	json.Unmarshal(roles, &u.Roles)
	json.Unmarshal(quals, &u.Qualifications)
	json.Unmarshal(certs, &u.Certifications)
	if u.Roles == nil {
		u.Roles = []string{}
	}
	if u.Qualifications == nil {
		u.Qualifications = []string{}
	}
	if u.Certifications == nil {
		u.Certifications = []map[string]any{}
	}
	if len(loc) > 0 {
		var c Coordinate
		if json.Unmarshal(loc, &c) == nil {
			u.LatestLocation = &c
		}
	}
	return &u, nil
}

func (u *User) hasActiveCertification(code string) bool {
	if code == "" {
		return true
	}
	for _, c := range u.Certifications {
		cCode, _ := c["code"].(string)
		active, _ := c["active"].(bool)
		if cCode == code && active {
			if exp, ok := c["expiresAt"].(string); ok && exp != "" {
				if t, ok2 := parseTime(exp); ok2 && t.Before(time.Now()) {
					continue
				}
			}
			return true
		}
	}
	// fall back to qualifications list
	return contains(u.Qualifications, code)
}

type Location struct {
	ID                  string
	Name                string
	Coord               Coordinate
	CoverageKm          float64
	HandlingMinutes     int
	Active              bool
	Functions           map[string]bool
	CapacityUnits       int
	CooledCapacityUnits int
	ReservedUnits       int
	CooledReservedUnits int
}

func scanLocation(row interface{ Scan(...any) error }) (*Location, error) {
	var l Location
	var fn []byte
	err := row.Scan(&l.ID, &l.Name, &l.Coord.Latitude, &l.Coord.Longitude, &l.CoverageKm, &l.HandlingMinutes, &l.Active, &fn, &l.CapacityUnits, &l.CooledCapacityUnits, &l.ReservedUnits, &l.CooledReservedUnits)
	if err != nil {
		return nil, err
	}
	l.Functions = map[string]bool{}
	json.Unmarshal(fn, &l.Functions)
	return &l, nil
}

const locationCols = `id, name, latitude, longitude, coverage_km, handling_minutes, active, functions, capacity_units, cooled_capacity_units, reserved_units, cooled_reserved_units`

func loadLocation(id string) (*Location, error) {
	return scanLocation(db.QueryRow(`SELECT `+locationCols+` FROM locations WHERE id=$1`, id))
}

func loadAllLocations() []*Location {
	rows, err := db.Query(`SELECT ` + locationCols + ` FROM locations ORDER BY created_at`)
	if err != nil {
		return nil
	}
	defer rows.Close()
	var out []*Location
	for rows.Next() {
		if l, err := scanLocation(rows); err == nil {
			out = append(out, l)
		}
	}
	return out
}

func (l *Location) hasFunction(f string) bool {
	return l.Active && l.Functions[f]
}

func locationJSON(l *Location) map[string]any {
	return map[string]any{
