func loadAllConnections() []*Connection {
	rows, err := db.Query(`SELECT id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, cooled_capacity_units, reserved_units, cooled_reserved_units FROM connections ORDER BY created_at`)
