	var n int
	db.QueryRow(`SELECT count(*) FROM users`).Scan(&n)
	if n > 0 {
		return
	}
	username := getenv("ADMIN_USERNAME", "admin")
	password := getenv("ADMIN_PASSWORD", "admin")
	salt := newUUID()
	db.Exec(`INSERT INTO users (id, username, password_hash, full_name, roles, active) VALUES ($1,$2,$3,$4,$5,true)`,
