package main

import (
	"crypto/rand"
	"encoding/base64"
	"encoding/json"
	"io"
	"net/http"
	"strings"
)

type session struct {
	Token      string
	User       *User
	ActiveRole string
}

func getSession(r *http.Request) *session {
	tok := bearerToken(r)
	if tok == "" {
		return nil
	}
	var userID string
	var role *string
	err := db.QueryRow(`SELECT user_id, active_role FROM sessions WHERE token=$1`, tok).Scan(&userID, &role)
	if err != nil {
		return nil
	}
	u, err := loadUser(userID)
	if err != nil || !u.Active {
		return nil
	}
	s := &session{Token: tok, User: u}
	if role != nil {
		s.ActiveRole = *role
	}
	return s
}

func bearerToken(r *http.Request) string {
	h := r.Header.Get("Authorization")
	if strings.HasPrefix(h, "Bearer ") {
		return strings.TrimPrefix(h, "Bearer ")
	}
	if t := r.URL.Query().Get("token"); t != "" {
		return t
	}
	// WebSocket subprotocol: base64url-encoded "bearer.<token>"
	for _, p := range strings.Split(r.Header.Get("Sec-WebSocket-Protocol"), ",") {
		p = strings.TrimSpace(p)
		if p == "" {
			continue
		}
		cand := p
		if dec, err := base64.RawURLEncoding.DecodeString(p); err == nil {
			cand = string(dec)
		} else if dec, err := base64.URLEncoding.DecodeString(p); err == nil {
			cand = string(dec)
		}
		if strings.HasPrefix(cand, "bearer.") {
			return strings.TrimPrefix(cand, "bearer.")
		}
		if strings.HasPrefix(cand, "Bearer ") {
			return strings.TrimPrefix(cand, "Bearer ")
		}
	}
	return ""
}

// rolePermissions maps each operation to the roles allowed to perform it.
var rolePermissions = map[string][]string{
	"check_serviceability":           {"requester", "dispatcher", "administrator"},
	"create_collection_request":      {"requester"},
	"ingest_presealed_sample":        {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"collect_and_seal_sample":        {"collection_professional"},
	"accept_assignment":              {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"decline_assignment":             {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"update_assignment_progress":     {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"record_worker_location":         {"collection_professional", "delivery_partner"},
	"initiate_handoff":               {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"confirm_handoff":                {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"record_handling_checkpoint":     {"collection_professional", "delivery_partner", "node_handler", "laboratory_team"},
	"confirm_laboratory_receipt":     {"laboratory_team"},
	"record_laboratory_exception":    {"laboratory_team"},
	"configure_capacity":             {"node_handler", "laboratory_team", "administrator"},
	"configure_laboratory_acceptance": {"administrator", "laboratory_team"},
	"create_location":                {"administrator"},
	"update_location":                {"administrator"},
	"create_connection":              {"administrator"},
	"create_sample_type":             {"administrator"},
	"update_sample_type":             {"administrator"},
	"create_user":                    {"administrator"},
	"update_user_access":             {"administrator"},
	"read_user":                      {"administrator"},
	"set_location_status":            {"administrator"},
	"set_location_function_status":   {"administrator"},
	"set_connection_status":          {"administrator"},
	"set_worker_availability":        {"collection_professional", "delivery_partner", "node_handler", "laboratory_team", "dispatcher", "administrator"},
	"cancel_journey":                 {"dispatcher", "administrator"},
	"reroute_journey":                {"x dispatcher", "administrator"},
	"split_journey":                  {"dispatcher", "administrator"},
	"merge_journeys":                 {"dispatcher", "administrator"},
	"edit_active_plan":               {"dispatcher", "administrator"},
	"report_disruption":              {"dispatcher", "administrator"},
	"read_operations_state":          {"dispatcher", "administrator"},
	"search_audit_trail":             {"dispatcher", "administrator"},
	"list_role_work":                 {"requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team", "dispatcher", "administrator"},
	"read_sample_state":              {"requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team", "dispatcher", "administrator"},
	"read_sample_lifecycle":          {"requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team", "dispatcher", "administrator"},
	"read_journey_plan":              {"requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team", "dispatcher", "administrator"},
	"read_serviceability_snapshot":   {"requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team", "dispatcher", "administrator"},
}

func roleAllowed(op, role string) bool {
	roles, ok := rolePermissions[op]
	if !ok {
		return true
	}
	return contains(roles, role)
}

// handler is an authenticated operation handler.
type handler func(s *session, body []byte) (int, any, *apiErr)

// op wraps a handler with auth, RBAC, JSON parsing and optional idempotency.
func op(name string, requireIdempotency bool, h handler) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		body, err := io.ReadAll(r.Body)
		if err != nil {
			writeErr(w, errOf(400, "invalid_json", "could not read request body"))
			return
		}
		if len(body) > 0 {
			var js any
			if json.Unmarshal(body, &js) != nil {
				writeErr(w, errOf(400, "invalid_json", "request body is not valid JSON"))
				return
			}
		}
		s := getSession(r)
		if s == nil {
			writeErr(w, errOf(401, "unauthorized", "authentication required"))
			return
		}
		if s.ActiveRole == "" && name != "select_active_role" && name != "read_ui_bootstrap" {
			recordAudit(s.User.ID, "", name, "", "", false, map[string]any{"reason": "role_not_selected"})
			writeErr(w, errOf(409, "role_not_selected", "an active role must be selected before performing this action"))
			return
		}
		if !roleAllowed(name, s.ActiveRole) {
			recordAudit(s.User.ID, s.ActiveRole, name, "", "", false, map[string]any{"reason": "forbidden"})
			writeErr(w, errOf(403, "forbidden", "your active role may not perform this action"))
			return
		}
		if requireIdempotency {
			var parsed struct {
				IdempotencyKey string `json:"idempotencyKey"`
			}
			json.Unmarshal(body, &parsed)
			if parsed.IdempotencyKey == "" {
				writeErr(w, errOf(400, "idempotency_required", "idempotencyKey is required"))
				return
			}
			hash := hashRequest(body)
			var prevHash string
			var prevStatus int
			var prevBody []byte
			err := db.QueryRow(`SELECT request_hash, response_status, response_body FROM idempotency_keys WHERE key=$1 AND user_id=$2 AND op=$3`, parsed.IdempotencyKey, s.User.ID, name).Scan(&prevHash, &prevStatus, &prevBody)
			if err == nil {
				if prevHash != hash {
					writeErr(w, errOf(409, "idempotency_conflict", "idempotency key was already used with a different request"))
					return
				}
				w.Header().Set("Content-Type", "application/json")
				w.WriteHeader(prevStatus)
				w.Write(prevBody)
				return
			}
			status, data, aerr := h(s, body)
			if aerr != nil {
				recordAudit(s.User.ID, s.ActiveRole, name, "", "", false, map[string]any{"code": aerr.code})
				writeErr(w, aerr)
				return
			}
			respBody, _ := json.Marshal(map[string]any{"data": data})
			db.Exec(`INSERT INTO idempotency_keys (key, user_id, op, request_hash, response_status, response_body) VALUES ($1,$2,$3,$4,$5,$6) ON CONFLICT DO NOTHING`,
				parsed.IdempotencyKey, s.User.ID, name, hash, status, string(respBody))
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(status)
			w.Write(respBody)
			return
		}
		status, data, aerr := h(s, body)
		if aerr != nil {
			writeErr(w, aerr)
			return
		}
		writeData(w, status, data)
	}
}

func decodeBody(body []byte, v any) *apiErr {
	if len(body) == 0 {
		return errOf(400, "invalid_json", "request body is required")
	}
	dec := json.NewDecoder(strings.NewReader(string(body)))
	dec.DisallowUnknownFields()
	if err := dec.Decode(v); err != nil {
		return errOf(400, "invalid_json", "invalid request body: "+err.Error())
	}
	return nil
}

func randomToken() string {
	b := make([]byte, 32)
	rand.Read(b)
	return base64.RawURLEncoding.EncodeToString(b)
}

