		Active     bool   `json:"active"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	if !contains([]string{"collection_point", "transfer_point", "hub", "laboratory"}, req.Function) {
		return 0, nil, errOf(400, "invalid_location", "unknown function")
	}
	l, err := loadLocation(req.LocationID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "location not found")
	}
	l.Functions[req.Function] = req.Active
	db.Exec(`UPDATE locations SET functions=$1 WHERE id=$2`, mustJSON(l.Functions), l.ID)
	recordAudit(s.User.ID, s.ActiveRole, "set_location_function_status", "location", l.ID, true, map[string]any{"function": req.Function, "active": req.Active})
	bumpNetworkRevision()
	if !req.Active {
		go replanForUnavailableLocation(l.ID)
	}
