func handleSetConnectionStatus(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		ConnectionID string `json:"connectionId"`
		Active       bool   `json:"active"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	var exists int
	db.QueryRow(`SELECT count(*) FROM connections WHERE id=$1`, req.ConnectionID).Scan(&exists)
	if exists == 0 {
		return 0, nil, errOf(404, "not_found", "connection not found")
	}
	db.Exec(`UPDATE connections SET active=$1 WHERE id=$2`, req.Active, req.ConnectionID)
	recordAudit(s.User.ID, s.ActiveRole, "set_connection_status", "connection", req.ConnectionID, true, map[string]any{"active": req.Active})
	bumpNetworkRevision()
	if !req.Active {
		go replanForUnavailableConnection(req.ConnectionID)
	}
	return 200, map[string]any{"connectionId": req.ConnectionID, "active": req.Active}, nil
