func loadCapacityTarget(targetType, targetID string) (regularCap, cooledCap, regularRes, cooledRes int, err error) {
	switch targetType {
	case "node", "laboratory":
		err = db.QueryRow(`SELECT capacity_units, cooled_capacity_units, reserved_units, cooled_reserved_units FROM locations WHERE id=$1`, targetID).Scan(&regularCap, &cooledCap, &regularRes, &cooledRes)
	case "connection":
		err = db.QueryRow(`SELECT capacity_units, cooled_capacity_units, reserved_units, cooled_reserved_units FROM connections WHERE id=$1`, targetID).Scan(&regularCap, &cooledCap, &regularRes, &cooledRes)
	default:
		err = errOf(400, "invalid_capacity", "unknown targetType")
	}
	return
}

func handleConfigureCapacity(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		TargetType          string `json:"targetType"`
		TargetID            string `json:"targetId"`
		CapacityUnits       int    `json:"capacityUnits"`
		CooledCapacityUnits int    `json:"cooledCapacityUnits"`
	}
	if aerr := decodeBody(body, &req); relErr(aerr) {
		return 0, nil, aerr
	}
	if req.CapacityUnits < 0 || req.CooledCapacityUnits < 0 {
		return 0, nil, errOf(400, "invalid_capacity", "capacity values must be non-negative")
	}
	if !contains([]string{"node", "laboratory", "connection"}, req.TargetType) {
		return 0, nil, errOf(400, "invalid_capacity", "unknown targetType")
	}
	_, _, regRes, coolRes, err := loadCapacityTarget(req.TargetType, req.TargetID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "capacity target not found")
	}
	if req.CapacityUnits < regRes || req.CooledCapacityUnits < coolRes {
		return 0, nil, errOf(409, "capacity_reserved", "configured capacity cannot be below currently reserved units")
	}
	// node handlers and lab operators may only configure their own assigned location
	if s.ActiveRole == "node_handler" || s.ActiveRole == "laboratory_team" {
		if req.TargetType == "connection" || s.User.AssignedLocationID == nil || *s.User.AssignedLocationID != req.TargetID {
			return 0, nil, errOf(403, "forbidden", "you may only configure capacity at your assigned location")
		}
	}
	var table string
	if req.TargetType == "connection" {
		table = "connections"
	} else {
		table = "locations"
	}
	db.Exec(`UPDATE `+table+` SET capacity_units=$1, cooled_capacity_units=$2 WHERE id=$3`, req.CapacityUnits, req.CooledCapacityUnits, req.TargetID)
	recordAudit(s.User.ID, s.ActiveRole, "configure_capacity", req.TargetType, req.TargetID, true, map[string]any{"capacityUnits": req.CapacityUnits, "cooledCapacityUnits": req.CooledCapacityUnits})
	bumpNetworkRevision()
	return 200, map[string]any{
		"targetType":                req.TargetType,
		"targetId":                  req.TargetID,
		"capacityUnits":             req.CapacityUnits,
		"cooledCapacityUnits":       req.CooledCapacityUnits,
		"reservedUnits":             regRes,
		"cooledReservedUnits":       coolRes,
		"availableUnits":            req.CapacityUnits - regRes,
		"cooledAvailableUnits":      req.CooledCapacityUnits - coolRes,
	}, nil
}

func relErr(e *apiErr) bool { return e != nil }

func handleConfigureLabAcceptance(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      bool   `json:"accepts"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	l, err := loadLocation(req.LaboratoryID)
	if err != nil || !l.Functions["laboratory"] {
		return 0, nil, errOf(404, "not_found", "laboratory not found")
	}
	if _, err := loadSampleType(req.SampleTypeID); err != nil {
		return 0, nil, errOf(404, "not_found", "sample type not found")
	}
	if s.ActiveRole == "laboratory_team" && (s.User.AssignedLocationID == nil || *s.User.AssignedLocationID != req.LaboratoryID) {
		return 0, nil, errOf(403, "forbidden |laboratory_not_assigned", "you are not assigned to this laboratory")
	}
	db.Exec(`INSERT INTO lab_acceptance (id, laboratory_id, sample_type_id, accepts) VALUES ($1,$2,$3,$4)
		ON CONFLICT (laboratory_id, sample_type_id) DO UPDATE SET accepts=$4`, newUUID(), req.LaboratoryID, req.SampleTypeID, req.Accepts)
	recordAudit(s.User.ID, s.ActiveRole, "configure_laboratory_acceptance", "laboratory", req.LaboratoryID, true, map[string]any{"sampleTypeId": req.SampleTypeID, "accepts": req.Accepts})
	bumpNetworkRevision()
	return 200, map[string]any{"laboratoryId": req.LaboratoryID, "sampleTypeId": req.SampleTypeID, "accepts": req.Accepts}, nil
}

func ensureServiceabilitySnapshot() {
	var n int
	db.QueryRow(`SELECT count(*) FROM serviceability_snapshots`).Scan(&n)
	if n == 0 {
		recomputeServiceabilitySnapshot()
	}
}

func recomputeServiceabilitySnapshot() {
	var maxVersion int
	db.QueryRow(`SELECT COALESCE(max(version),0) FROM serviceability_snapshots`).Scan(&maxVersion)
	locs := loadAllLocations()
	regions := []map[string]any{}
	activeCP := 0
	for _, l := range locs {
		if l.hasFunction("collection_point") {
			activeCP++
			regions = append(regions, map[string]any{
				"regionId":     l.ID,
				"locationId":   l.ID,
				"name":         l.Name,
				"center":       l.Coord,
				"radiusKm":     l.CoverageKm,
				"serviceable":  true,
				"computedFrom": "collection_point",
			})
		}
	}
	now := time.Now()
	db.Exec(`INSERT INTO serviceability_snapshots (version, status, computed_at, network_revision, regions, active_collection_point_count) VALUES ($1,'complete',$2,$3,$4,$5)`,
		maxVersion+1, now, networkRevision(), mustJSON(regions), activeCP)
	// prune old snapshots, keep last 5
	db.Exec(`DELETE FROM serviceability_snapshots WHERE version < $1`, maxVersion+1-5)
	publishEvent("serviceability_snapshot_updated", "serviceability_snapshot", "", "", map[string]any{"version": maxVersion + 1})
}

func handleReadServiceabilitySnapshot(s *session) (int, any, *apiErr) {
	var version, rev, cpCount int
	var computedAt time.Time
	var regions []byte
	err := db.QueryRow(`SELECT version, computed_at, network_revision, regions, active_collection_point_count FROM serviceability_snapshots WHERE status='complete' ORDER BY version DESC LIMIT 1`).Scan(&version, &computedAt, &rev, &regions, &cpCount)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "no serviceability snapshot is available yet")
	}
	var reg []map[string]any
	json.Unmarshal(regions, &reg)
	if reg == nil {
		reg = []map[string]any{}
	}
	return 200, map[string]any{
		"version":                    version,
		"status":                     "complete",
		"computedAt":                 fmtTime(computedAt),
		"networkRevision":            rev,
		"regions":                    reg,
		"activeCollectionPointCount": cpCount,
	}, nil
}
"}

