package main

import (
	"container/heap"
	"math"
	"time"
)

type planResult struct {
	serviceable       bool
	reason            string
	entryNode         *Location
	lab               *Location
	path              []*Connection
	estimatedDelivery time.Time
	totalCost         float64
}

// capacityAvailable reports whether a pool has spare capacity. A configured
// capacity of 0 means the pool is unmanaged (not capacity-limited).
func capacityAvailable(capacity, reserved int) bool {
	if capacity <= 0 {
		return true
	}
	return reserved < capacity
}

func labAccepts(labID, sampleTypeID string) bool {
	var accepts bool
	err := db.QueryRow(`SELECT accepts FROM lab_acceptance WHERE laboratory_id=$1 AND sample_type_id=$2`, labID, sampleTypeID).Scan(&accepts)
	return err == nil && accepts
}

func activeLabs(st *SampleType) []*Location {
	var out []*Location
	for _, l := range loadAllLocations() {
		if l.hasFunction("laboratory") && labAccepts(l.ID, st.ID) {
			if st.RequiresCooledRoute {
				if !capacityAvailable(l.CooledCapacityUnits, l.CooledReservedUnits) {
					continue
				}
			} else if !capacityAvailable(l.CapacityUnits, l.ReservedUnits) {
				continue
			}
			out = append(out, l)
		}
	}
	return out
}

type dijItem struct {
	node string
	cost float64
}
type dijHeap []dijItem

func (h dijHeap) Len() int            { return len(h) }
func (h dijHeap) Less(i, j int) bool  { return h[i].cost < h[j].cost }
func (h dijHeap) Swap(i, j int)       { h[i], h[j] = h[j], h[i] }
func (h *dijHeap) Push(x any)         { *h = append(*h, x.(dijItem)) }
func (h *dijHeap) Pop() any           { old := *h; n := len(old); it := old[n-1]; *h = old[:n-1]; return it }

// shortestPath returns the cheapest feasible path of connections from->to.
func shortestPath(fromID, toID string, st *SampleType, locs map[string]*Location, conns []*Connection) ([]*Connection, float64, bool) {
	dist := map[string]float64{fromID: 0}
	prev := map[string]*Connection{}
	pq := &dijHeap{{node: fromID, cost: 0}}
	for pq.Len() > 0 {
		it := heap.Pop(pq).(dijItem)
		if it.node == toID {
			break
		}
		if it.cost > dist[it.node] {
			continue
		}
		for _, c := range conns {
			if c.FromLocationID != it.node || !c.Active {
				continue
			}
			to := locs[c.ToLocationID]
			if to == nil || !to.Active {
				continue
			}
			if st.RequiresCooledRoute {
				if !c.Cooled || !capacityAvailable(c.CooledCapacityUnits, c.CooledReservedUnits) {
					continue
				}
			} else if !capacityAvailable(c.CapacityUnits, c.ReservedUnits) {
				continue
			}
			cost := float64(c.TravelMinutes)
			if c.ToLocationID != toID {
				cost += float64(to.HandlingMinutes)
			}
			nd := it.cost + cost
			if cur, ok := dist[c.ToLocationID]; !ok || nd < cur {
				dist[c.ToLocationID] = nd
				prev[c.ToLocationID] = c
				heap.Push(pq, dijItem{node: c.ToLocationID, cost: nd})
			}
		}
	}
	if _, ok := dist[toID]; !ok {
		return nil, 0, false
	}
	var path []*Connection
	for cur := toID; cur != fromID; {
		c := prev[cur]
		if c == nil {
			return nil, 0, false
		}
		path = append([]*Connection{c}, path...)
		cur = c.FromLocationID
	}
	return path, dist[toID], true
}

// evaluateServiceability runs the full dry-run serviceability evaluation.
func evaluateServiceability(origin Coordinate, originType string, originNodeID *string, st *SampleType, earliest, deadline time.Time) planResult {
	fail := func(reason string) planResult { return planResult{serviceable: false, reason: reason} }
	locs := map[string]*Location{}
	for _, l := range loadAllLocations() {
		locs[l.ID] = l
	}
	conns := loadAllConnections()

	// 1. origin coverage
	var entry *Location
	if originType == "node" {
		if originNodeID == nil {
			return fail("outside_service_coverage")
		}
		l := locs[*originNodeID]
		if l == nil || !l.hasFunction("collection_point") {
			return fail("outside_service_coverage")
		}
		entry = l
	} else {
		best := math.MaxFloat64
		for _, l := range locs {
			if !l.hasFunction("collection_point") {
				continue
			}
			d := haversineKm(origin.Latitude, origin.Longitude, l.Coord.Latitude, l.Coord.Longitude)
			if d <= 5.0 && d < best {
				best = d
				entry = l
			}
		}
		if entry == nil {
			return fail("outside_service_coverage")
		}
	}

	// 2. accepting laboratory
	labs := activeLabs(st)
	if len(labs) == 0 {
		// distinguish: does any active lab accept the type at all (capacity excluded)?
		anyAccepts := false
		for _, l := range locs {
			if l.hasFunction("laboratory") && labAccepts(l.ID, st.ID) {
				anyAccepts = true
				break
			}
		}
		if !anyAccepts {
			return fail("no_accepting_laboratory")
		}
		return fail("insufficient_capacity")
	}

	// 3. route + capacity + deadline
	start := earliest
	if start.Before(time.Now()) {
		start = time.Now()
	}
	bestFound := false
	var best planResult
	sawRoute := false
	sawCapacityFail := false
	for _, lab := range labs {
		path, minutes, ok := shortestPath(entry.ID, lab.ID, st, locs, conns)
		if !ok {
			// check if a route exists ignoring capacity to distinguish no_route vs insufficient_capacity
			if _, _, ok2 := shortestPathUnlimited(entry.ID, lab.ID, st, locs, conns); ok2 {
				sawCapacityFail = true
			}
			continue
		}
		sawRoute = true
		eta := start.Add(time.Duration(minutes) * time.Minute)
		if eta.After(deadline) {
			continue
		}
		cost := 0.0
		for _, c := range path {
			cost += c.CostUnits
		}
		if !bestFound || eta.Before(best.estimatedDelivery) {
			bestFound = true
			best = planResult{serviceable: true, entryNode: entry, lab: lab, path: path, estimatedDelivery: eta, totalCost: cost}
		}
	}
	if bestFound {
		return best
	}
	if !sawRoute {
		if sawCapacityFail {
			return fail("insufficient_capacity")
		}
		return fail("no_route")
	}
	return fail("deadline_unreachable")
}

// shortestPathUnlimited ignores capacity pools (used for reason classification).
func shortestPathUnlimited(fromID, toID string, st *SampleType, locs map[string]*Location, conns []*Connection) ([]*Connection, float64, bool) {
	dist := map[string]float64{fromID: 0}
	prev := map[string]*Connection{}
	pq := &dijHeap{{node: fromID, cost: 0}}
	for pq.Len() > 0 {
		it := heap.Pop(pq).(dijItem)
		if it.node == toID {
			break
		}
		if it.cost > dist[it.node] {
			continue
		}
		for _, c := range conns {
			if c.FromLocationID != it.node || !c.Active {
				continue
			}
			to := locs[c.ToLocationID]
			if to == nil || !to.Active {
				continue
			}
			if st.RequiresCooledRoute && !c.Cooled {
				continue
			}
			nd := it.cost + float64(c.TravelMinutes)
			if cur, ok := dist[c.ToLocationID]; !ok || nd < cur {
				dist[c.ToLocationID] = nd
				prev[c.ToLocationID] = c
				heap.Push(pq, dijItem{node: c.ToLocationID, cost: nd})
			}
		}
	}
	if _, ok := dist[toID]; !ok {
		return nil, 0, false
	}
	var path []*Connection
	for cur := toID; cur != fromID; {
		c := prev[cur]
		path = append([]*Connection{c}, path...)
		cur = c.FromLocationID
	}
	return path, dist[toID], true
}

// reserveCapacity reserves one unit on every pool used by a journey.
func reserveCapacity(plan *planResult, cooled bool) {
	for _, c := range plan.path {
		if cooled {
			db.Exec(`UPDATE connections SET cooled_reserved_units = cooled_reserved_units + 1 WHERE id=$1`, c.ID)
		} else {
			db.Exec(`UPDATE connections SET reserved_units = reserved_units + 1 WHERE id=$1`, c.ID)
		}
	}
	if plan.lab != nil {
		if cooled {
			db.Exec(`UPDATE locations SET cooled_reserved_units = cooled_reserved_units + 1 WHERE id=$1`, plan.lab.ID)
		} else {
			db.Exec(`UPDATE locations SET reserved_units = reserved_units + 1 WHERE id=$1`, plan.lab.ID)
		}
	}
	// intermediate nodes
	for i, c := range plan.path {
		if i == len(plan.path)-1 {
			break
		}
		if cooled {
			db.Exec(`UPDATE locations SET cooled_reserved_units = cooled_reserved_units + 1 WHERE id=$1`, c.ToLocationID)
		} else {
			db.Exec(`UPDATE locations SET reserved_units = reserved_units + 1 WHERE id=$1`, c.ToLocationID)
		}
	}
}

func releaseJourneyCapacity(j *Journey, cooled bool) {
	for _, cid := range j.ConnectionIDs {
		if cooled {
			db.Exec(`UPDATE connections SET cooled_reserved_units = GREATEST(cooled_reserved_units - 1, 0) WHERE id=$1`, cid)
		} else {
			db.Exec(`UPDATE connections SET reserved_units = GREATEST(reserved_units - 1, 0) WHERE id=$1`, cid)
		}
	}
	ids := append(append([]string{}, j.NodeIDs...), func() []string {
		if j.LaboratoryID != nil {
			return []string{*j.LaboratoryID}
		}
		return nil
	}()...)
	for _, nid := range ids {
		if cooled {
			db.Exec(`UPDATE locations SET cooled_reserved_units = GREATEST(cooled_reserved_units - 1, 0) WHERE id=$1`, nid)
		} else {
			db.Exec(`UPDATE locations SET reserved_units = GREATEST(reserved_units - 1, 0) WHERE id=$1`, nid)
		}
	}
}

// createJourney builds stops, legs, assignments and reserves capacity.
func createJourney(sampleID string, req *Request, st *SampleType, plan *planResult, routeMode string, needsCollection bool) (*Journey, *apiErr) {
	journeyID := newUUID()
	stops := []map[string]any{}
	legs := []map[string]any{}
	connIDs := []string{}
	nodeIDs := []string{}
	seq := 1
	stops = append(stops, map[string]any{"stopId": newUUID(), "sequence": seq, "kind": "pickup", "locationId": plan.entryNode.ID})
	seq++
	for i, c := range plan.path {
		connIDs = append(connIDs, c.ID)
		if i < len(plan.path)-1 {
			nodeIDs = append(nodeIDs, c.ToLocationID)
			stops = append(stops, map[string]any{"stopId": newUUID(), "sequence": seq, "kind": "handoff", "locationId": c.ToLocationID})
			seq++
		}
	}
	stops = append(stops, map[string]any{"stopId": newUUID(), "sequence": seq, "kind": "delivery", "locationId": plan.lab.ID})

	_, err := db.Exec(`INSERT INTO journeys (id, plan_version, route_mode, status, sample_ids, stops, legs, connection_ids, node_ids, laboratory_id, entry_location_id, estimated_delivery_at, total_cost_units) VALUES ($1,1,$2,'planned',$3,$4,'[]',$5,$6,$7,$8,$9,$10)`,
