		}
		if contains(a.DeclinedBy, u.ID) {
			continue
		}
		if a.Kind == "node" || a.Kind == "laboratory" {
			assigned := ""
			if a.Kind == "node" && a.NodeID != nil {
				assigned = *a.NodeID
			}
			if a.Kind == "laboratory" && a.LaboratoryID != nil {
				assigned = *a.LaboratoryID
			}
			if u.AssignedLocationID == nil || *u.AssignedLocationID != assigned {
				continue
			}
		}
		if a.Kind == "collection" && st != nil && st.QualifiedCollectorRequired {
			if !u.hasActiveCertification(st.RequiredQualification) {
				continue
			}
		}
		candidates = append(candidates, u)
	}
	// fairness ordering: workload asc, deprioritized last, oldest last_offered first
	type scored struct {
		u        *User
		workload int
		deprio   bool
		last     time.Time
	}
	var list []scored
	for _, u := range candidates {
		var wl int
		db.QueryRow(`SELECT count(*) FROM assignments WHERE worker_id=$1 AND status IN ('accepted','in_progress')`, u.ID).Scan(&wl)
		var depUntil *time.Time
		var last *time.Time
