		var lt time.Time
		if last != nil {
			lt = *last
		}
		list = append(list, scored{u, wl, dep, lt})
	}
	for i := 0; i < len(list); i++ {
		for j := i + 1; j < len(list); j++ {
			a, b := list[i], list[j]
			swap := false
			if a.deprio != b.deprio {
