		for _, a := range expired {
			declined := append(a.DeclinedBy, *a.OfferedTo)
			db.Exec(`UPDATE assignments SET status='pending', offered_to=NULL, offered_at=NULL, offer_expires_at=NULL, declined_by=$1, updated_at=now() WHERE id=$2`, mustJSON(declined), a.ID)
			recordAudit("", "system", "offer_expired", "assignment", a.ID, true, map[string]any{"workerId": *a.OfferedTo})
			a.DeclinedBy = declined
			offerAssignment(a)
		}
	}
	// no qualified worker exceptions
	rows2, err := db.Query(`SELECT ` + assignmentCols + ` FROM assignments WHERE status='pending' AND no_eligible_since IS NOT NULL AND no_eligible_since < now() - interval '15 minutes'`)
	if err == nil {
		var stuck []*Assignment
		for rows2.Next() {
			if a, err := scanAssignment(rows2); err == nil {
				stuck = append(stuck, a)
			}
		}
		rows2.Close()
		for _, a := range stuck {
			if a.SampleID != nil {
				flagSampleException(*a.SampleID, "no_qualified_worker", "no qualified worker is available for a required assignment")
			}
			db.Exec(`UPDATE assignments SET no_eligible_since=NULL WHERE id=$1`, a.ID)
		}
	}
}

func flagSampleException(sampleID, code, note string) {
	exc := map[string]any{
		"type":      code,
		"code":      code,
		"note":      note,
		"flaggedAt": fmtTime(time.Now()),
	}
	db.Exec(`UPDATE samples SET status='exception', exception=$1 WHERE id=$2 AND status NOT IN ('received','cancelled')`, mustJSON(exc), sampleID)
	recordAudit("", "system", "exception_flagged", "sample", sampleID, true, map[string]any{"code": code, "note": note})
	publishEvent("exception_raised", "sample", sampleID, "dispatcher", map[string]any{"code": code, "note": note})
}

