	}
	if !req.AlreadySealed {
		return 0, nil, errOf(400, "presealed_required", "alreadySealed must be true for pre-sealed ingestion")
	}
	if req.OriginType == "home" {
		return 0, nil, errOf(400, "invalid_request", "pre-sealed samples cannot originate from a home")
	}
	inner, _ := json.MarshalReq(req.requestInput)
	_ = inner
	// re-parse common fields
	st, err := loadSampleType(req.SampleTypeID)
	if err != nil {
		return 0, nil, errOf(400, "invalid_request", "unknown sampleTypeId")
	}
	requestedAt, ok := parseTime(req.RequestedAt)
	if !ok {
		return 0, nil, errOf(400, "invalid_request", "requestedAt must be an RFC3339 timestamp")
	}
	deadline, ok := parseTime(req.DeliveryDeadline)
	if !ok {
		return 0, nil, errOf(400, "invalid_request", "deliveryDeadline must be an RFC3339 timestamp")
