	}
	recordAudit(s.User.ID, s.ActiveRole, "create_collection_request", "sample", sampleID, true, map[string]any{"requestId": requestID, "journeyId": j.ID})
	recordAudit(s.User.ID, s.ActiveRole, "request_created", "sample", sampleID, true, map[string]any{"requestId": requestID, "originType": req.OriginType})
	publishEvent("sample_status", "sample", sampleID, "", map[string]any{"status": "created"})
	return 201, map[string]any{
