func handleAcceptAssignment(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		AssignmentID string `json:"assignmentId"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	a, err := loadAssignment(req.AssignmentID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "assignment not found")
	}
	if a.Status != "offered" || a.OfferedTo == nil {
		return 0, nil, errOf(409, "offer_not_available", "this assignment is not currently offered")
	}
	if *a.OfferedTo != s.User.ID {
		return 0, nil, errOf(409, "offer_not_offered", "this assignment was offered to another worker")
	}
	if a.OfferExpiresAt != nil && a.OfferExpiresAt.Before(time.Now()) {
		return 0, nil, errOf(409, "offer_not_available", "this offer has expired")
	}
	st := sampleTypeForAssignment(a)
	eligible := false
	for _, u := range eligibleWorkers(a, st) {
		if u.ID == s.User.ID {
			eligible = true
			break
		}
	}
	// declinedBy contains previous decliners; the current offer target is always eligible unless state changed
	if !eligible && !contains(a.DeclinedBy, s.User.ID) {
		// re-check basic eligibility without the declined filter
		if !basicEligible(s.User, a, st) {
			return 0, nil, errOf(403, "ineligible_worker", "you are no longer eligible for this assignment")
		}
	}
	db.Exec(`UPDATE assignments SET status='accepted', worker_id=$1, updated_at=now() WHERE id=$2`, s.User.ID, a.ID)
	if a.JourneyID != nil {
		db.Exec(`UPDATE journeys SET status='in_progress' WHERE id=$1 AND status='planned'`, *a.JourneyID)
	}
	recordAudit(s.User.ID, s.ActiveRole, "accept_assignment", "assignment", a.ID, true, map[string]any{"kind": a.Kind})
	publishEvent("assignment_updated", "assignment", a.ID, "", map[string]any{"status": "accepted", "workerId": s.User.ID})
	return 200, map[string]any{"assignmentId": a.ID, "status": "accepted", "workerId": s.User.ID}, nil
}

func basicEligible(u *User, a *Assignment, st *SampleType) bool {
	if !u.Active || !u.Available {
		return false
	}
	switch a.Kind {
	case "collection":
		if !contains(u.Roles, "collection_professional") {
			return false
		}
		if st != nil && st.QualifiedCollectorRequired && !u.hasActiveCertification(st.RequiredQualification) {
			return false
		}
	case "transport":
		return contains(u.Roles, "delivery_partner")
	case "node":
		return contains(u.Roles, "node_handler") && u.AssignedLocationID != nil && a.NodeID != nil && *u.AssignedLocationID == *a.NodeID
	case "laboratory":
		return contains(u.Roles, "laboratory_team") && u.AssignedLocationID != nil && a.LaboratoryID != nil && *u.AssignedLocationID == *a.LaboratoryID
	}
	return true
}

func handleDeclineAssignment(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		AssignmentID string `json:"assignmentId"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	a, err := loadAssignment(req.AssignmentID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "assignment not found")
	}
	if a.Status != "offered" || a.OfferedTo == nil || *a.OfferedTo != s.User.ID {
		return 0, nil, errOf(409, "offer_not_offered", "this assignment is not currently offered to you")
	}
	declined := append(a.DeclinedBy, s.User.ID)
	db.Exec(`UPDATE assignments SET status='pending', offered_to=NULL, offered_at=NULL, offer_expires_at=NULL, declined_by=$1, updated_at=now() WHERE id=$2`, mustJSON(declined), a.ID)
	db.Exec(`UPDATE users SET decline_count = decline_count + 1 WHERE id=$1`, s.User.ID)
	var dc int
	db.QueryRow(`SELECT decline_count FROM users WHERE id=$1`, s.User.ID).Scan(&dc)
	if dc >= 3 {
		db.Exec(`UPDATE users SET deprioritized_until = now() + interval '30 minutes', decline_count=0 WHERE id=$1`, s.User.ID)
	}
	recordAudit(s.User.ID, s.ActiveRole, "decline_assignment", "assignment", a.ID, true, map[string]any{"kind": a.Kind})
	a.DeclinedBy = declined
	offerAssignment(a)
	a2, _ := loadAssignment(a.ID)
	resp := map[string]any{"assignmentId": a.ID, "status": "pending"}
	if a2.OfferedTo != nil {
		resp["reofferedTo"] = *a2.OfferedTo
	}
	return 200, resp, nil
}

var progressOrder = map[string]int{
	"accepted": 1, "at_pickup": 2, "picked_up": 3, "in_transit": 4, "arrived": 5, "delivered": 6, "completed": 6,
}

func handleUpdateProgress(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		AssignmentID      string      `json:"assignmentId"`
		Status            string      `json:"status"`
		OccurredAt        string      `json:"occurredAt"`
		Location          *Coordinate `json:"location"`
		LocationSeq       int         `json:"locationSequence"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	a, err := loadAssignment(req.AssignmentID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "assignment not found")
	}
	if a.WorkerID == nil || *a.WorkerID != s.User.ID {
		return 0, nil, errOf(403, "forbidden", "this assignment is not accepted by you")
	}
	if a.Status == "completed" || a.Status == "cancelled" {
		return 0, nil, errOf(409, "invalid_assignment_state", "assignment is already "+a.Status)
	}
	if _, ok := progressOrder[req.Status]; !ok {
		return 0, nil, errOf(400, "invalid_assignment_state", "unknown progress status")
	}
	occurredAt := time.Now()
	if t, ok := parseTime(req.OccurredAt); ok {
		occurredAt = t
	}
	if req.Location != nil && !validCoordinate(*req.Location) {
		return 0, nil, errOf(400, "invalid_location", "invalid location coordinate")
	}
	newStatus := "in_progress"
	if req.Status == "delivered" || req.Status == "completed" {
		newStatus = "completed"
	}
	if req.Location != nil {
		db.Exec(`UPDATE assignments SET status=$1, progress_status=$2, location=$3, location_recorded_at=$4, location_sequence=$5, updated_at=now() WHERE id=$6`,
			newStatus, req.Status, mustJSON(req.Location), occurredAt, req.LocationSeq, a.ID)
	} else {
		db.Exec(`UPDATE assignments SET status=$1, progress_status=$2, updated_at=now() WHERE id=$3`, newStatus, req.Status, a.ID)
	}
	if a.SampleID != nil {
		// update sample location and status
		if req.Location != nil {
			db.Exec(`UPDATE samples SET latest_location=$1, location_recorded_at=$2 WHERE id=$3`, mustJSON(req.Location), occurredAt, *a.SampleID)
		}
		if a.Kind == "transport" && (req.Status == "picked_up" || req.Status == "in_transit") {
			db.Exec(`UPDATE samples SET status='in_transit' WHERE id=$1 AND status IN ('sealed','created')`, *a.SampleID)
		}
		if a.Kind == "transport" && req.Status == "delivered" {
			if isFinalLeg(a) {
				db.Exec(`UPDATE samples SET status='at_laboratory' WHERE id=$1 AND status NOT IN ('received','exception','expired','cancelled')`, *a.SampleID)
				if loc, err := loadLocation(*a.ToLocationID); err == nil {
					db.Exec(`UPDATE samples SET latest_location=$1, location_recorded_at=$2 WHERE id=$3`, mustJSON(loc.Coord), occurredAt, *a.SampleID)
				}
			}
		}
		recordAudit(s.User.ID, s.ActiveRole, "assignment_progress", "sample", *a.SampleID, true, map[string]any{"assignmentId": a.ID, "status": req.Status})
		publishEvent("sample_status", "sample", *a.SampleID, "", map[string]any{"assignmentId": a.ID, "status": req.Status})
	} else {
		recordAudit(s.User.ID, s.ActiveRole, "assignment_progress", "assignment", a.ID, true, map[string]any{"status": req.Status})
	}
	a2, _ := loadAssignment(a.ID)
	return 200, map[string]any{
		"assignmentId":         a2.ID,
		"status":               a2.Status,
		"progressStatus":       req.Status,
		"recordedAt":           fmtTime(occurredAt),
		"locationSequence":     a2.LocationSequence,
	}, nil
}

func isFinalLeg(a *Assignment) bool {
	if a.JourneyID == nil {
		return true
	}
	var maxSeq int
	db.QueryRow(`SELECT COALESCE(max(sequence),0) FROM assignments WHERE journey_id=$1 AND kind='transport'`, *a.JourneyID).Scan(&maxSeq)
	var mySeq int
	db.QueryRow(`SELECT sequence FROM assignments WHERE id=$1`, a.ID).Scan(&mySeq)
	return mySeq == maxSeq
}

func handleRecordWorkerLocation(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		Coordinate       Coordinate `json:"coordinate"`
		RecordedAt       string     `json:"recordedAt"`
		LocationSequence int        `json:"locationSequence"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	if !validCoordinate(req.Coordinate) {
		return 0, nil, errOf(400, "invalid_location", "invalid coordinate")
	}
	recordedAt := time.Now()
	if t, ok := parseTime(req.RecordedAt); ok {
		recordedAt = t
	}
	db.Exec(`UPDATE users SET latest_location=$1, location_recorded_at=$2 WHERE id=$3`, mustJSON(req.Coordinate), recordedAt, s.User.ID)
	recordAudit(s.User.ID, s.ActiveRole, "record_worker_location", "user", s.User.ID, true, map[string]any{"coordinate": req.Coordinate})
	publishEvent("worker_location", "user", s.User.ID, "dispatcher", map[string]any{"coordinate": req.Coordinate, "recordedAt": fmtTime(recordedAt)})
	return 200, map[string]any{
		"workerId":         s.User.ID,
		"latestLocation":   req.Coordinate,
		"locationRecordedAt": fmtTime(recordedAt),
		"locationSequence": req.LocationSequence,
	}, nil
}

func handleCollectAndSeal(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		SampleID             string   `json:"sampleId"`
		AssignmentID         string   `json:"assignmentId"`
		CollectedAt          string   `json:"collectedAt"`
		ContainerType        string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	sm, err := loadSample(req.SampleID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "sample not found")
	}
	if sm.Sealed {
		return 0, nil, errOf(409, "already_sealed", "sample is already sealed")
	}
	a, err := loadAssignment(req.AssignmentID)
	if err != nil || a.Kind != "collection" || a.SampleID == nil || *a.SampleID != sm.ID {
		return 0, nil, errOf(404, "not_found", "collection assignment not found")
	}
	if a.WorkerID == nil || *a.WorkerID != s.User.ID {
		return 0, nil, errOf(403, "forbidden", "this collection assignment is not accepted by you")
	}
	r, err := loadRequest(sm.RequestID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "request not found")
	}
	st, _ := loadSampleType(r.SampleTypeID)
	if st != nil && st.QualifiedCollectorRequired && !s.User.hasActiveCertification(st.RequiredQualification) {
		return 0, nil, errOf(403, "missing_qualification", "you do not hold the required active qualification for this sample type")
	}
	collectedAt := time.Now()
	if t, ok := parseTime(req.CollectedAt); ok {
		collectedAt = t
	}
	if r.Earliest != nil && collectedAt.Before(*r.Earliest) {
		return 0, nil, errOf(409, "outside_collection_window", "collection is before the start of the collection window")
	}
	if r.Latest != nil && collectedAt.After(*r.Latest) {
		return 0, nil, errOf(409, "outside_collection_window", "collection is after the end of the collection window")
	}
	compliant := true
	if st != nil {
		if req.ContainerType != "" && st.ContainerType != "" && req.ContainerType != st.ContainerType {
			compliant = false
		}
		if req.ObservedTemperatureC != nil && (*req.ObservedTemperatureC < st.TemperatureMinC || *req.ObservedTemperatureC > st.TemperatureMaxC) {
			compliant = false
		}
	}
	if !compliant {
		flagSampleException(sm.ID, "handling_noncompliant", "container or temperature outside required range at collection")
		return 0, nil, errOf(400, "handling_noncompliant", "container or temperature does not comply with the sample's handling rules")
	}
	db.Exec(`UPDATE samples SET sealed=true, sealed_at=$1, status='sealed', current_holder_id=$2, location_recorded_at=$1 WHERE id=$3`, collectedAt, s.User.ID, sm.ID)
	db.Exec(`UPDATE assignments SET status='completed', progress_status='completed', updated_at=now() WHERE id=$1`, a.ID)
	recordAudit(s.User.ID, s.ActiveRole, "sample_collected", "sample", sm.ID, true, map[string]any{"collectedAt": fmtTime(collectedAt)})
	recordAudit(s.User.ID, s.ActiveRole, "sample_sealed", "sample", sm.ID, true, map[string]any{"sealedAt": fmtTime(collectedAt)})
	publishEvent("sample_status", "sample", sm.ID, "", map[string]any{"status": "sealed"})
	return 201, map[string]any{
		"sampleId":           sm.ID,
		"status":             "sealed",
		"sealed":             true,
		"sealedAt":           fmtTime(collectedAt),
		"handlingCompliant":  true,
		"currentHolderId":    s.User.ID,
	}, nil
}

func handleRecordCheckpoint(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		SampleID             string   `json:"sampleId"`
		AssignmentID         *string  `json:"assignmentId"`
		LocationID           *string  `json:"locationId"`
		ContainerType        string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
		RecordedAt           string   `json:"recordedAt"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	sm, err := loadSample(req.SampleID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "sample not found")
	}
	if sm.CurrentHolderID == nil || *sm.CurrentHolderID != s.User.ID {
		return 0, nil, errOf(409, "not_current_holder", "only the current holder may record a handling checkpoint")
	}
	r, _ := loadRequest(sm.RequestID)
	st, _ := loadSampleType(r.SampleTypeID)
	recordedAt := time.Now()
	if t, ok := parseTime(req.RecordedAt); ok {
		recordedAt = t
	}
	compliant := true
	if st != nil {
		if req.ContainerType != "" && st.ContainerType != "" && req.ContainerType != st.ContainerType {
			compliant = false
		}
		if req.ObservedTemperatureC != nil && (*req.ObservedTemperatureC < st.TemperatureMinC || *req.ObservedTemperatureC > st.TemperatureMaxC) {
			compliant = false
		}
	}
	checkpointID := newUUID()
	db.Exec(`INSERT INTO checkpoints (id, sample_id, assignment_id, location_id, container_type, observed_temperature_c, compliant, recorded_by, recorded_at) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		checkpointID, sm.ID, req.AssignmentID, req.LocationID, req.ContainerType, req.ObservedTemperatureC, compliant, s.User.ID, recordedAt)
	recordAudit(s.User.ID, s.ActiveRole, "handling_checkpoint", "sample", sm.ID, true, map[string]any{"checkpointId": checkpointID, "compliant": compliant, "containerType": req.ContainerType, "observedTemperatureC": req.ObservedTemperatureC})
	if !compliant {
		flagSampleException(sm.ID, "handling_noncompliant", "observed container or temperature outside the required range")
	}
	return 201, map[string]any{
		"checkpointId":        checkpointID,
		"sampleId":            sm.ID,
		"compliant":           compliant,
		"recordedAt":          fmtTime(recordedAt),
	}, nil
}
"}

