func handleLabReceipt(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		SampleID             string   `json:"sampleId"`
		ReceivedAt           string   `json:"receivedAt"`
		ContainerType        string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	sm, err := loadSample(req.SampleID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "sample not found")
	}
	if sm.Status == "received" {
		return 0, nil, errOf(409, "already_received", "sample was already received")
	}
	if s.User.AssignedLocationID == nil {
		return 0, nil, errOf(403, "laboratory_not_assigned", "you are not assigned to a laboratory")
	}
	if sm.TargetLaboratoryID == nil || *sm.TargetLaboratoryID != *s.User.AssignedLocationID {
		return 0, nil, errOf(403, "laboratory_not_assigned", "this sample is not routed to your laboratory")
	}
	if sm.Status != "at_laboratory" && sm.Status != "in_transit" && sm.Status != "exception" {
		return 0, nil, errOf(409, "invalid_assignment_state", "sample has not arrived at the laboratory (status: "+sm.Status+")")
	}
	r, _ := loadRequest(sm.RequestID)
	receivedAt := time.Now()
	if t, ok := parseTime(req.ReceivedAt); ok {
		receivedAt = t
	}
	if receivedAt.After(r.DeliveryDeadline) {
		db.Exec(`UPDATE samples SET status='expired', exception=$1 WHERE id=$2`, mustJSON(map[string]any{
			"type": "delivery_deadline_exceeded", "code": "delivery_deadline_exceeded",
			"note": "sample arrived after its delivery deadline", "flaggedAt": fmtTime(time.Now()),
		}), sm.ID)
		recordAudit(s.User.ID, s.ActiveRole, "laboratory_receipt_rejected", "sample", sm.ID, false, map[string]any{"reason": "delivery_deadline_exceeded"})
		return 0, nil, errOf(409, "delivery_deadline_exceeded", "sample arrived after its delivery deadline")
	}
	db.Exec(`UPDATE samples SET status='received', received_at=$1, received_laboratory_id=$2, current_holder_id=$3, location_recorded_at=$1 WHERE id=$4`,
		receivedAt, *s.User.AssignedLocationID, s.User.ID, sm.ID)
	if sm.ActiveJourneyID != nil {
		j, err := loadJourney(*sm.ActiveJourneyID)
		if err == nil {
			releaseJourneyCapacity(j, isCooledJourney(sm))
			db.Exec(`UPDATE journeys SET status='completed' WHERE id=$1`, j.ID)
			db.Exec(`UPDATE assignments SET status='completed', updated_at=now() WHERE journey_id=$1 AND kind='laboratory' AND status IN ('offered','accepted','in_progress','pending')`, j.ID)
		}
	}
	recordAudit(s.User.ID, s.ActiveRole, "laboratory_receipt", "sample", sm.ID, true, map[string]any{"receivedAt": fmtTime(receivedAt)})
	publishEvent("sample_status", "sample", sm.ID, "", map[string]any{"status": "received"})
	return 200, map[string]any{
		"sampleId":   sm.ID,
		"status":     "received",
		"receivedAt": fmtTime(receivedAt),
	}, nil
}

func isCooledJourney(sm *Sample) bool {
	r, err := loadRequest(sm.RequestID)
	if err != nil {
		return false
	}
	st, err := loadSampleType(r.SampleTypeID)
	if err != nil {
		return false
	}
	return st.RequiresCooledRoute
}

