// currentPositionNode returns the network node where the sample currently is:
// the destination of its last completed transport leg, else the journey entry.
func currentPositionNode(sm *Sample, j *Journey) *string {
	var toID *string
	db.QueryRow(`SELECT to_location_id FROM assignments WHERE journey_id=$1 AND kind='transport' AND status='completed' ORDER BY sequence DESC LIMIT 1`, j.ID).Scan(&toID)
	if toID != nil {
		return toID
	}
	return j.EntryLocationID
}

// replanSample creates a replacement journey for unfinished work of a sample.
func replanSample(sm *Sample, reason string) (*Journey, *apiErr) {
	if sm.ActiveJourneyID == nil {
		return nil, errOf(409, "invalid_assignment_state", "sample has no active journey")
	}
	oldJ, err := loadJourney(*sm.ActiveJourneyID)
	if err != nil {
		return nil, errOf(404, "not_found", "journey not found")
	}
	if oldJ.ReplanStatus != nil && *oldJ.ReplanStatus == "replaced" {
		return nil, errOf(409, "replacement_plan_conflict", "an active replacement plan already exists")
	}
	r, err := loadRequest(sm.RequestID)
	if err != nil {
		return nil, errOf(404, "not_found", "request not found")
	}
	st, _ := loadSampleType(r.SampleTypeID)
	entryNodeID := currentPositionNode(sm, oldJ)
	entry, err := loadLocation(*entryNodeID)
	if err != nil {
		return nil, errOf(404, "not_found", "current position not found")
	}
	plan := evaluateServiceability(entry.Coord, "node", entryNodeID, st, time.Now(), r.DeliveryDeadline)
	if !plan.serviceable {
		if plan.reason == "deadline_unreachable" || plan.reason == "no_route" || plan.reason == "no_accepting_laboratory" {
			db.Exec(`UPDATE samples SET status='expired', exception=$1 WHERE id=$2`, mustJSON(map[string]any{
				"type": "expired", "code": "expired", "note": "no valid route can meet the delivery deadline", "flaggedAt": fmtTime(time.Now()),
			}), sm.ID)
			recordAudit("", "system", "sample_expired", "sample", sm.ID, true, map[string]any{"reason": plan.reason})
			publishEvent("sample_status", "sample", sm.ID, "", map[string]any{"status": "expired"})
		} else {
			flagSampleException(sm.ID, plan.reason, "replanning failed: "+plan.reason)
		}
		return nil, errOf(422, "unserviceable", "no valid replacement plan: "+plan.reason)
	}
	// cancel unfinished assignments on the old journey; completed work is preserved
	db.Exec(`UPDATE assignments SET status='cancelled', updated_at=now() WHERE journey_id=$1 AND status IN ('pending','offered')`, oldJ.ID)
	releaseJourneyCapacity(oldJ, st.RequiresCooledRoute)
	newJ, aerr := createJourney(sm.ID, r, st, &plan, oldJ.RouteMode, false)
	if aerr != nil {
		return nil, aerr
	}
	db.Exec(`UPDATE journeys SET parent_journey_id=$1 WHERE id=$2`, oldJ.ID, newJ.ID)
	db.Exec(`UPDATE journeys SET replan_status='replaced', replacement_plan_id=$1, plan_version=plan_version+1 WHERE id=$2`, newJ.ID, oldJ.ID)
	recordAudit("", "system", "journey_replanned", "journey", oldJ.ID, true, map[string]any{"replacementJourneyId": newJ.ID, "reason": reason})
	publishEvent("journey_updated", "journey", newJ.ID, "dispatcher", map[string]any{"status": "planned", "parentJourneyId": oldJ.ID})
	newJ, _ = loadJourney(newJ.ID)
	return newJ, nil
}

