	recordAudit(s.User.ID, s.ActiveRole, "split_journey", "journey", j.ID, true, map[string]any{"newJourneyId": newJourneyID, "sampleIds": req.SampleIDs})
	newJ, _ := loadJourney(newJourneyID)
	return 201, map[string]any{
		"journeyId":       j.ID,
		"planVersion":     j.PlanVersion + 1,
		"status":          j.Status,
		"sampleIds":       remaining,
		"newJourneyId":    newJourneyID,
		"newSampleIds":    newJ.SampleIDs,
	}, nil
}

func handleMergeJourneys(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	j, err := loadJourney(req.JourneyID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "journey not found")
	}
	if aerr := checkPlanVersion(j, req.ExpectedPlanVersion); aerr != nil {
		return 0, nil, aerr
	}
	if j.Status == "completed" || j.Status == "cancelled" {
		return 0, nil, errOf(409, "journey_completed", "journey is already "+j.Status)
	}
	// validate compatibility of all samples (existing + new)
	allSamples := append(append([]string{}, j.SampleIDs...), req.SampleIDs...)
	typeInfos := map[string]*SampleType{}
	var firstReq *Request
	for _, sid := range allSamples {
		sm, err := loadSample(sid)
		if err != nil {
			return 0, nil, errOf(404, "not_found", "sample not found: "+sid)
		}
		r, _ := loadRequest(sm.RequestID)
		st, _ := loadSampleType(r.SampleTypeID)
		if firstReq == nil {
			firstReq = r
		}
		if !st.BatchingAllowed {
			return 0, nil, errOf(409, "batch_incompatible", "sample type "+st.Name+" must not be batched")
		}
		typeInfos[st.ID] = st
	}
	for _, st := range typeInfos {
		for otherID := range typeInfos {
			if contains(st.IncompatibleSampleTypes, otherID) {
				return 0, nil, errOf(409, "batch_incompatible", "sample types may not travel together")
			}
		}
	}
	// target laboratories must match
	for _, sid := range req.SampleIDs {
		sm, _ := loadSample(sid)
		if sm.TargetLaboratoryID == nil || j.LaboratoryID == nil || *sm.TargetLaboratoryID != *j.LaboratoryID {
			return 0, nil, errOf(409, "incompatible_stops", "samples are routed to different laboratories")
		}
		if sm.ActiveJourneyID != nil && *sm.ActiveJourneyID != j.ID {
			old, err := loadJourney(*sm.ActiveJourneyID)
			if err == nil {
				db.Exec(`UPDATE assignments SET status='cancelled', updated_at=now() WHERE journey_id=$1 AND sample_id=$2 AND status IN ('pending','offered')`, old.ID, sid)
				db.Exec(`UPDATE journeys SET sample_ids=$1, plan_version=plan_version+1 WHERE id=$2`, mustJSON(removeStr(old.SampleIDs, sid)), old.ID)
			}
		}
		db.Exec(`UPDATE samples SET active_journey_id=$1 WHERE id=$2`, j.ID, sid)
	}
	merged := append(append([]string{}, j.SampleIDs...), req.SampleIDs...)
	db.Exec(`UPDATE journeys SET sample_ids=$1, route_mode='batched', plan_version=plan_version+1 WHERE id=$2`, mustJSON(merged), j.ID)
	recordAudit(s.User.ID, s.ActiveRole, "merge_journeys", "journey", j.ID, true, map[string]any{"sampleIds": req.SampleIDs})
	j2, _ := loadJourney(j.ID)
	return 201, map[string]any{
		"journeyId":   j2.ID,
		"planVersion": j2.PlanVersion,
		"routeMode":   j2.RouteMode,
		"status":      j2.Status,
		"sampleIds":   j2.SampleIDs,
	}, nil
}

func removeStr(list []string, v string) []string {
	out := []string{}
	for _, x := range list {
		if x != v {
			out = append(out, x)
		}
	}
	return out
}

func handleEditActivePlan(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
