package main

import (
	"encoding/json"
	"io"
	"log"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}

var wsClients = struct {
	sync.Mutex
	conns map[*wsClient]bool
}{conns: map[*wsClient]bool{}}

type wsClient struct {
	conn *websocket.Conn
	user *User
	send chan []byte
}

func wsBroadcaster() {
	ticker := time.NewTicker(2 * time.Second)
	defer ticker.Stop()
	var cursor int64
	for range ticker.C {
		rows, err := db.Query(`SELECT id, type, entity_type, entity_id, payload, created_at FROM events WHERE id > $1 ORDER BY id LIMIT 500`, cursor)
		if err != nil {
			continue
		}
		var batch [][]byte
		for rows.Next() {
			var id int64
			var typ, et, eid string
			var payload []byte
			var at time.Time
			rows.Scan(&id, &typ, &et, &eid, &payload, &at)
			var p map[string]any
			json.Unmarshal(payload, &p)
			if p == nil {
				p = map[string]any{}
			}
			msg, _ := json.Marshal(map[string]any{
				"cursor":     strconv.FormatInt(id, 10),
				"type":       typ,
				"entityType": et,
				"entityId":   eid,
				"payload":    p,
				"createdAt":  fmtTime(at),
			})
			batch = append(batch, msg)
			cursor = id
		}
		rows.Close()
		if len(batch) == 0 {
			continue
		}
		wsClients.Lock()
		for c := range wsClients.conns {
			for _, m := range batch {
				select {
				case c.send <- m:
				default:
				}
			}
		}
		wsClients.Unlock()
	}
}

func handleEventsWS(w http.ResponseWriter, r *http.Request) {
	s := getSession(r)
	if s == nil {
		writeErr(w, errOf(401, "unauthorized", "authentication required"))
		return
	}
	if !strings.Contains(strings.ToLower(r.Header.Get("Connection")), "upgrade") {
		// plain GET polling variant
		q := map[string]string{}
		for k := range r.URL.Query() {
			q[k] = r.URL.Query().Get(k)
		}
		status, data, aerr := handleListEvents(s, q)
		if aerr != nil {
			writeErr(w, aerr)
			return
		}
		writeData(w, status, data)
		return
	}
	proto := ""
	for _, p := range strings.Split(r.Header.Get("Sec-WebSocket-Protocol"), ",") {
		p = strings.TrimSpace(p)
		if p != "" {
			proto = p
			break
		}
	}
	hdr := http.Header{}
	if proto != "" {
		hdr.Set("Sec-WebSocket-Protocol", proto)
	}
	conn, err := upgrader.Upgrade(w, r, hdr)
	if err != nil {
		return
	}
	c := &wsClient{conn: conn, user: s.User, send: make(chan []byte, 256)}
	wsClients.Lock()
	wsClients.conns[c] = true
	wsClients.Unlock()
	go func() {
		for m := range c.send {
			if err := c.conn.WriteMessage(websocket.TextMessage, m); err != nil {
				return
			}
		}
	}()
	go func() {
		defer func() {
			wsClients.Lock()
			delete(wsClients.conns, c)
			wsClients.Unlock()
			c.conn.Close()
		}()
		for {
			if _, _, err := c.conn.ReadMessage(); err != nil {
				return
			}
		}
	}()
}

func queryMap(r *http.Request) map[string]string {
	q := map[string]string{}
	for k := range r.URL.Query() {
		q[k] = r.URL.Query().Get(k)
	}
	return q
}

func readiness(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		writeJSON(w, 503, map[string]any{"status": "unavailable"})
		return
	}
	writeJSON(w, 200, map[string]any{"status": "ready"})
}

func spaHandler(dist string) http.Handler {
	fs := http.FileServer(http.Dir(dist))
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		p := dist + r.URL.Path
		if st, err := os.Stat(p); err == nil && !st.IsDir() {
			fs.ServeHTTP(w, r)
			return
		}
		http.ServeFile(w, r, dist+"/index.html")
	})
}

func main() {
	log.SetOutput(os.Stderr)
	initDB()
	go wsBroadcaster()
	go func() {
		t := time.NewTicker(2 * time.Second)
		for range t.C {
			sweepOffers()
		}
	}()

	mux := http.NewServeMux()
	mux.HandleFunc("GET /ready", readiness)
	mux.HandleFunc("GET /api/ready", readiness)

	mux.HandleFunc("POST /api/authenticate-user", func(w http.ResponseWriter, r *http.Request) {
		body, _ := io.ReadAll(r.Body)
		handleAuthenticate(w, body)
	})
	mux.HandleFunc("POST /api/select-active-role", op("select_active_role", false, handleSelectRole))
	mux.HandleFunc("POST /api/check-serviceability", op("check_serviceability", false, handleCheckServiceability))
	mux.HandleFunc("POST /api/create-collection-request", op("create_collection_request", true, handleCreateCollectionRequest))
	mux.HandleFunc("POST /api/ingest-presealed-sample", op("ingest_presealed_sample", true, handleIngestPresealed))
	mux.HandleFunc("POST /api/collect-and-seal-sample", op("collect_and_seal_sample", true, handleCollectAndSeal))
	mux.HandleFunc("POST /api/accept-assignment", op("accept_assignment", true, handleAcceptAssignment))
	mux.HandleFunc("POST /api/decline-assignment", op("decline_assignment", true, handleDeclineAssignment))
	mux.HandleFunc("POST /api/update-assignment-progress", op("update_assignment_progress", true, handleUpdateProgress))
	mux.HandleFunc("POST /api/record-worker-location", op("record_worker_location", false, handleRecordWorkerLocation))
	mux.HandleFunc("POST /api/initiate-handoff", op("initiate_handoff", true, handleInitiateHandoff))
	mux.HandleFunc("POST /api/confirm-handoff", op("confirm_handoff", true, handleConfirmHandoff))
	mux.HandleFunc("POST /api/record-handling-checkpoint", op("record_handling_checkpoint", true, handleRecordCheckpoint))
	mux.HandleFunc("POST /api/confirm-laboratory-receipt", op("confirm_laboratory_receipt", true, handleLabReceipt))
	mux.HandleFunc("POST /api/record-laboratory-exception", op("record_laboratory_exception", true, handleLabException))
	mux.HandleFunc("POST /api/configure-capacity", op("configure_capacity", false, handleConfigureCapacity))
	mux.HandleFunc("POST /api/configure-laboratory-acceptance", op("configure_laboratory_acceptance", false, handleConfigureLabAcceptance))
	mux.HandleFunc("POST /api/create-location", op("create_location", true, handleCreateLocation))
	mux.HandleFunc("POST /api/update-location", op("update_location", true, handleUpdateLocation))
	mux.HandleFunc("POST /api/create-connection", op("create_connection", true, handleCreateConnection))
	mux.HandleFunc("POST /api/create-sample-type", op("create_sample_type", true, handleCreateSampleType))
	mux.HandleFunc("POST /api/update-sample-type", op("update_sample_type", true, handleUpdateSampleType))
	mux.HandleFunc("POST /api/create-user", op("create_user", true, handleCreateUser))
	mux.HandleFunc("POST /api/update-user-access", op("update_user_access", true, handleUpdateUserAccess))
	mux.HandleFunc("POST /api/set-location-status", op("set_location_status", false, handleSetLocationStatus))
	mux.HandleFunc("POST /api/set-location-function-status", op("set_location_function_status", false, handleSetLocationFunctionStatus))
	mux.HandleFunc("POST /api/set-connection-status", op("set_connection_status", false, handleSetConnectionStatus))
	mux.HandleFunc("POST /api/set-worker-availability", op("set_worker_availability", false, handleSetWorkerAvailability))
	mux.HandleFunc("POST /api/cancel-journey", op("cancel_journey", true, handleCancelJourney))
	mux.HandleFunc("POST /api/reroute-journey", op("reroute_journey", true, handleRerouteJourney))
	mux.HandleFunc("POST /api/split-journey", op("split_journey", true, handleSplitJourney))
	mux.HandleFunc("POST /api/merge-journeys", op("merge_journeys", true, handleMergeJourneys))
	mux.HandleFunc("POST /api/edit-active-plan", op("edit_active_plan", true, handleEditActivePlan))
	mux.HandleFunc("POST /api/report-disruption", op("report_disruption", true, handleReportDisruption))

	mux.HandleFunc("GET /api/ui/bootstrap", func(w http.ResponseWriter, r *http.Request) {
		s := getSession(r)
		if s == nil {
			writeErr(w, errOf(401, "unauthorized", "authentication required"))
			return
		}
		status, data, aerr := handleBootstrap(s, nil)
		if aerr != nil {
			writeErr(w, aerr)
			return
		}
		writeData(w, status, data)
	})
	mux.HandleFunc("GET /api/list-role-work", func(w http.ResponseWriter, r *http.Request) {
		s := getSession(r)
		if s == nil {
			writeErr(w, errOf(401, "unauthorized", "authentication required"))
			return
		}
		if s.ActiveRole == "" {
			writeErr(w, errOf(409, "role_not_selected", "an active role must be selected"))
			return
		}
		status, data, aerr := handleListRoleWork(s, r.URL.Query().Get("role"))
		if aerr != nil {
			writeErr(w, aerr)
			return
		}
		writeData(w, status, data)
	})
	mux.HandleFunc("GET /api/read-sample-state/{sampleId}", func(w http.ResponseWriter, r *http.Request) {
		getWrap(w, r, "read_sample_state", func(s *session) (int, any, *apiErr) {
			return handleReadSampleState(s, r.PathValue("sampleId"))
		})
	})
	mux.HandleFunc("GET /api/read-sample-lifecycle/{sampleId}", func(w http.ResponseWriter, r *http.Request) {
		getWrap(w, r, "read_sample_lifecycle", func(s *session) (int, any, *apiErr) {
			return handleReadSampleLifecycle(s, r.PathValue("sampleId"))
		})
	})
	mux.HandleFunc("GET /api/read-journey-plan/{journeyId}", func(w http.ResponseWriter, r *http.Request) {
		getWrap(w, r, "read_journey_plan", func(s *session) (int, any, *apiErr) {
			return handleReadJourneyPlan(s, r.PathValue("journeyId"))
		})
	})
	mux.HandleFunc("GET /api/read-user/{userId}", func(w http.ResponseWriter, r *http.Request) {
		getWrap(w, r, "read_user", func(s *session) (int, any, *apiErr) {
			return handleReadUser(s, r.PathValue("userId"))
		})
	})
	mux.HandleFunc("GET /api/read-operations-state", func(w http.ResponseWriter, r *http.Request) {
		getWrap(w, r, "read_operations_state", func(s *session) (int, any, *apiErr) {
			return handleReadOperationsState(s)
		})
	})
	mux.HandleFunc("GET /api/read-serviceability-snapshot", func(w http.ResponseWriter, r *http.Request) {
		getWrap(w, r, "read_serviceability_snapshot", func(s *session) (int, any, *apiErr) {
			return handleReadServiceabilitySnapshot(s)
		})
	})
	mux.HandleFunc("GET /api/search-audit-trail", func(w http.ResponseWriter, r *http.Request) {
		getWrap(w, r, "search_audit_trail", func(s *session) (int, any, *apiErr) {
			return handleSearchAudit(s, queryMap(r))
		})
	})
	mux.HandleFunc("GET /api/events", handleEventsWS)

	mux.Handle("/map-assets/", http.StripPrefix("/map-assets/", http.FileServer(http.Dir("/workspace/map-assets"))))

	dist := getenv("WEB_DIST", "/workspace/web/dist")
	mux.Handle("/", spaHandler(dist))

	addr := ":" + getenv("PORT", "8080")
	log.Printf("listening on %s", addr)
	log.Fatal(http.ListenAndServe(addr, mux))
}

func getWrap(w http.ResponseWriter, r *http.Request, name string, h func(s *session) (int, any, *apiErr)) {
	s := getSession(r)
	if s == nil {
		writeErr(w, errOf(401, "unauthorized", "authentication required"))
		return
	}
	if s.ActiveRole == "" {
		writeErr(w, errOf(409, "role_not_selected", "an active role must be selected"))
		return
	}
	if !roleAllowed(name, s.ActiveRole) {
		writeErr(w, errOf(403, "forbidden", "your active role may not perform this action"))
		return
	}
	status, data, aerr := h(s)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	writeData(w, status, data)
}

