package main

import (
	"encoding/json"
	"io"
	"log"
	"net/http"
	"os"
	"strconv"
	"strings"
	"sync"
	"time"

	"github.com/gorilla/websocket"
)

var upgrader = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}

var wsClients = struct {
	sync.Mutex
	conns map[*wsClient]bool
}{conns: map[*wsClient]bool{}}

type wsClient struct {
	conn *websocket.Conn
	user *User
	send chan []byte
}

func wsBroadcaster() {
	ticker := time.NewTicker(2 * time.Second)
	defer ticker.Stop()
	var cursor int64
	for range ticker.C {
		rows, err := db.Query(`SELECT id, type, entity_type, entity_id, payload, created_at FROM events WHERE id > $1 ORDER BY id LIMIT 500`, cursor)
		if err != nil {
			continue
		}
		var batch [][]byte
		for rows.Next() {
			var id int64
			var typ, et, eid string
			var payload []byte
			var at time.Time
			rows.Scan(&id, &typ, &et, &eid, &payload, &at)
			var p map[string]any
			json.Unmarshal(payload, &p)
			if p == nil {
				p = map[string]any{}
			}
			msg, _ := json.Marshal(map[string]any{
				"cursor":     strconv.FormatInt(id, 10),
				"type":       typ,
				"entityType": et,
				"entityId":   eid,
				"payload":    p,
				"createdAt":  fmtTime(at),
			})
			batch = append(batch, msg)
			cursor = id
		}
		rows.Close()
		if len(batch) == 0 {
			continue
		}
		wsClients.Lock()
		for c := range wsClients.conns {
			for _, m := range batch {
				select {
				case c.send <- m:
				default:
				}
			}
		}
		wsClients.Unlock()
	}
}

func handleEventsWS(w http.ResponseWriter, r *http.Request) {
	s := getSession(r)
	if s == nil {
		writeErr(w, errOf(401, "unauthorized", "authentication required"))
		return
	}
	if !strings.Contains(strings.ToLower(r.Header.Get("Connection")), "upgrade") {
		// plain GET polling variant
		q := map[string]string{}
		for k := range r.URL.Query() {
			q[k] = r.URL.Query().Get(k)
		}
		status, data, aerr := handleListEvents(s, q)
		if aerr != nil {
			writeErr(w, aerr)
			return
		}
		writeData(w, status, data)
		return
	}
	proto := ""
	for _, p := range strings.Split(r.Header.Get("Sec-WebSocket-Protocol"), ",") {
		p = strings.TrimSpace(p)
		if p != "" {
			proto = p
			break
		}
	}
	hdr := http.Header{}
	if proto != "" {
		hdr.Set("Sec-WebSocket-Protocol", proto)
	}
	conn, err := upgrader.Upgrade(w, r, hdr)
	if err != nil {
		return
	}
	c := &wsClient{conn: conn, user: s.User, send: make(chan []byte, 256)}
	wsClients.Lock()
	wsClients.conns[c] = true
	wsClients.Unlock()
	go func() {
		for m := range c.send {
			if err := c.conn.WriteMessage(websocket.TextMessage, m); err != nil {
				return
			}
		}
	}()
	go func() {
		defer func() {
			wsClients.Lock()
			delete(wsClients.conns, c)
			wsClients.Unlock()
			c.conn.Close()
		}()
		for {
			if _, _, err := c.conn.ReadMessage(); err != nil {
				return
			}
		}
	}()
}

func queryMap(r *http.Request) map[string]string {
	q := map[string]string{}
	for k := range r.URL.Query() {
		q[k] = r.URL.Query().Get(k)
	}
	return q
}

func readiness(w http.ResponseWriter, r *http.Request) {
