var validRoles = []string{"administrator", "dispatcher", "requester", "collection_professional", "delivery_partner", "node_handler", "laboratory_team"}

func handleAuthenticate(w http.ResponseWriter, body []byte) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		writeErr(w, errOf(400, "invalid_json", "invalid request body"))
		return
	}
	var u User
	var roles []byte
	err := db.QueryRow(`SELECT id, username, password_hash, roles, active FROM users WHERE username=$1`, req.Username).Scan(&u.ID, &u.Username, &u.PasswordHash, &roles, &u.Active)
	if err != nil || !u.Active {
		recordAudit("", "", "sign_in", "user", "", false, map[string]any{"username": req.Username})
		writeErr(w, errOf(401, "invalid_credentials", "invalid username or password"))
		return
	}
	parts := strings.Split(u.PasswordHash, ":")
	if len(parts) != 2 || hashPassword(req.Password, parts[1]) != parts[0] {
		recordAudit(u.ID, "", "sign_in", "user", u.ID, false, map[string]any{"username": req.Username})
		writeErr(w, errOf(401, "invalid_credentials", "invalid username or password"))
		return
	}
	json.Unmarshal(roles, &u.Roles)
	token := randomToken()
	activeRole := ""
	if len(u.Roles) == 1 {
		activeRole = u.Roles[0]
	}
	if activeRole == "" {
		db.Exec(`INSERT INTO sessions (token, user_id, active_role) VALUES ($1,$2,NULL)`, token, u.ID)
	} else {
		db.Exec(`INSERT INTO sessions (token, user_id, active_role) VALUES ($1,$2,$3)`, token, u.ID, activeRole)
	}
	recordAudit(u.ID, activeRole, "sign_in", "user", u.ID, true, map[string]any{"username": req.Username})
	writeData(w, 200, map[string]any{
		"sessionToken": token,
		"userId":       u.ID,
		"roles":        u.Roles,
		"activeRole":   activeRole,
	})
}

func handleSelectRole(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		Role string `json:"role"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	if !contains(validRoles, req.Role) {
		return 0, nil, errOf(400, "invalid_role", "unknown role")
	}
	if !contains(s.User.Roles, req.Role) {
		return 0, nil, errOf(403, "role_not_held", "you do not hold this role")
	}
	db.Exec(`UPDATE sessions SET active_role=$1 WHERE token=$2`, req.Role, s.Token)
	recordAudit(s.User.ID, req.Role, "select_role", "user", s.User.ID, true, map[string]any{"role": req.Role})
	return 200, map[string]any{"activeRole": req.Role, "roles": s.User.Roles}, nil
}

