		req.Qualifications = u.Qualifications
	}
	db.Exec(`UPDATE users SET roles=$1, qualifications=$2, certifications=$3, active=$4, assigned_location_id=$5 WHERE id=$6`,
		mustJSON(req.Roles), mustJSON(req.Qualifications), mustJSON(req.Certifications), req.Active, req.AssignedLocationID, u.ID)
	recordAudit(s.User.ID, s.ActiveRole, "update_user_access", "user", u.ID, true, map[string]any{"roles": req.Roles, "active": req.Active})
	u, _ = loadUser(u.ID)
	return 201, map[string]any{
		"userId":         u.ID,
		"roles":          u.Roles,
		"qualifications": u.Qualifications,
		"certifications": u.Certifications,
		"active":         u.Active,
	}, nil
}

func handleReadUser(s *session, userID string) (int, any, *apiErr) {
	u, err := loadUser(userID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "user not found")
	}
	return 200, userJSON(u), nil
}

func handleSetWorkerAvailability(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		WorkerID      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits int    `json:"capacityUnits"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	if req.CapacityUnits < 0 {
		return 0, nil, errOf(400, "invalid_capacity", "capacityUnits must be non-negative")
	}
	u, err := loadUser(req.WorkerID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "worker not found")
	}
	if u.ID != s.User.ID && s.ActiveRole != "dispatcher" && s.ActiveRole != "administrator" {
		return 0, nil, errOf(403, "forbidden", "you may only change your own availability")
	}
	if !req.Available {
		var active int
		db.QueryRow(`SELECT count(*) FROM assignments WHERE worker_id=$1 AND status IN ('accepted','in_progress')`, u.ID).Scan(&active)
		if active > 0 {
			return 0, nil, errOf(409, "capacity_reserved", "worker has active assignments")
		}
	}
	db.Exec(`UPDATE users SET available=$1, capacity_units=$2 WHERE id=$3`, req.Available, req.CapacityUnits, u.ID)
	recordAudit(s.User.ID, s.ActiveRole, "set_worker_availability", "user", u.ID, true, map[string]any{"available": req.Available, "capacityUnits": req.CapacityUnits})
	publishEvent("worker_availability", "user", u.ID, "dispatcher", map[string]any{"available": req.Available})
	return 200, map[string]any{"workerId": u.ID, "available": req.Available, "capacityUnits": req.CapacityUnits}, nil
}

