export interface ApiError {
  code: string;
  message: string;
  status: number;
}

let token: string | null = localStorage.getItem("sessionToken");

export function setToken(t: string | null) {
  token = t;
  if (t) localStorage.setItem("sessionToken", t);
  else localStorage.removeItem("sessionToken");
}

export function getToken() {
  return token;
}

async function request(method: string, path: string, body?: unknown): Promise<any> {
  const headers: Record<string, string> = {};
  if (token) headers["Authorization"] = `Bearer ${token}`;
  if (body !== undefined) headers["Content-Type"] = "application/json";
  const res = await fetch(path, {
    method,
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  let json: any = null;
  try {
    json = await res.json();
  } catch {
    /* empty */
  }
  if (!res.ok) {
    const err: ApiError = {
      status: res.status,
      code: json?.error?.code ?? "error",
      message: json?.error?.message ?? `Request failed (${res.status})`,
    };
    throw err;
  }
  return json?.data ?? json;
}

export const api = {
  login: (username: string, password: string) =>
    request("POST", "/api/authenticate-user", { username, password }),
  selectRole: (role: string) => request("POST", "/api/select-active-role", { role }),
  bootstrap: () => request("GET", "/api/ui/bootstrap"),
  listRoleWork: (role?: string) => request("POST", "/api/list-role-work", role ? { role } : {}),
  sampleState: (sampleId: string) => request("GET", `/api/read-sample-state/${sampleId}`),
  sampleLifecycle: (sampleId: string) => request("POST", "/api/read-sample-lifecycle", { sampleId }),
  journeyPlan: (journeyId: string) => request("POST", "/api/read-journey-plan", { journeyId }),
  operationsState: () => request("POST", "/api/read-operations-state", {}),
  serviceabilitySnapshot: () => request("POST", "/api/read-serviceability-snapshot", {}),
  searchAudit: (params: Record<string, unknown>) => request("POST", "/api/search-audit-trail", params),
  checkServiceability: (payload: unknown) => request("POST", "/api/check-serviceability", payload),
  createRequest: (payload: unknown) => request("POST", "/api/create-collection-request", payload),
  acceptAssignment: (assignmentId: string) =>
    request("POST", "/api/accept-assignment", { assignmentId, idempotencyKey: crypto.randomUUID() }),
  declineAssignment: (assignmentId: string, reason?: string) =>
    request("POST", "/api/decline-assignment", { assignmentId, reason }),
  collectAndSeal: (payload: unknown) =>
    request("POST", "/api/collect-and-seal-sample", { ...(payload as object), idempotencyKey: crypto.randomUUID() }),
  updateProgress: (payload: unknown) => request("POST", "/api/update-assignment-progress", payload),
  recordLocation: (payload: unknown) => request("POST", "/api/record-worker-location", payload),
  initiateHandoff: (payload: unknown) =>
    request("POST", "/api/initiate-handoff", { ...(payload as object), idempotencyKey: crypto.randomUUID() }),
  confirmHandoff: (payload: unknown) => request("POST", "/api/confirm-handoff", payload),
  recordCheckpoint: (payload: unknown) => request("POST", "/api/record-handling-checkpoint", payload),
  confirmReceipt: (payload: unknown) =>
    request("POST", "/api/confirm-laboratory-receipt", { ...(payload as object), idempotencyKey: crypto.randomUUID() }),
  configureCapacity: (payload: unknown) => request("POST", "/api/configure-capacity", payload),
  setAvailability: (available: boolean) => request("POST", "/api/set-worker-availability", { available }),
};

