table { border-collapse: collapse; width: 100%; font-size: 13px; }
th, td { text-align: left; padding: 6px 8px; border-bottom: 1px solid #e3e9ee; }
th { background: #eef3f7; }
.tabs { display: flex; gap: 4px; margin-bottom: 12px; }
.tabs button { border-radius: 4px 4px 0 0; }
.tabs button.active { background: #12395b; color: #fff; }
.badge { display: inline-block; padding: 2px 8px; border-radius: 10px; font-size: 11px; font-weight: 600; }
.badge.stale { background: #ffecb3; color: #8d6e00; }
.badge.fresh { background: #c8e6c9; color: #1b5e20; }
.badge.exception { background: #ffcdd2; color: #b71c1c; }
.badge.role { background: #2e5f8a; color: #fff; }
.timeline { list-style: none; padding-left: 0; }
.timeline li { border-left: 3px solid #1d6fb8; padding: 4px 12px; margin-bottom: 8px; background: #f7fafc; }
.timeline li.failure { border-left-color: #b3261e; }
.form-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(220px, 1fr)); gap: 10px; }
.form-grid label { display: flex; flex-direction: column; font-size: 12px; gap: 4px; }
.login-box { max-width: 360px; margin: 80px auto; }
.login-box .card { padding: 24px; }
.login-box input { width: 100%; margin-bottom: 10px; }
.login-box button { width: 100%; }
.map-container { height: 420px; border: 1px solid #dde4ea; border-radius: 6px; overflow: hidden; }
.section-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 16px; }
.muted { color: #6b7a85; font-size: 12px; }
.row { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; }

import { useEffect, useRef } from "react";
import maplibregl from "maplibre-gl";
import { Protocol } from "pmtiles";
import "maplibre-gl/dist/maplibre-gl.css";

const protocol = new Protocol();
maplibregl.addProtocol("pmtiles", protocol.tile);

export interface MapMarker {
  id: string;
  lng: number;
  lat: number;
  label: string;
  color?: string;
}

export default function MapView({ markers }: { markers: MapMarker[] }) {
  const ref = useRef<HTMLDivElement>(null);
  const mapRef = useRef<maplibregl.Map | null>(null);
  const markersRef = useRef<maplibregl.Marker[]>([]);

  useEffect(() => {
    if (!ref.current || mapRef.current) return;
    const map = new maplibregl.Map({
      container: ref.current,
      style: "/map-assets/style.json",
      center: [77.5946, 12.9716],
      zoom: 10,
    });
    map.addControl(new maplibregl.NavigationControl());
    mapRef.current = map;
    return () => {
      map.remove();
      mapRef.current = null;
    };
  }, []);

  useEffect(() => {
    const map = mapRef.current;
    if (!map) return;
    markersRef.current.forEach((m) => m.remove());
    markersRef.current = markers.map((mk) =>
      new maplibregl.Marker({ color: mk.color ?? "#1d6fb8" })
        .setLngLat([mk.lng, mk.lat])
        .setPopup(new maplibregl.Popup().setText(mk.label))
        .addTo(map)
    );
  }, [markers]);

  return <div className="map-container" ref={ref} aria-label="Live network map" />;
}

