	}
	if len(loc) > 0 {
		var c Coordinate
		if json.Unmarshal(loc, &c) == nil {
			u.LatestLocation = &c
		}
	}
	return &u, nil
}

func (u *User) hasActiveCertification(code string) bool {
	if code == "" {
		return true
	}
	for _, c := range u.Certifications {
		cCode, _ := c["code"].(string)
		active, _ := c["active"].(bool)
		if cCode == code && active {
			if exp, ok := c["expiresAt"].(string); ok && exp != "" {
				if t, ok2 := parseTime(exp); ok2 && t.Before(time.Now()) {
					continue
				}
			}
			return true
		}
	}
	// fall back to qualifications list
	return contains(u.Qualifications, code)
}

