		j.Stops = []map[string]any{}
	}
	if j.Legs == nil {
		j.Legs = []map[string]any{}
	}
	return &j, nil
}

type Assignment struct {
	ID                 string
	JourneyID          *string
	SampleID           *string
	Kind               string
	Sequence           int
	FromLocationID     *string
	ToLocationID       *string
	NodeID             *string
	LaboratoryID       *string
	WorkerID           *string
	OfferedTo          *string
	OfferedAt          *time.Time
	OfferExpiresAt     *time.Time
	DeclinedBy         []string
	Status             string
	ProgressStatus     *string
	Location           *Coordinate
	LocationRecordedAt *time.Time
	LocationSequence   int
}

func scanAssignment(row interface{ Scan(...any) error }) (*Assignment, error) {
	var a Assignment
	var decl, loc []byte
	err := row.Scan(&a.ID, &a.JourneyID, &a.SampleID, &a.Kind, &a.Sequence, &a.FromLocationID, &a.ToLocationID, &a.NodeID, &a.LaboratoryID, &a.WorkerID, &a.OfferedTo, &a.OfferedAt, &a.OfferExpiresAt, &decl, &a.Status, &a.ProgressStatus, &loc, &a.LocationRecordedAt, &a.LocationSequence)
	if err != nil {
		return nil, err
	}
	a.DeclinedBy = strSlice(decl)
	if len(loc) > 0 {
		var c Coordinate
		if json.Unmarshal(loc, &c) == nil {
			a.Location = &c
		}
	}
	return &a, nil
}

const assignmentCols = `id, journey_id, sample_id, kind, sequence, from_location_id, to_location_id, node_id, laboratory_id, worker_id, offered_to, offered_at, offer_expires_at, declined_by, status, progress_status, location, location_recorded_at, location_sequence`

func loadAssignment(id string) (*Assignment, error) {
	return scanAssignment(db.QueryRow(`SELECT `+assignmentCols+` FROM assignments WHERE id=$1`, id))
}

