function CapacityCard({
  refresh,
  onError,
}: {
  refresh: () => Promise<void>;
  onError: (m: string | null) => void;
}) {
  const [locations, setLocations] = useState<any[]>([]);
  const [locId, setLocId] = useState("");
  const [regular, setRegular] = useState("0");
  const [cooled, setCooled] = useState("0");
  useEffect(() => {
    api
      .operationsState()
      .then((d) => {
        const locs = d.data?.locations ?? [];
        setLocations(locs);
        if (locs.length && !locId) setLocId(locs[0].locationId);
      })
      .catch(() => {});
  }, []);
  const loc = locations.find((l) => l.locationId === locId);
  useEffect(() => {
    if (loc) {
      setRegular(String(loc.capacityUnits ?? 0));
      setCooled(String(loc.cooledCapacityUnits ?? 0));
    }
  }, [locId, locations]);
  if (!locations.length) return null;
  return (
    <section className="card">
      <h2>Location capacity</h2>
      <div className="form">
        <label>
          Location
          <select value={locId} onChange={(e) => setLocId(e.target.value)}>
            {locations.map((l) => (
              <option key={l.locationId} value={l.locationId}>
                {l.name}
              </option>
            ))}
          </select>
        </label>
        <label>
          Regular units
          <input value={regular} onChange={(e) => setRegular(e.target.value)} />
        </label>
        <label>
          Cooled units
          <input value={cooled} onChange={(e) => setCooled(e.target.value)} />
        </label>
        <button
          onClick={() =>
            api
              .configureCapacity(locId, {
                capacityUnits: Number(regular),
                cooledCapacityUnits: Number(cooled),
              })
              .then(refresh)
              .catch((e) => onError(e.message))
          }
        >
          Save capacity
        </button>
      </div>
    </section>
  );
}

