let token: string | null = localStorage.getItem("sessionToken");

export function setToken(t: string | null) {
  token = t;
  if (t) localStorage.setItem("sessionToken", t);
  else localStorage.removeItem("sessionToken");
}

export function getToken() {
  return token;
}

async function request(method: string, path: string, body?: unknown): Promise<any> {
  const headers: Record<string, string> = {};
  if (token) headers["Authorization"] = `Bearer ${token}`;
  if (body !== undefined) headers["Content-Type"] = "application/json";
  const res = await fetch(path, {
    method,
    headers,
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  let json: any = null;
  try {
    json = await res.json();
  } catch {
    /* empty */
  }
  if (!res.ok) {
    const code = json?.error?.code ?? json?.code ?? "error";
    const message =
      json?.error?.message ?? (typeof json?.error === "string" ? json.error : null) ?? `Request failed (${res.status})`;
    const err: ApiError = { status: res.status, code, message };
    throw err;
  }
  return json?.data ?? json;
}

