func canSeeSample(s *session, sm *Sample) bool {
	role := s.ActiveRole
	if role == "dispatcher" || role == "administrator" {
		return true
	}
	if role == "requester" {
		return sm.RequesterID == s.User.ID
	}
	// workers: involved via an assignment or custody
	if sm.CurrentHolderID != nil && *sm.CurrentHolderID == s.User.ID {
		return true
	}
	var n int
	db.QueryRow(`SELECT count(*) FROM assignments WHERE sample_id=$1 AND (worker_id=$2 OR offered_to=$2)`, sm.ID, s.User.ID).Scan(&n)
	return n > 0
}

func handleReadSampleState(s *session, sampleID string) (int, any, *apiErr) {
	sm, err := loadSample(sampleID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "sample not found")
	}
	if !canSeeSample(s, sm) {
		return 0, nil, errOf(403, "forbidden", "you may not view this sample")
	}
	return 200, sampleStateJSON(sm), nil
}

func handleReadSampleLifecycle(s *session, sampleID string) (int, any, *apiErr) {
	sm, err := loadSample(sampleID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "sample not found")
	}
	if !canSeeSample(s, sm) {
		return 0, nil, errOf(403, "forbidden", "you may not view this sample")
	}
	rows, err := db.Query(`SELECT id, action, role, success, occurred_at, details FROM audit_log WHERE entity_type='sample' AND entity_id=$1 ORDER BY id`, sampleID)
	if err != nil {
		return 0, nil, errOf(500, "internal_error", err.Error())
	}
	defer rows.Close()
	entries := []map[string]any{}
	for rows.Next() {
		var id int64
		var action, role string
		var success bool
		var at time.Time
		var details []byte
		rows.Scan(&id, &action, &role, &success, &at, &details)
		var det map[string]any
		json.Unmarshal(details, &det)
		if det == nil {
			det = map[string]any{}
		}
		entries = append(entries, map[string]any{
			"eventId":    id,
			"action":     action,
			"role":       role,
			"success":    success,
			"occurredAt": fmtTime(at),
			"details":    det,
		})
	}
	return 200, map[string]any{"sampleId": sampleID, "entries": entries}, nil
}

