func handleListRoleWork(s *session, roleFilter string) (int, any, *apiErr) {
	role := s.ActiveRole
	if roleFilter != "" {
		if !contains(s.User.Roles, roleFilter) {
			return 0, nil, errOf(403, "role_not_held", "you do not hold this role")
		}
		role = roleFilter
	}
	pending := []any{}
	inProgress := []any{}
	completed := []any{}
	switch role {
	case "requester":
		rows, _ := db.Query(`SELECT id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, s.User.ID)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var id string
	 			rows.Scan(&id)
				sm, err := loadSample(id)
				if err != nil {
					continue
				}
				item := map[string]any{
					"sampleId":         sm.ID,
					"requestId":        sm.RequestID,
					"status":           sm.Status,
					"currentHolderId":  sm.CurrentHolderID,
					"activeJourneyId":  sm.ActiveJourneyID,
					"deliveryDeadline": nil,
				}
				if r, err := loadRequest(sm.RequestID); err == nil {
					item["deliveryDeadline"] = fmtTime(r.DeliveryDeadline)
				}
				switch sm.Status {
				case "created":
					pending = append(pending, item)
				case "received", "cancelled", "expired":
					completed = append(completed, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
		}
	case "dispatcher", "administrator":
		rows, _ := db.Query(`SELECT id FROM journeys ORDER BY created_at DESC LIMIT 200`)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var id string
				rows.Scan(&id)
				j, err := loadJourney(id)
				if err != nil {
					continue
				}
				var holder any
				if len(j.SampleIDs) > 0 {
					if sm, err := loadSample(j.SampleIDs[0]); err == nil && sm.CurrentHolderID != nil {
						holder = *sm.CurrentHolderID
					}
				}
				item := map[string]any{
					"journeyId":       j.ID,
					"planVersion":     j.PlanVersion,
					"routeMode":       j.RouteMode,
					"status":          j.Status,
					"sampleIds":       j.SampleIDs,
					"currentHolderId": holder,
				}
				switch j.Status {
				case "planned":
					pending = append(pending, item)
				case "in_progress":
					inProgress = append(inProgress, item)
				default:
					completed = append(completed, item)
				}
			}
		}
	default:
		// worker roles
		rows, _ := db.Query(`SELECT `+assignmentCols+` FROM assignments WHERE (offered_to=$1 AND status='offered') OR worker_id=$1 ORDER BY updated_at DESC LIMIT 200`, s.User.ID)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				a, err := scanAssignment(rows)
				if err != nil {
					continue
				}
				item := assignmentWorkItemJSON(a)
				switch a.Status {
				case "offered":
					pending = append(pending, item)
				case "accepted", "in_progress":
					inProgress = append(inProgress, item)
				default:
					completed = append(completed, item)
				}
			}
		}
	}
	return 200, map[string]any{
		"role":       role,
		"pending":    pending,
		"inProgress": inProgress,
		"completed":  completed,
	}, nil
}

func handleReadJourneyPlan(s *session, journeyID string) (int, any, *apiErr) {
	j, err := loadJourney(journeyID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "journey not found")
	}
	role := s.ActiveRole
	// access checks
	if role == "requester" {
		ok := false
		for _, sid := range j.SampleIDs {
			if sm, err := loadSample(sid); err == nil && sm.RequesterID == s.User.ID {
				ok = true
			}
		}
		if !ok {
			return 0, nil, errOf(403, "forbidden", "you may not view this journey")
		}
	} else if role != "dispatcher" && role != "administrator" {
		var n int
		db.QueryRow(`SELECT count(*) FROM assignments WHERE journey_id=$1 AND (worker_id=$2 OR offered_to=$2)`, j.ID, s.User.ID).Scan(&n)
		if n == 0 {
			return 0, nil, errOf(403, "forbidden", "you may not view this journey")
		}
	}
	stops := []map[string]any{}
	for _, st := range j.Stops {
		stops = append(stops, map[string]any{
			"stopId":       st["stopId"],
			"sequence":     st["sequence"],
			"kind":         st["kind"],
			"locationId":   st["locationId"],
			"assignmentId": st["assignmentId"],
		})
	}
	legs := []map[string]any{}
	for _, lg := range j.Legs {
		include := true
		if role != "dispatcher" && role != "administrator" && role != "requester" {
			// workers only see their own legs
			include = false
			if aid, ok := lg["assignmentId"].(string); ok {
				if a, err := loadAssignment(aid); err == nil {
					if (a.WorkerID != nil && *a.WorkerID == s.User.ID) || (a.OfferedTo != nil && *a.OfferedTo == s.User.ID) {
						include = true
					}
				}
			}
		}
		if include {
			legs = append(legs, map[string]any{
				"legId":          lg["legId"],
				"sequence":       lg["sequence"],
				"fromLocationId": lg["fromLocationId"],
				"toLocationId":   lg["toLocationId"],
				"assignmentId":   lg["assignmentId"],
			})
		}
	}
	scope := "full"
	if role == "requester" {
		scope = "requester_view"
	} else if role != "dispatcher" && role != "administrator" {
		scope = "assigned_legs"
	}
	return 200, map[string]any{
		"journeyId":           j.ID,
		"parentJourneyId":     j.ParentJourneyID,
		"planVersion":         j.PlanVersion,
		"routeMode":           j.RouteMode,
		"status":              j.Status,
		"sampleIds":           j.SampleIDs,
		"stops":               stops,
		"legs":                legs,
		"estimatedDeliveryAt": nullTime(j.EstimatedDeliveryAt),
		"totalCostUnits":      j.TotalCostUnits,
		"replanStatus":        j.ReplanStatus,
		"replacementPlanId":   j.ReplacementPlanID,
		"scope":               scope,
	}, nil
}

func operationsStateJSON(audienceRole string) map[string]any {
	samples := []any{}
	rows, _ := db.Query(`SELECT id FROM samples ORDER BY created_at DESC LIMIT 500`)
	if rows != nil {
		for rows.Next() {
			var id string
			rows.Scan(&id)
			if sm, err := loadSample(id); err == nil {
				samples = append(samples, opsSampleJSON(sm))
			}
		}
		rows.Close()
	}
	workers := []any{}
	wrows, _ := db.Query(`SELECT id FROM users WHERE roles ?| ARRAY['collection_professional','delivery_partner','node_handler','laboratory_team']`)
	if wrows != nil {
		for wrows.Next() {
			var id string
			wrows.Scan(&id)
			u, err := loadUser(id)
			if err != nil {
				continue
			}
			var active int
			db.QueryRow(`SELECT count(*) FROM assignments WHERE worker_id=$1 AND status IN ('accepted','in_progress')`, u.ID).Scan(&active)
			status := "unavailable"
			if u.Available {
				status = "available"
			}
			w := map[string]any{
				"workerId":           u.ID,
				"fullName":           u.FullName,
				"roles":              u.Roles,
				"available":          u.Available,
				"status":             status,
				"capacityUnits":      1,
				"assignmentCount":    active,
				"locationStale":      staleLocation(u.LocationRecordedAt),
				"locationRecordedAt": nullTime(u.LocationRecordedAt),
			}
			if u.LatestLocation != nil {
				w["latestLocation"] = u.LatestLocation
			}
			workers = append(workers, w)
		}
		wrows.Close()
	}
	locations := []any{}
	for _, l := range loadAllLocations() {
		locations = append(locations, map[string]any{
			"id":             l.ID,
			"locationId":     l.ID,
			"name":           l.Name,
			"coordinate":     l.Coord,
			"active":         l.Active,
			"coverageKm":     l.CoverageKm,
			"handlingMinutes": l.HandlingMinutes,
			"functions": map[string]bool{
				"collection_point": l.Functions["collection_point"],
				"transfer_point":   l.Functions["transfer_point"],
				"hub":              l.Functions["hub"],
				"laboratory":       l.Functions["laboratory"],
			},
			"capacity": capacityJSON(l.CapacityUnits, l.ReservedUnits, l.CooledCapacityUnits, l.CooledReservedUnits),
		})
	}
	connections := []any{}
	for _, c := range loadAllConnections() {
		connections = append(connections, map[string]any{
			"id":             c.ID,
			"connectionId":   c.ID,
			"fromLocationId": c.FromLocationID,
			"toLocationId":   c.ToLocationID,
			"travelMinutes":  c.TravelMinutes,
			"costUnits":      c.CostUnits,
			"cooled":         c.Cooled,
			"active":         c.Active,
			"capacity":       capacityJSON(c.CapacityUnits, c.ReservedUnits, c.CooledCapacityUnits, c.CooledReservedUnits),
		})
	}
	routes := []any{}
	jrows, _ := db.Query(`SELECT id FROM journeys ORDER BY created_at DESC LIMIT 200`)
	if jrows != nil {
		for jrows.Next() {
			var id string
			jrows.Scan(&id)
			if j, err := loadJourney(id); err == nil {
				routes = append(routes, journeySummaryJSON(j))
			}
		}
		jrows.Close()
	}
	handoffs := []any{}
	hrows, _ := db.Query(`SELECT id FROM handoffs ORDER BY created_at DESC LIMIT 100`)
	if hrows != nil {
		for hrows.Next() {
			var id string
			hrows.Scan(&id)
			if h, err := loadHandoff(id); err == nil {
				handoffs = append(handoffs, handoffJSON(h))
			}
		}
		hrows.Close()
	}
	exceptions := []any{}
	erows, _ := db.Query(`SELECT id FROM samples WHERE exception IS NOT NULL AND status IN ('exception','expired') ORDER BY created_at DESC LIMIT 100`)
	if erows != nil {
		for erows.Next() {
			var id string
			erows.Scan(&id)
			if sm, err := loadSample(id); err == nil {
				exceptions = append(exceptions, sampleStateJSON(sm))
			}
		}
		erows.Close()
	}
	var maxActive, minActive, ineligible int
	db.QueryRow(`SELECT COALESCE(max(c),0), COALESCE(min(c),0) FROM (SELECT count(*) AS c FROM assignments WHERE status IN ('accepted','in_progress') GROUP BY worker_id) t`).Scan(&maxActive, &minActive)
	db.QueryRow(`SELECT count(*) FROM assignments WHERE status='pending' AND no_eligible_since IS NOT NULL`).Scan(&ineligible)
	return map[string]any{
		"samples":                   samples,
		"workers":                   workers,
		"locations":                 locations,
		"connections":               connections,
		"routes":                    routes,
		"handoffs":                  handoffs,
		"delays":                    []any{},
		"exceptions":                exceptions,
		"assignmentCountSpread":     maxActive - minActive,
		"ineligibleAssignmentCount": ineligible,
	}
}

func handleReadOperationsState(s *session) (int, any, *apiErr) {
	return 200, operationsStateJSON(s.ActiveRole), nil
}

func handleSearchAudit(s *session, q map[string]string) (int, any, *apiErr) {
	where := []string{"1=1"}
	args := []any{}
	i := 1
	add := func(cond string, val string) {
		where = append(where, fmt.Sprintf(cond, i))
		args = append(args, val)
		i++
	}
	if v := q["sampleId"]; v != "" {
		add(`entity_id=$%d`, v)
	}
	if v := q["requestId"]; v != "" {
		add(`entity_id=$%d`, v)
	}
	if v := q["journeyId"]; v != "" {
		add(`entity_id=$%d`, v)
	}
	if v := q["actorId"]; v != "" {
		add(`actor_id=$%d`, v)
	}
	if v := q["role"]; v != "" {
		add(`role=$%d`, v)
	}
	if v := q["action"]; v != "" {
		add(`action=$%d`, v)
	}
	if v := q["entityType"]; v != "" {
		add(`entity_type=$%d`, v)
	}
	if v := q["success"]; v != "" {
		add(`success=$%d`, v)
	}
	if v := q["from"]; v != "" {
		if t, ok := parseTime(v); ok {
			where = append(where, fmt.Sprintf("occurred_at >= $%d", i))
			args = append(args, t)
			i++
		}
	}
	if v := q["to"]; v != "" {
		if t, ok := parseTime(v); ok {
			where = append(where, fmt.Sprintf("occurred_at <= $%d", i))
			args = append(args, t)
			i++
		}
	}
	limit := 100
	if v := q["limit"]; v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 && n <= 1000 {
			limit = n
		}
	}
	query := `SELECT id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details FROM audit_log WHERE ` + strings.Join(where, " AND ") + ` ORDER BY id DESC LIMIT ` + strconv.Itoa(limit)
	rows, err := db.Query(query, args...)
	if err != nil {
		return 0, nil, errOf(500, "internal_error", err.Error())
	}
	defer rows.Close()
	entries := []map[string]any{}
	for rows.Next() {
		var id int64
		var actorID, role, action, entityType, entityID string
		var success bool
		var at time.Time
		var details []byte
		rows.Scan(&id, &actorID, &role, &action, &entityType, &entityID, &success, &at, &details)
		var det map[string]any
		json.Unmarshal(details, &det)
		if det == nil {
			det = map[string]any{}
		}
		entries = append(entries, map[string]any{
			"auditId":    strconv.FormatInt(id, 10),
			"actorId":    actorID,
			"role":       role,
			"action":     action,
			"entityType": entityType,
			"entityId":   entityID,
			"success":    success,
			"occurredAt": fmtTime(at),
			"details":    det,
		})
	}
	return 200, map[string]any{"entries": entries}, nil
}

func handleListEvents(s *session, q map[string]string) (int, any, *apiErr) {
	cursor := int64(0)
	if c := q["cursor"]; c != "" {
		if n, err := strconv.ParseInt(c, 10, 64); err == nil {
			cursor = n
		}
	}
	rows, err := db.Query(`SELECT id, type, entity_type, entity_id, payload, created_at FROM events WHERE id > $1 ORDER BY id LIMIT 200`, cursor)
	if err != nil {
		return 0, nil, errOf(500, "internal_error", err.Error())
	}
	defer rows.Close()
	events := []map[string]any{}
	var last int64 = cursor
	for rows.Next() {
		var id int64
		var typ, et, eid string
		var payload []byte
		var at time.Time
		rows.Scan(&id, &typ, &et, &eid, &payload, &at)
		var p map[string]any
		json.Unmarshal(payload, &p)
		if p == nil {
			p = map[string]any{}
		}
		events = append(events, map[string]any{
			"cursor":     strconv.FormatInt(id, 10),
			"type":       typ,
			"entityType": et,
			"entityId":   eid,
			"payload":    p,
			"createdAt":  fmtTime(at),
		})
		last = id
	}
	return 200, map[string]any{"events": events, "nextCursor": strconv.FormatInt(last, 10)}, nil
}

