import { useCallback, useEffect, useState } from "react";
import { api, setToken, getToken, ApiError } from "./api";
import MapView, { MapMarker } from "./MapView";

interface Session {
  userId: string;
  username: string;
  roles: string[];
  activeRole: string;
}

const ROLE_LABELS: Record<string, string> = {
  administrator: "Administrator",
  dispatcher: "Dispatcher",
  requester: "Requester",
  collection_professional: "Certified Collection Professional",
  delivery_partner: "Relay Courier",
  node_handler: "Node Handler",
  laboratory_team: "Laboratory Intake Operator",
};

function roleLabel(r: string) {
  return ROLE_LABELS[r] ?? r;
}

function fmt(t?: string | null) {
  if (!t) return "—";
  return new Date(t).toLocaleString();
}

export default function App() {
  const [session, setSession] = useState<Session | null>(null);
  const [boot, setBoot] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  const refresh = useCallback(async () => {
    try {
      const b = await api.bootstrap();
      setBoot(b);
      setSession({
        userId: b.user.userId,
        username: b.user.username,
        roles: b.user.roles,
        activeRole: b.user.activeRole,
      });
      setError(null);
    } catch (e: any) {
      if (e.status === 401) {
        setToken(null);
        setSession(null);
        setBoot(null);
      }
    }
  }, []);

  useEffect(() => {
    if (getToken()) refresh();
  }, [refresh]);

  if (!session) {
    return (
      <Login
        onLogin={(s) => {
          setSession(s);
          refresh();
        }}
      />
    );
  }

  const needsRole = !session.activeRole;

  return (
    <div>
      <header className="app-header">
        <h1>Lab Sample Pickup &amp; Delivery</h1>
        <span>
          Signed in as <strong>{session.username}</strong>
        </span>
        {session.activeRole && (
          <span className="badge role" aria-label="active role">
            Active role: {roleLabel(session.activeRole)}
          </span>
        )}
        {session.roles.length > 1 && (
          <label>
            Switch role:{" "}
            <select
              aria-label="role switcher"
              value={session.activeRole}
              onChange={async (e) => {
                try {
                  await api.selectRole(e.target.value);
                  await refresh();
                } catch (err: any) {
                  setError(err.message);
                }
              }}
            >
              {!session.activeRole && <option value="">Select role…</option>}
              {session.roles.map((r) => (
                <option key={r} value={r}>
                  {roleLabel(r)}
                </option>
              ))}
            </select>
          </label>
        )}
        <button
          onClick={() => {
            setToken(null);
            setSession(null);
            setBoot(null);
          }}
        >
          Sign out
        </button>
      </header>
      <main>
        {error && (
          <div className="error-banner" role="alert">
            {error}
          </div>
        )}
        {needsRole ? (
          <RolePicker
            roles={session.roles}
            onPicked={async (role) => {
              try {
                await api.selectRole(role);
                await refresh();
              } catch (e: any) {
                setError(e.message);
              }
            }}
          />
        ) : (
          <RoleHome session={session} boot={boot} refresh={refresh} onError={setError} />
        )}
      </main>
    </div>
  );
}

function Login({ onLogin }: { onLogin: (s: Session) => void }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  return (
    <div className="login-box">
      <div className="card">
        <h2>Sign in</h2>
        {error && (
          <div className="error-banner" role="alert">
            {error}
          </div>
        )}
        <form
          onSubmit={async (e) => {
            e.preventDefault();
            setBusy(true);
            setError(null);
            try {
              const data = await api.login(username, password);
              setToken(data.sessionToken);
              onLogin({
                userId: data.userId,
                username,
                roles: data.roles,
                activeRole: data.activeRole ?? "",
              });
            } catch (err: any) {
              setError(err.message ?? "Sign in failed");
            } finally {
              setBusy(false);
            }
          }}
        >
          <input
            aria-label="username"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
            autoComplete="username"
          />
          <input
            aria-label="password"
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            autoComplete="current-password"
          />
          <button className="primary" type="submit" disabled={busy}>
            Sign in
          </button>
        </form>
      </div>
    </div>
  );
}

function RolePicker({ roles, onPicked }: { roles: string[]; onPicked: (r: string) => void }) {
  return (
    <div className="card">
      <h2>Select your working role</h2>
      <p className="muted">You hold multiple roles. Choose the role you are currently working under.</p>
      <div className="row">
        {roles.map((r) => (
          <button key={r} className="primary" onClick={() => onPicked(r)}>
            {roleLabel(r)}
          </button>
        ))}
      </div>
    </div>
  );
}

function RoleHome({
  session,
  boot,
  refresh,
  onError,
}: {
  session: Session;
  boot: any;
  refresh: () => Promise<void>;
  onError: (m: string | null) => void;
}) {
  const role = session.activeRole;
  const isDispatcher = role === "dispatcher" || role === "administrator";
  const isWorker = ["collection_professional", "delivery_partner", "node_handler", "laboratory_team"].includes(role);
  const [sampleId, setSampleId] = useState<string | null>(null);

  return (
    <div>
      {isDispatcher && <MonitorView boot={boot} onOpenSample={setSampleId} />}
      {isDispatcher && <AuditView />}
      {role === "requester" && <RequesterView boot={boot} refresh={refresh} onError={onError} onOpenSample={setSampleId} />}
      {isWorker && <WorkView session={session} refresh={refresh} onError={onError} onOpenSample={setSampleId} />}
      {(role === "node_handler" || role === "laboratory_team") && (
        <CapacityCard refresh={refresh} onError={onError} />
      )}
      {sampleId && <SampleDetail sampleId={sampleId} onClose={() => setSampleId(null)} />}
    </div>
  );
}

/* ---------------- Sample detail ---------------- */

function SampleDetail({ sampleId, onClose }: { sampleId: string; onClose: () => void }) {
  const [state, setState] = useState<any>(null);
  const [lifecycle, setLifecycle] = useState<any>(null);
  const [journey, setJourney] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    (async () => {
      try {
        const st = await api.sampleState(sampleId);
        setState(st);
        const lc = await api.sampleLifecycle(sampleId);
        setLifecycle(lc);
        if (st.activeJourneyId) {
          try {
            setJourney(await api.journeyPlan(st.activeJourneyId));
          } catch {
            /* not visible to this role */
          }
        }
      } catch (e: any) {
        setError(e.message);
      }
    })();
  }, [sampleId]);

  if (error)
    return (
      <div className="card">
        <div className="error-banner" role="alert">
          {error}
        </div>
        <button onClick={onClose}>Close</button>
      </div>
    );
  if (!state) return <div className="card">Loading sample…</div>;

  const markers: MapMarker[] = [];
  if (state.latestLocation?.lng != null) {
    markers.push({
      id: "sample",
      lng: state.latestLocation.lng,
      lat: state.latestLocation.lat,
      label: `Sample ${state.sampleId.slice(0, 8)}`,
      color: state.exception ? "#b3261e" : "#1d6fb8",
    });
  }
  if (state.origin?.lng != null) {
    markers.push({ id: "origin", lng: state.origin.lng, lat: state.origin.lat, label: "Origin", color: "#2e7d32" });
  }

  const entries: any[] = lifecycle?.entries ?? lifecycle?.timeline ?? [];

  return (
    <div className="card" aria-label="sample detail">
      <div className="row" style={{ justifyContent: "space-between" }}>
        <h2>Sample {state.sampleId.slice(0, 8)}</h2>
        <button onClick={onClose}>Close</button>
      </div>
      {state.exception && (
        <div className="exception-banner" role="alert" aria-label="exception flag">
          ⚠ Exception: {state.exception.reason ?? state.exception.code ?? JSON.stringify(state.exception)}
        </div>
      )}
      <div className="section-grid">
        <div>
          <p>
            <strong>Status:</strong> {state.status} {state.sealed ? "(sealed)" : ""}
          </p>
          <p>
            <strong>Current custodian:</strong> {state.currentHolderId ?? "—"}
          </p>
          <p>
            <strong>Delivery deadline:</strong> {fmt(state.deliveryDeadline)}
          </p>
          <p>
            <strong>Collection window:</strong> {fmt(state.earliestCollectionAt)} – {fmt(state.latestCollectionAt)}
          </p>
          <p>
            <strong>Freshness:</strong>{" "}
            {state.locationStale ? (
              <span className="badge stale" aria-label="location stale">
                Stale
              </span>
            ) : (
              <span className="badge fresh" aria-label="location fresh">
                Fresh
              </span>
            )}{" "}
            <span className="muted">Last update: {fmt(state.locationRecordedAt)}</span>
          </p>
        </div>
        <div>
          {journey && (
            <div>
              <h3>Route progress</h3>
              <p className="muted">
                Journey {journey.journeyId?.slice(0, 8)} — {journey.status} (plan v{journey.planVersion})
              </p>
              <ol>
                {(journey.legs ?? []).map((leg: any) => (
                  <li key={leg.legId ?? leg.assignmentId}>
                    {leg.fromName ?? leg.fromLocationId} → {leg.toName ?? leg.toLocationId} —{" "}
                    <strong>{leg.status}</strong>
                  </li>
                ))}
              </ol>
            </div>
          )}
        </div>
      </div>
      {markers.length > 0 && <MapView markers={markers} />}
      <h3>Status history</h3>
      <ol className="timeline" aria-label="status history">
        {entries.map((e: any, i: number) => (
          <li key={e.eventId ?? i} className={e.success === false ? "failure" : ""}>
            <strong>{e.action ?? e.status}</strong>{" "}
            <span className="muted">
              {fmt(e.occurredAt ?? e.at)} {e.role ? `· ${roleLabel(e.role)}` : ""}
            </span>
          </li>
        ))}
      </ol>
    </div>
  );
}

/* ---------------- Requester ---------------- */

function RequesterView({
  boot,
  refresh,
  onError,
  onOpenSample,
}: {
  boot: any;
  refresh: () => Promise<void>;
  onError: (m: string | null) => void;
  onOpenSample: (id: string) => void;
}) {
  const samples: any[] = boot?.requesterSamples ?? [];
  const sampleTypes: any[] = [
    { id: "00000000-0000-4000-8000-000000000001", name: "Amber" },
    { id: "00000000-0000-4000-8000-000000000002", name: "Indigo" },
    { id: "00000000-0000-4000-8000-000000000003", name: "Frost" },
    { id: "00000000-0000-4000-8000-000000000004", name: "Pulse" },
  ];
  const [form, setForm] = useState({
    originType: "home",
    lng: "77.5946",
    lat: "12.9716",
    sampleTypeId: "",
    earliest: "",
    latest: "",
    deadline: "",
  });
  const [checkResult, setCheckResult] = useState<any>(null);
  const [message, setMessage] = useState<string | null>(null);

  const payload = () => ({
    originType: form.originType,
    origin: { longitude: parseFloat(form.lng), latitude: parseFloat(form.lat) },
    sampleTypeId: form.sampleTypeId,
    earliestCollectionAt: form.earliest ? new Date(form.earliest).toISOString() : undefined,
    latestCollectionAt: form.latest ? new Date(form.latest).toISOString() : undefined,
    deliveryDeadline: form.deadline ? new Date(form.deadline).toISOString() : undefined,
  });

  return (
    <div>
      <div className="card">
        <h2>My requests</h2>
        {samples.length === 0 && <p className="muted">No requests yet.</p>}
        <table>
          <thead>
            <tr>
              <th>Sample</th>
              <th>Status</th>
              <th>Deadline</th>
              <th>Last update</th>
              <th>Freshness</th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            {samples.map((s) => (
              <tr key={s.sampleId}>
                <td>{s.sampleId.slice(0, 8)}</td>
                <td>
                  {s.status}{" "}
                  {s.exception && (
                    <span className="badge exception" aria-label="exception flag">
                      Exception
                    </span>
                  )}
                </td>
                <td>{fmt(s.deliveryDeadline)}</td>
                <td>{fmt(s.locationRecordedAt)}</td>
                <td>
                  {s.locationStale ? (
                    <span className="badge stale">Stale</span>
                  ) : (
                    <span className="badge fresh">Fresh</span>
                  )}
                </td>
                <td>
                  <button onClick={() => onOpenSample(s.sampleId)}>View</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      <div className="card">
        <h2>New collection request</h2>
        {message && <div className="success-banner">{message}</div>}
        <div className="form-grid">
          <label>
            Origin type
            <select value={form.originType} onChange={(e) => setForm({ ...form, originType: e.target.value })}>
              <option value="home">Home</option>
              <option value="clinic">Clinic</option>
              <option value="node">Network node</option>
            </select>
          </label>
          <label>
            Longitude
            <input value={form.lng} onChange={(e) => setForm({ ...form, lng: e.target.value })} />
          </label>
          <label>
            Latitude
            <input value={form.lat} onChange={(e) => setForm({ ...form, lat: e.target.value })} />
          </label>
          <label>
            Sample type
            <select
              aria-label="sample type"
              value={form.sampleTypeId}
              onChange={(e) => setForm({ ...form, sampleTypeId: e.target.value })}
            >
              <option value="">Select…</option>
              {sampleTypes.map((t: any) => (
                <option key={t.id} value={t.id}>
                  {t.name}
                </option>
              ))}
            </select>
          </label>
          <label>
            Earliest collection
            <input type="datetime-local" value={form.earliest} onChange={(e) => setForm({ ...form, earliest: e.target.value })} />
          </label>
          <label>
            Latest collection
            <input type="datetime-local" value={form.latest} onChange={(e) => setForm({ ...form, latest: e.target.value })} />
          </label>
          <label>
            Delivery deadline
            <input type="datetime-local" value={form.deadline} onChange={(e) => setForm({ ...form, deadline: e.target.value })} />
          </label>
        </div>
        <div className="row" style={{ marginTop: 12 }}>
          <button
            onClick={async () => {
              try {
                const res = await api.checkServiceability(payload());
                setCheckResult(res);
                onError(null);
              } catch (e: any) {
                setCheckResult(null);
                onError(e.message);
              }
            }}
          >
            Check serviceability (dry run)
          </button>
          <button
            className="primary"
            onClick={async () => {
              try {
                await api.createRequest({ ...payload(), idempotencyKey: crypto.randomUUID() });
                setMessage("Request created.");
                setCheckResult(null);
                onError(null);
                await refresh();
              } catch (e: any) {
                setMessage(null);
                onError(e.message);
              }
            }}
          >
            Create request
          </button>
        </div>
        {checkResult && (
          <p style={{ marginTop: 12 }} aria-label="serviceability result">
            Serviceability:{" "}
            <strong>{checkResult.serviceable ? "Serviceable" : `Not serviceable (${checkResult.reason ?? "unknown"})`}</strong>{" "}
            <span className="muted">— dry run only; nothing was created.</span>
          </p>
        )}
      </div>
    </div>
  );
}

/* ---------------- Worker work view ---------------- */

function WorkView({
  session,
  refresh,
  onError,
  onOpenSample,
}: {
  session: Session;
  refresh: () => Promise<void>;
  onError: (m: string | null) => void;
  onOpenSample: (id: string) => void;
}) {
  const [work, setWork] = useState<any>(null);
  const [tab, setTab] = useState<"current" | "past">("current");

  const load = useCallback(async () => {
    try {
      setWork(await api.listRoleWork());
    } catch (e: any) {
      onError(e.message);
    }
  }, [onError]);

  useEffect(() => {
    load();
    const t = setInterval(load, 5000);
    return () => clearInterval(t);
  }, [load]);

  if (!work) return <div className="card">Loading work…</div>;
  const current = [...(work.pending ?? []), ...(work.inProgress ?? [])];
  const past = work.completed ?? [];
  const items = tab === "current" ? current : past;

  return (
    <div className="card">
      <h2>{roleLabel(session.activeRole)} work</h2>
      <div className="tabs" role="tablist">
        <button className={tab === "current" ? "active" : ""} onClick={() => setTab("current")} role="tab">
          Current work
        </button>
        <button className={tab === "past" ? "active" : ""} onClick={() => setTab("past")} role="tab">
          Past work
        </button>
      </div>
      {items.length === 0 && <p className="muted">No {tab} work.</p>}
      <table>
        <thead>
          <tr>
            <th>Assignment</th>
            <th>Kind</th>
            <th>Status</th>
            <th>Sample</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {items.map((a: any) => (
            <tr key={a.assignmentId}>
              <td>{a.assignmentId.slice(0, 8)}</td>
              <td>{a.kind}</td>
              <td>{a.status}</td>
              <td>
                {a.sampleId && (
                  <button onClick={() => onOpenSample(a.sampleId)}>{a.sampleId.slice(0, 8)}</button>
                )}
              </td>
              <td>
                <WorkerActions
                  assignment={a}
                  role={session.activeRole}
                  onDone={async () => {
                    await load();
                    await refresh();
                  }}
                  onError={onError}
                />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function WorkerActions({
  assignment,
  role,
  onDone,
  onError,
}: {
  assignment: any;
  role: string;
  onDone: () => Promise<void>;
  onError: (m: string | null) => void;
}) {
  const run = async (fn: () => Promise<any>) => {
    try {
      await fn();
      onError(null);
      await onDone();
    } catch (e: any) {
      onError(e.message);
    }
  };
  const a = assignment;
  return (
    <div className="row">
      {a.status === "pending" && (
        <>
          <button className="primary" onClick={() => run(() => api.acceptAssignment(a.assignmentId))}>
            Accept
          </button>
          <button onClick={() => run(() => api.declineAssignment(a.assignmentId))}>Decline</button>
        </>
      )}
      {a.status === "accepted" && role === "collection_professional" && a.kind === "collection" && (
        <button
          className="primary"
          onClick={() =>
            run(() =>
              api.collectAndSeal({
                assignmentId: a.assignmentId,
                containerType: "standard",
                temperatureC: 20,
              })
            )
          }
        >
          Collect &amp; seal
        </button>
      )}
      {(a.status === "accepted" || a.status === "in_progress") && (
        <button
          onClick={() =>
            run(() =>
              api.updateProgress({
                assignmentId: a.assignmentId,
                status: "in_progress",
                note: "en route",
              })
            )
          }
        >
          Record progress
        </button>
      )}
    </div>
  );
}

/* ---------------- Capacity card ---------------- */

function CapacityCard({
  refresh,
  onError,
}: {
  refresh: () => Promise<void>;
  onError: (m: string | null) => void;
}) {
  const [locations, setLocations] = useState<any[]>([]);
  const [regular, setRegular] = useState("0");
  const [cooled, setCooled] = useState("0");
  const [selected, setSelected] = useState<string>("");

  useEffect(() => {
    let stop = false;
    const load = async () => {
      try {
        const d = await api.operationsState();
        if (stop) return;
        const locs = d.locations ?? [];
        setLocations(locs);
        if (!selected && locs.length > 0) {
          setSelected(locs[0].locationId);
          setRegular(String(locs[0].capacity?.capacityUnits ?? 0));
          setCooled(String(locs[0].capacity?.cooledCapacityUnits ?? 0));
        }
      } catch {
        /* ignore */
      }
    };
    load();
    const t = setInterval(load, 5000);
    return () => {
      stop = true;
      clearInterval(t);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [selected]);

  const loc = locations.find((l: any) => l.locationId === selected);

  return (
    <div className="card" aria-label="my location capacity">
      <h2>Location capacity</h2>
      <div className="row">
        <label>
          Location{" "}
          <select
            value={selected}
            onChange={(e) => {
              setSelected(e.target.value);
              const l = locations.find((x: any) => x.locationId === e.target.value);
              setRegular(String(l?.capacity?.capacityUnits ?? 0));
              setCooled(String(l?.capacity?.cooledCapacityUnits ?? 0));
            }}
          >
            {locations.map((l: any) => (
              <option key={l.locationId} value={l.locationId}>
                {l.name}
              </option>
            ))}
          </select>
        </label>
      </div>
      {loc && (
        <table>
          <thead>
            <tr>
              <th>Pool</th>
              <th>Configured</th>
              <th>Reserved</th>
              <th>Available</th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>Regular</td>
              <td>{loc.capacity?.capacityUnits}</td>
              <td>{loc.capacity?.reservedUnits}</td>
              <td>{loc.capacity?.availableUnits}</td>
            </tr>
            <tr>
              <td>Cooled</td>
              <td>{loc.capacity?.cooledCapacityUnits}</td>
              <td>{loc.capacity?.cooledReservedUnits}</td>
              <td>{loc.capacity?.cooledAvailableUnits}</td>
            </tr>
          </tbody>
        </table>
      )}
      <div className="row" style={{ marginTop: 10 }}>
        <label>
          Regular{" "}
          <input style={{ width: 80 }} value={regular} onChange={(e) => setRegular(e.target.value)} />
        </label>
        <label>
          Cooled <input style={{ width: 80 }} value={cooled} onChange={(e) => setCooled(e.target.value)} />
        </label>
        <button
          onClick={async () => {
            try {
              await api.configureCapacity({
                resourceId: selected,
                capacityUnits: parseInt(regular),
                cooledCapacityUnits: parseInt(cooled),
              });
              onError(null);
              await refresh();
            } catch (e: any) {
              onError(e.message);
            }
          }}
        >
          Update capacity
        </button>
      </div>
    </div>
  );
}

/* ---------------- Monitor dashboard ---------------- */

function MonitorView({ boot, onOpenSample }: { boot: any; onOpenSample: (id: string) => void }) {
  const [ops, setOps] = useState<any>(boot?.operations ?? null);

  useEffect(() => {
    let stop = false;
    const load = async () => {
      try {
        const o = await api.operationsState();
        if (!stop) setOps(o);
      } catch {
        /* ignore */
      }
    };
    load();
    const t = setInterval(load, 5000);
    return () => {
      stop = true;
      clearInterval(t);
    };
  }, []);

  if (!ops) return <div className="card">Loading operations state…</div>;

  const markers: MapMarker[] = (ops.locations ?? [])
    .filter((l: any) => l.coordinate?.longitude != null)
    .map((l: any) => ({
      id: l.locationId ?? l.id,
      lng: l.coordinate.longitude,
      lat: l.coordinate.latitude,
      label: l.name,
      color: l.active === false ? "#999" : "#2e7d32",
    }));
  (ops.workers ?? []).forEach((w: any) => {
    if (w.latestLocation?.longitude != null) {
      markers.push({
        id: `w-${w.workerId}`,
        lng: w.latestLocation.longitude,
        lat: w.latestLocation.latitude,
        label: `Worker ${w.fullName ?? w.workerId}`,
        color: "#e65100",
      });
    }
  });

  return (
    <div>
      <div className="card">
        <h2>Live network map</h2>
        <MapView markers={markers} />
      </div>
      <div className="card" aria-label="monitor dashboard">
        <h2>Monitor dashboard</h2>
        <div className="section-grid">
          <section aria-label="samples">
            <h3>Samples ({(ops.samples ?? []).length})</h3>
            <table>
              <tbody>
                {(ops.samples ?? []).slice(0, 20).map((s: any) => (
                  <tr key={s.sampleId}>
                    <td>
                      <button onClick={() => onOpenSample(s.sampleId)}>{s.sampleId.slice(0, 8)}</button>
                    </td>
                    <td>{s.status}</td>
                    <td>
                      {s.locationStale ? <span className="badge stale">Stale</span> : <span className="badge fresh">Fresh</span>}
                    </td>
                    <td>{s.status === "exception" && <span className="badge exception">Exception</span>}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </section>
          <section aria-label="workers">
            <h3>Workers ({(ops.workers ?? []).length})</h3>
            <table>
              <tbody>
                {(ops.workers ?? []).slice(0, 20).map((w: any) => (
                  <tr key={w.workerId}>
                    <td>{w.fullName ?? w.workerId.slice(0, 8)}</td>
                    <td>{(w.roles ?? []).map(roleLabel).join(", ")}</td>
                    <td>{w.available === false ? "Unavailable" : "Available"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </section>
          <section aria-label="locations">
            <h3>Locations ({(ops.locations ?? []).length})</h3>
            <table>
              <tbody>
                {(ops.locations ?? []).map((l: any) => (
                  <tr key={l.locationId ?? l.id}>
                    <td>{l.name}</td>
                    <td>
                      {Object.entries(l.functions ?? {})
                        .filter(([, v]) => v)
                        .map(([k]) => k)
                        .join(", ")}
                    </td>
                    <td>{l.active === false ? "Inactive" : "Active"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </section>
          <section aria-label="connections">
            <h3>Connections ({(ops.connections ?? []).length})</h3>
            <table>
              <tbody>
                {(ops.connections ?? []).map((c: any) => (
                  <tr key={c.connectionId ?? c.id}>
                    <td>
                      {c.fromName ?? c.fromLocationId} → {c.toName ?? c.toLocationId}
                    </td>
                    <td>{c.active === false ? "Inactive" : "Active"}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </section>
          <section aria-label="routes">
            <h3>Routes ({(ops.routes ?? []).length})</h3>
            <table>
              <tbody>
                {(ops.routes ?? []).slice(0, 20).map((r: any, i: number) => (
                  <tr key={r.journeyId ?? i}>
                    <td>{(r.journeyId ?? "").slice(0, 8)}</td>
                    <td>{r.status}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </section>
          <section aria-label="exceptions">
            <h3>Exceptions ({(ops.exceptions ?? []).length})</h3>
            <table>
              <tbody>
                {(ops.exceptions ?? []).map((x: any, i: number) => (
                  <tr key={x.sampleId ?? i}>
                    <td>{(x.sampleId ?? "").slice(0, 8)}</td>
                    <td>{x.reason ?? x.code ?? JSON.stringify(x)}</td>
                  </tr>
                ))}
              </tbody>
            </table>
          </section>
        </div>
      </div>
    </div>
  );
}

/* ---------------- Audit ---------------- */

function AuditView() {
  const [query, setQuery] = useState("");
  const [action, setAction] = useState("");
  const [result, setResult] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  const search = async () => {
    try {
      const params: Record<string, unknown> = {};
      if (query) params.query = query;
      if (action) params.action = action;
      setResult(await api.searchAudit(params));
      setError(null);
    } catch (e: any) {
      setError(e.message);
    }
  };

  useEffect(() => {
    search();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  return (
    <div className="card" aria-label="audit search">
      <h2>Audit trail</h2>
      {error && <div className="error-banner">{error}</div>}
      <div className="row" style={{ marginBottom: 10 }}>
        <input
          aria-label="audit search query"
          placeholder="Search (entity id, action…)"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
        />
        <input aria-label="audit action filter" placeholder="Action" value={action} onChange={(e) => setAction(e.target.value)} />
        <button className="primary" onClick={search}>
          Search
        </button>
      </div>
      {result && (
        <table>
          <thead>
            <tr>
              <th>Time</th>
              <th>Actor</th>
              <th>Role</th>
              <th>Action</th>
              <th>Entity</th>
              <th>Outcome</th>
            </tr>
          </thead>
          <tbody>
            {(result.entries ?? []).map((e: any, i: number) => (
              <tr key={e.auditId ?? e.eventId ?? i}>
                <td>{fmt(e.occurredAt ?? e.at)}</td>
                <td>{(e.actorId ?? "").slice(0, 8)}</td>
                <td>{e.role ? roleLabel(e.role) : "—"}</td>
                <td>{e.action}</td>
                <td>
                  {e.entityType} {(e.entityId ?? "").slice(0, 8)}
                </td>
                <td>{e.success === false ? "Failed" : "OK"}</td>
              </tr>
            ))}
          </tbody>
        </table>
      )}
    </div>
  );
}

