        </div>
        <div className="row" style={{ marginTop: 12 }}>
          <button
            onClick={async () => {
              try {
                const res = await api.checkServiceability(payload());
                setCheckResult(res);
                onError(null);
              } catch (e: any) {
                setCheckResult(null);
                onError(e.message);
              }
            }}
          >
            Check serviceability (dry run)
          </button>
          <button
            className="primary"
            onClick={async () => {
              try {
                await api.createRequest({ ...payload(), idempotencyKey: crypto.randomUUID() });
                setMessage("Request created.");
                setCheckResult(null);
                onError(null);
                await refresh();
              } catch (e: any) {
                setMessage(null);
                onError(e.message);
              }
            }}
