)

func timelineForSample(sampleID string, statusOnly bool) []map[string]any {
	q := `SELECT id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details FROM audit_log WHERE entity_type='sample' AND entity_id=$1`
	if statusOnly {
		q += ` AND action='sample_status'`
	}
	q += ` ORDER BY id`
	rows, err := db.Query(q, sampleID)
	if err != nil {
		return []map[string]any{}
	}
	defer rows.Close()
	entries := []map[string]any{}
	for rows.Next() {
		var id int64
		var actorID, role, action, entityType, entityID string
		var success bool
		var at time.Time
		var details []byte
		rows.Scan(&id, &actorID, &role, &action, &entityType, &entityID, &success, &at, &details)
		var det map[string]any
		json.Unmarshal(details, &det)
		if det == nil {
			det = map[string]any{}
		}
		entries = append(entries, map[string]any{
			"eventId":    id,
			"action":     action,
			"actorId":    actorID,
			"role":       role,
			"entityType": entityType,
			"entityId":   entityID,
			"success":    success,
			"occurredAt": fmtTime(at),
			"details":    det,
		})
	}
	return entries
}

