		CapacityUnits       int     `json:"capacityUnits"`
		CooledCapacityUnits int     `json:"cooledCapacityUnits"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	if req.FromLocationID == "" || req.ToLocationID == "" || req.FromLocationID == req.ToLocationID || req.TravelMinutes < 0 || req.CapacityUnits < 0 || req.CooledCapacityUnits < 0 {
		return 0, nil, errOf(400, "invalid_connection", "invalid connection fields")
	}
	if _, err := loadLocation(req.FromLocationID); err != nil {
		return 0, nil, errOf(400, "invalid_connection", "from location does not exist")
	}
	if _, err := loadLocation(req.ToLocationID); err != nil {
		return 0, nil, errOf(400, "invalid_connection", "to location does not exist")
	}
	id := newUUID()
	db.Exec(`INSERT INTO connections (id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, cooled_capacity_units) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		id, req.FromLocationID, req.ToLocationID, req.TravelMinutes, req.CostUnits, req.Cooled, req.Active, req.CapacityUnits, req.CooledCapacityUnits)
	recordAudit(s.User.ID, s.ActiveRole, "create_connection", "connection", id, true, map[string]any{"from": req.FromLocationID, "to": req.ToLocationID})
	bumpNetworkRevision()
	return 201, map[string]any{
		"connectionId":    id,
		"fromLocationId":  req.FromLocationID,
		"toLocationId":    req.ToLocationID,
		"travelMinutes":   req.TravelMinutes,
		"costUnits":       req.CostUnits,
		"cooled":          req.Cooled,
		"active":          req.Active,
		"travelMinutesOk": true,
	}, nil
}

func handleCreateSampleType(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		Name                       string   `json:"name"`
		QualifiedCollectorRequired bool     `json:"qualifiedCollectorRequired"`
		RequiredQualification      string   `json:"requiredQualification"`
		ContainerType              string   `json:"containerType"`
		TemperatureMinC            float64  `json:"temperatureMinC"`
		TemperatureMaxC            float64  `json:"temperatureMaxC"`
		IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
