	recordAudit(s.User.ID, s.ActiveRole, "create_sample_type", "sample_type", id, true, map[string]any{"name": req.Name})
	bumpNetworkRevision()
	st, _ := loadSampleType(id)
	return 201, sampleTypeJSON(st), nil
}

