	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	l, err := loadLocation(req.LocationID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "location not found")
	}
	if req.Name == "" || !validCoordinate(req.Coordinate) || req.CoverageKm < 0 || req.HandlingMinutes < 0 || req.CapacityUnits < 0 || req.CooledCapacityUnits < 0 {
		return 0, nil, errOf(400, "invalid_location", "invalid location fields")
	}
	if req.CapacityUnits < l.ReservedUnits || req.CooledCapacityUnits < l.CooledReservedUnits {
		return 0, nil, errOf(409, "capacity_reserved", "configured capacity cannot be below currently reserved units")
	}
	fn := map[string]bool{
		"collection_point": req.Functions.CollectionPoint,
		"transfer_point":   req.Functions.TransferPoint,
		"hub":              req.Functions.Hub,
		"laboratory":       req.Functions.Laboratory,
	}
	db.Exec(`UPDATE locations SET name=$1, latitude=$2, longitude=$3, coverage_km=$4, handling_minutes=$5, active=$6, functions=$7, capacity_units=$8, cooled_capacity_units=$9 WHERE id=$10`,
		req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, req.CoverageKm, req.HandlingMinutes, req.Active, mustJSON(fn), req.CapacityUnits, req.CooledCapacityUnits, l.ID)
