package main

import (
	"encoding/json"
	"time"
)

func bumpNetworkRevision() {
	db.Exec(`INSERT INTO meta (key, value) VALUES ('network_revision','1') ON CONFLICT (key) DO UPDATE SET value = (meta.value::int + 1)::text`)
	go recomputeServiceabilitySnapshot()
}

func networkRevision() int {
	var v string
	if err := db.QueryRow(`SELECT value FROM meta WHERE key='network_revision'`).Scan(&v); err != nil {
		return 0
	}
	n := 0
	for _, c := range v {
		if c >= '0' && c <= '9' {
			n = n*10 + int(c-'0')
		}
	}
	return n
}

func validCoordinate(c Coordinate) bool {
	return c.Latitude >= -90 && c.Latitude <= 90 && c.Longitude >= -180 && c.Longitude <= 180
}

var validFunctions = []string{"collection_point", "transfer_point", "hub", "laboratory"}

func functionsMap(list []string) (map[string]bool, *apiErr) {
	fn := map[string]bool{"collection_point": false, "transfer_point": false, "hub": false, "laboratory": false}
	for _, f := range list {
		if !contains(validFunctions, f) {
			return nil, errOf(400, "invalid_location_function", "unknown location function: "+f)
		}
		fn[f] = true
	}
	return fn, nil
}

func handleCreateLocation(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		Name            string     `json:"name"`
		Coordinate      Coordinate `json:"coordinate"`
		CoverageKm      float64    `json:"coverageKm"`
		HandlingMinutes int        `json:"handlingMinutes"`
		Active          bool       `json:"active"`
		Functions       []string   `json:"functions"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	if req.Name == "" {
		return 0, nil, errOf(400, "invalid_location", "name is required")
	}
	if !validCoordinate(req.Coordinate) {
		return 0, nil, errOf(400, "invalid_coordinate", "invalid coordinate")
	}
	if req.CoverageKm <= 0 || req.CoverageKm > 5 {
		return 0, nil, errOf(400, "invalid_node_coverage", "coverageKm must be in (0, 5]")
	}
	if req.HandlingMinutes < 0 || req.HandlingMinutes > 1440 {
		return 0, nil, errOf(400, "invalid_handling_time", "handlingMinutes must be in [0, 1440]")
	}
	fn, ferr := functionsMap(req.Functions)
	if ferr != nil {
		return 0, nil, ferr
	}
	id := newUUID()
	_, err := db.Exec(`INSERT INTO locations (id, name, latitude, longitude, coverage_km, handling_minutes, active, functions, capacity_units, cooled_capacity_units) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,0,0)`,
		id, req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, req.CoverageKm, req.HandlingMinutes, req.Active, mustJSON(fn))
	if err != nil {
		return 0, nil, errOf(500, "internal_error", err.Error())
	}
	recordAudit(s.User.ID, s.ActiveRole, "create_location", "location", id, true, map[string]any{"name": req.Name})
	bumpNetworkRevision()
	l, _ := loadLocation(id)
	return 201, locationJSON(l), nil
}

func handleUpdateLocation(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		LocationID      string     `json:"locationId"`
		Name            string     `json:"name"`
		Coordinate      Coordinate `json:"coordinate"`
		CoverageKm      float64    `json:"coverageKm"`
		HandlingMinutes int        `json:"handlingMinutes"`
		Functions       []string   `json:"functions"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	l, err := loadLocation(req.LocationID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "location not found")
	}
	if req.Name == "" {
		return 0, nil, errOf(400, "invalid_location", "name is required")
	}
	if !validCoordinate(req.Coordinate) {
		return 0, nil, errOf(400, "invalid_coordinate", "invalid coordinate")
	}
	if req.CoverageKm <= 0 || req.CoverageKm > 5 {
		return 0, nil, errOf(400, "invalid_node_coverage", "coverageKm must be in (0, 5]")
	}
	if req.HandlingMinutes < 0 || req.HandlingMinutes > 1440 {
		return 0, nil, errOf(400, "invalid_handling_time", "handlingMinutes must be in [0, 1440]")
	}
	fn := l.Functions
	if req.Functions != nil {
		var ferr *apiErr
		fn, ferr = functionsMap(req.Functions)
		if ferr != nil {
			return 0, nil, ferr
		}
	}
	db.Exec(`UPDATE locations SET name=$1, latitude=$2, longitude=$3, coverage_km=$4, handling_minutes=$5, functions=$6 WHERE id=$7`,
		req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, req.CoverageKm, req.HandlingMinutes, mustJSON(fn), l.ID)
	recordAudit(s.User.ID, s.ActiveRole, "update_location", "location", l.ID, true, map[string]any{"name": req.Name})
	bumpNetworkRevision()
	l, _ = loadLocation(l.ID)
	return 201, locationJSON(l), nil
}

func handleCreateConnection(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		FromLocationID      string  `json:"fromLocationId"`
		ToLocationID        string  `json:"toLocationId"`
		TravelMinutes       int     `json:"travelMinutes"`
		CostUnits           float64 `json:"costUnits"`
		Cooled              bool    `json:"cooled"`
		Active              bool    `json:"active"`
		CapacityUnits       int     `json:"capacityUnits"`
		CooledCapacityUnits int     `json:"cooledCapacityUnits"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	if req.FromLocationID == "" || req.ToLocationID == "" || req.FromLocationID == req.ToLocationID || req.TravelMinutes < 0 || req.CapacityUnits < 0 || req.CooledCapacityUnits < 0 {
		return 0, nil, errOf(400, "invalid_connection", "invalid connection fields")
	}
	if _, err := loadLocation(req.FromLocationID); err != nil {
		return 0, nil, errOf(400, "invalid_connection", "from location does not exist")
	}
	if _, err := loadLocation(req.ToLocationID); err != nil {
		return 0, nil, errOf(400, "invalid_connection", "to location does not exist")
	}
	id := newUUID()
	db.Exec(`INSERT INTO connections (id, from_location_id, to_location_id, travel_minutes, cost_units, cooled, active, capacity_units, cooled_capacity_units) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,$9)`,
		id, req.FromLocationID, req.ToLocationID, req.TravelMinutes, req.CostUnits, req.Cooled, req.Active, req.CapacityUnits, req.CooledCapacityUnits)
	recordAudit(s.User.ID, s.ActiveRole, "create_connection", "connection", id, true, map[string]any{"from": req.FromLocationID, "to": req.ToLocationID})
	bumpNetworkRevision()
	return 201, map[string]any{
		"connectionId":    id,
		"fromLocationId":  req.FromLocationID,
		"toLocationId":    req.ToLocationID,
		"travelMinutes":   req.TravelMinutes,
		"costUnits":       req.CostUnits,
		"cooled":          req.Cooled,
		"active":          req.Active,
		"travelMinutesOk": true,
	}, nil
}

func handleCreateSampleType(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		Name                       string   `json:"name"`
		QualifiedCollectorRequired bool     `json:"qualifiedCollectorRequired"`
		RequiredQualification      string   `json:"requiredQualification"`
		ContainerType              string   `json:"containerType"`
		TemperatureMinC            float64  `json:"temperatureMinC"`
		TemperatureMaxC            float64  `json:"temperatureMaxC"`
		IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
		RequiresCooledRoute        bool     `json:"requiresCooledRoute"`
		BatchingAllowed            bool     `json:"batchingAllowed"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	if req.Name == "" || req.TemperatureMinC > req.TemperatureMaxC {
		return 0, nil, errOf(400, "invalid_sample_type", "invalid sample type fields")
	}
	if req.IncompatibleSampleTypes == nil {
		req.IncompatibleSampleTypes = []string{}
	}
	for _, other := range req.IncompatibleSampleTypes {
		if _, err := loadSampleType(other); err != nil {
			return 0, nil, errOf(400, "invalid_sample_type", "incompatible sample type does not exist")
		}
	}
	var exists int
	db.QueryRow(`SELECT count(*) FROM sample_types WHERE name=$1`, req.Name).Scan(&exists)
	if exists > 0 {
		return 0, nil, errOf(409, "duplicate_sample_type", "a sample type with this name already exists")
	}
	id := newUUID()
