package main

import (
	"encoding/json"
	"time"
)

func bumpNetworkRevision() {
	db.Exec(`INSERT INTO meta (key, value) VALUES ('network_revision','1') ON CONFLICT (key) DO UPDATE SET value = (meta.value::int + 1)::text`)
	go recomputeServiceabilitySnapshot()
}

func networkRevision() int {
	var v string
	if err := db.QueryRow(`SELECT value FROM meta WHERE key='network_revision'`).Scan(&v); err != nil {
		return 0
	}
	n := 0
	for _, c := range v {
		if c >= '0' && c <= '9' {
			n = n*10 + int(c-'0')
		}
	}
	return n
}

func validCoordinate(c Coordinate) bool {
	return c.Latitude >= -90 && c.Latitude <= 90 && c.Longitude >= -180 && c.Longitude <= 180
}

var validFunctions = []string{"collection_point", "transfer_point", "hub", "laboratory"}

func functionsMap(list []string) (map[string]bool, *apiErr) {
	fn := map[string]bool{"collection_point": false, "transfer_point": false, "hub": false, "laboratory": false}
	for _, f := range list {
		if !contains(validFunctions, f) {
			return nil, errOf(400, "invalid_location_function", "unknown location function: "+f)
		}
		fn[f] = true
	}
	return fn, nil
}

func handleCreateLocation(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		Name            string     `json:"name"`
		Coordinate      Coordinate `json:"coordinate"`
		CoverageKm      float64    `json:"coverageKm"`
		HandlingMinutes int        `json:"handlingMinutes"`
		Active          bool       `json:"active"`
		Functions       []string   `json:"functions"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	if req.Name == "" {
		return 0, nil, errOf(400, "invalid_location", "name is required")
	}
	if !validCoordinate(req.Coordinate) {
		return 0, nil, errOf(400, "invalid_coordinate", "invalid coordinate")
	}
	if req.CoverageKm <= 0 || req.CoverageKm > 5 {
		return 0, nil, errOf(400, "invalid_node_coverage", "coverageKm must be in (0, 5]")
	}
	if req.HandlingMinutes < 0 || req.HandlingMinutes > 1440 {
		return 0, nil, errOf(400, "invalid_handling_time", "handlingMinutes must be in [0, 1440]")
	}
	fn, ferr := functionsMap(req.Functions)
	if ferr != nil {
		return 0, nil, ferr
	}
	id := newUUID()
	_, err := db.Exec(`INSERT INTO locations (id, name, latitude, longitude, coverage_km, handling_minutes, active, functions, capacity_units, cooled_capacity_units) VALUES ($1,$2,$3,$4,$5,$6,$7,$8,0,0)`,
		id, req.Name, req.Coordinate.Latitude, req.Coordinate.Longitude, req.CoverageKm, req.HandlingMinutes, req.Active, mustJSON(fn))
	if err != nil {
		return 0, nil, errOf(500, "internal_error", err.Error())
	}
	recordAudit(s.User.ID, s.ActiveRole, "create_location", "location", id, true, map[string]any{"name": req.Name})
	bumpNetworkRevision()
	l, _ := loadLocation(id)
	return 201, locationJSON(l), nil
}

func handleUpdateLocation(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
