	rows, err := db.Query(`SELECT `+assignmentCols+` FROM assignments WHERE journey_id=$1 AND status='pending' ORDER BY sequence`, journeyID)
	if err != nil {
		return
	}
	defer rows.Close()
	var pending []*Assignment
	for rows.Next() {
		if a, err := scanAssignment(rows); err == nil {
			pending = append(pending, a)
		}
	}
	for _, a := range pending {
		offerAssignment(a)
	}
}

