package main

import (
	"time"
)

func handoffJSON(h *Handoff) map[string]any {
	return map[string]any{
		"handoffId":         h.ID,
		"sampleId":          h.SampleID,
		"fromAssignmentId":  h.FromAssignmentID,
		"toAssignmentId":    h.ToAssignmentID,
		"senderId":          h.SenderID,
		"receiverId":        h.ReceiverID,
		"status":            h.Status,
		"senderConfirmed":   h.SenderConfirmed,
		"receiverConfirmed": h.ReceiverConfirmed,
		"createdAt":         fmtTime(h.CreatedAt),
		"confirmedAt":       nullTime(h.ConfirmedAt),
	}
}

type Handoff struct {
	ID                string
	SampleID          string
	FromAssignmentID  *string
	ToAssignmentID    *string
	SenderID          string
	ReceiverID        string
	Status            string
	SenderConfirmed   bool
	ReceiverConfirmed bool
	CustodyTransferred bool
	CreatedAt         time.Time
	ConfirmedAt       *time.Time
}

func loadHandoff(id string) (*Handoff, error) {
	var h Handoff
	err := db.QueryRow(`SELECT id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id, status, sender_confirmed, receiver_confirmed, custody_transferred, created_at, confirmed_at FROM handoffs WHERE id=$1`, id).
		Scan(&h.ID, &h.SampleID, &h.FromAssignmentID, &h.ToAssignmentID, &h.SenderID, &h.ReceiverID, &h.Status, &h.SenderConfirmed, &h.ReceiverConfirmed, &h.CustodyTransferred, &h.CreatedAt, &h.ConfirmedAt)
	return &h, err
}

func handleInitiateHandoff(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		SampleID         string  `json:"sampleId"`
		FromAssignmentID *string `json:"fromAssignmentId"`
		ToAssignmentID   *string `json:"toAssignmentId"`
		ReceiverID       string  `json:"receiverId"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	sm, err := loadSample(req.SampleID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "sample not found")
	}
	if sm.CurrentHolderID == nil || *sm.CurrentHolderID != s.User.ID {
		return 0, nil, errOf(409, "not_current_holder", "only the current holder may initiate a handoff")
	}
	if _, err := loadUser(req.ReceiverID); err != nil {
		return 0, nil, errOf(404, "not_found", "receiver not found")
	}
	if req.FromAssignmentID != nil {
		fa, err := loadAssignment(*req.FromAssignmentID)
		if err != nil || fa.WorkerID == nil || *fa.WorkerID != s.User.ID {
			return 0, nil, errOf(403, "sender_assignment_mismatch", "the from assignment does not belong to you")
		}
	}
	if req.ToAssignmentID != nil {
		ta, err := loadAssignment(*req.ToAssignmentID)
		if err != nil {
			return 0, nil, errOf(404, "not_found", "to assignment not found")
		}
		if ta.WorkerID != nil && *ta.WorkerID != req.ReceiverID {
			return 0, nil, errOf(409, "receiver_assignment_mismatch", "the to assignment belongs to a different worker")
		}
	}
	handoffID := newUUID()
	db.Exec(`INSERT INTO handoffs (id, sample_id, from_assignment_id, to_assignment_id, sender_id, receiver_id) VALUES ($1,$2,$3,$4,$5,$6)`,
		handoffID, sm.ID, req.FromAssignmentID, req.ToAssignmentID, s.User.ID, req.ReceiverID)
	recordAudit(s.User.ID, s.ActiveRole, "handoff_initiated", "sample", sm.ID, true, map[string]any{"handoffId": handoffID, "receiverId": req.ReceiverID})
	publishEvent("handoff_updated", "handoff", handoffID, "", map[string]any{"sampleId": sm.ID, "status": "pending"})
	h, _ := loadHandoff(handoffID)
	return 201, handoffJSON(h), nil
}

func handleConfirmHandoff(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		HandoffID string `json:"handoffId"`
		Side      string `json:"side"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	h, err := loadHandoff(req.HandoffID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "handoff not found")
	}
	if req.Side != "sender" && req.Side != "receiver" {
		return 0, nil, errOf(400, "invalid_request", "side must be sender or receiver")
	}
	if req.Side == "sender" && h.SenderID != s.User.ID {
		return 0, nil, errOf(403, "forbidden", "only the sender may confirm the sender side")
	}
	if req.Side == "receiver" && h.ReceiverID != s.User.ID {
		return 0, nil, errOf(403, "forbidden", "only the receiver may confirm the receiver side")
	}
	if req.Side == "sender" {
		db.Exec(`UPDATE handoffs SET sender_confirmed=true WHERE id=$1`, h.ID)
		h.SenderConfirmed = true
	} else {
		db.Exec(`UPDATE handoffs SET receiver_confirmed=true WHERE id=$1`, h.ID)
		h.ReceiverConfirmed = true
	}
	status := "pending"
	if h.SenderConfirmed && h.ReceiverConfirmed && !h.CustodyTransferred {
		now := time.Now()
		db.Exec(`UPDATE handoffs SET status='confirmed', custody_transferred=true, confirmed_at=$1 WHERE id=$2`, now, h.ID)
		db.Exec(`UPDATE samples SET current_holder_id=$1, location_recorded_at=$2 WHERE id=$3`, h.ReceiverID, now, h.SampleID)
		recordAudit(s.User.ID, s.ActiveRole, "custody_transferred", "sample", h.SampleID, true, map[string]any{"handoffId": h.ID, "from": h.SenderID, "to": h.ReceiverID})
		publishEvent("custody_changed", "sample", h.SampleID, "", map[string]any{"holderId": h.ReceiverID})
		status = "confirmed"
		h.CustodyTransferred = true
	} else if h.CustodyTransferred {
		status = "confirmed"
	}
	recordAudit(s.User.ID, s.ActiveRole, "handoff_confirmed", "sample", h.SampleID, true, map[string]any{"handoffId": h.ID, "side": req.Side})
	publishEvent("handoff_updated", "handoff", h.ID, "", map[string]any{"sampleId": h.SampleID, "status": status})
	h2, _ := loadHandoff(h.ID)
	return 200, handoffJSON(h2), nil
}

func handleLabReceipt(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		SampleID             string   `json:"sampleId"`
		ReceivedAt           string   `json:"receivedAt"`
		ContainerType        string   `json:"containerType"`
		ObservedTemperatureC *float64 `json:"observedTemperatureC"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	sm, err := loadSample(req.SampleID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "sample not found")
	}
	if sm.Status == "received" {
		return 0, nil, errOf(409, "already_received", "sample was already received")
	}
	if s.User.AssignedLocationID == nil {
		return 0, nil, errOf(403, "laboratory_not_assigned", "you are not assigned to a laboratory")
	}
	if sm.TargetLaboratoryID == nil || *sm.TargetLaboratoryID != *s.User.AssignedLocationID {
		return 0, nil, errOf(403, "laboratory_not_assigned", "this sample is not routed to your laboratory")
	}
	if sm.Status != "at_laboratory" && sm.Status != "in_transit" && sm.Status != "exception" {
		return 0, nil, errOf(409, "invalid_assignment_state", "sample has not arrived at the laboratory (status: "+sm.Status+")")
	}
	r, _ := loadRequest(sm.RequestID)
	receivedAt := time.Now()
	if t, ok := parseTime(req.ReceivedAt); ok {
		receivedAt = t
	}
	if receivedAt.After(r.DeliveryDeadline) {
		db.Exec(`UPDATE samples SET status='expired', exception=$1 WHERE id=$2`, mustJSON(map[string]any{
			"type": "delivery_deadline_exceeded", "code": "delivery_deadline_exceeded",
			"note": "sample arrived after its delivery deadline", "flaggedAt": fmtTime(time.Now()),
		}), sm.ID)
		recordAudit(s.User.ID, s.ActiveRole, "laboratory_receipt_rejected", "sample", sm.ID, false, map[string]any{"reason": "delivery_deadline_exceeded"})
		auditSampleStatus(sm.ID, "expired", map[string]any{"reason": "delivery_deadline_exceeded"})
		return 0, nil, errOf(409, "delivery_deadline_exceeded", "sample arrived after its delivery deadline")
	}
	db.Exec(`UPDATE samples SET status='received', received_at=$1, received_laboratory_id=$2, current_holder_id=$3, location_recorded_at=$1 WHERE id=$4`,
		receivedAt, *s.User.AssignedLocationID, s.User.ID, sm.ID)
	auditSampleStatus(sm.ID, "received", nil)
	if sm.ActiveJourneyID != nil {
		j, err := loadJourney(*sm.ActiveJourneyID)
		if err == nil {
			releaseJourneyCapacity(j, isCooledJourney(sm))
			db.Exec(`UPDATE journeys SET status='completed' WHERE id=$1`, j.ID)
			db.Exec(`UPDATE assignments SET status='completed', updated_at=now() WHERE journey_id=$1 AND kind='laboratory' AND status IN ('offered','accepted','in_progress','pending')`, j.ID)
		}
	}
	recordAudit(s.User.ID, s.ActiveRole, "laboratory_receipt", "sample", sm.ID, true, map[string]any{"receivedAt": fmtTime(receivedAt)})
	publishEvent("sample_status", "sample", sm.ID, "", map[string]any{"status": "received"})
	return 200, map[string]any{
		"sampleId":   sm.ID,
		"status":     "received",
		"receivedAt": fmtTime(receivedAt),
	}, nil
}

func isCooledJourney(sm *Sample) bool {
	r, err := loadRequest(sm.RequestID)
	if err != nil {
		return false
	}
	st, err := loadSampleType(r.SampleTypeID)
	if err != nil {
		return false
	}
	return st.RequiresCooledRoute
}

func handleLabException(s *session, body []byte) (int, any, *apiErr) {
	var req struct {
		SampleID       string  `json:"sampleId"`
		ExceptionType  string  `json:"exceptionType"`
		Note           string  `json:"note"`
		OccurredAt     string  `json:"occurredAt"`
		ObservedTempC  *float64 `json:"observedTemperatureC"`
	}
	if aerr := decodeBody(body, &req); aerr != nil {
		return 0, nil, aerr
	}
	sm, err := loadSample(req.SampleID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "sample not found")
	}
	if s.User.AssignedLocationID == nil || sm.TargetLaboratoryID == nil || *sm.TargetLaboratoryID != *s.User.AssignedLocationID {
		return 0, nil, errOf(403, "laboratory_not_assigned", "this sample is not routed to your laboratory")
	}
	occurredAt := time.Now()
	if t, ok := parseTime(req.OccurredAt); ok {
		occurredAt = t
	}
	db.Exec(`UPDATE samples SET status='exception', exception=$1 WHERE id=$2`, mustJSON(map[string]any{
		"type": req.ExceptionType, "code": req.ExceptionType, "note": req.Note, "flaggedAt": fmtTime(occurredAt),
	}), sm.ID)
	recordAudit(s.User.ID, s.ActiveRole, "laboratory_exception", "sample", sm.ID, true, map[string]any{"exceptionType": req.ExceptionType, "note": req.Note})
	auditSampleStatus(sm.ID, "exception", map[string]any{"code": req.ExceptionType})
	publishEvent("exception_raised", "sample", sm.ID, "dispatcher", map[string]any{"code": req.ExceptionType, "note": req.Note})
	return 201, map[string]any{
		"sampleId":      sm.ID,
		"status":        "exception",
		"exceptionType": req.ExceptionType,
		"recordedAt":    fmtTime(occurredAt),
	}, nil
}

