	mux.HandleFunc("POST /api/set-location-function-status", op("set_location_function_status", false, handleSetLocationFunctionStatus))
	mux.HandleFunc("POST /api/set-connection-status", op("set_connection_status", false, handleSetConnectionStatus))
	mux.HandleFunc("POST /api/set-worker-availability", op("set_worker_availability", false, handleSetWorkerAvailability))
