		s := getSession(r)
		if s == nil {
			writeErr(w, errOf(401, "unauthorized", "authentication required"))
			return
		}
		if s.ActiveRole == "" {
			writeErr(w, errOf(409, "role_not_selected", "an active role must be selected"))
			return
