		postRead(w, r, "search_audit_trail", func(s *session, body []byte) (int, any, *apiErr) {
			var req struct {
				Query      string `json:"query"`
				ActorID    string `json:"actorId"`
				EntityType string `json:"entityType"`
				EntityID   string `json:"entityId"`
				Action     string `json:"action"`
				Role       string `json:"role"`
				Success    *bool  `json:"success"`
				FromTime   string `json:"fromTime"`
				ToTime     string `json:"toTime"`
				Limit      int    `json:"limit"`
				Offset     int    `json:"offset"`
				Order      string `json:"order"`
			}
			json.Unmarshal(body, &req)
			q := map[string]string{
				"query": req.Query,
				"sampleId": req.EntityID, "requestId": req.EntityID, "journeyId": req.EntityID,
				"actorId": req.ActorID, "entityType": req.EntityType, "action": req.Action,
				"role": req.Role, "from": req.FromTime, "to": req.ToTime,
				"order": req.Order,
			}
			if req.Limit > 0 {
				q["limit"] = strconv.Itoa(req.Limit)
			}
			if req.Offset > 0 {
