func postRead(w http.ResponseWriter, r *http.Request, name string, h func(s *session, body []byte) (int, any, *apiErr)) {
	s := getSession(r)
	if s == nil {
		writeErr(w, errOf(401, "unauthorized", "authentication required"))
		return
	}
	if s.ActiveRole == "" {
		writeErr(w, errOf(409, "role_not_selected", "an active role must be selected"))
		return
	}
	if !roleAllowed(name, s.ActiveRole) {
		writeErr(w, errOf(403, "forbidden", "your active role may not perform this action"))
		return
	}
	body, _ := io.ReadAll(r.Body)
	status, data, aerr := h(s, body)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	writeData(w, status, data)
}

func getWrap(w http.ResponseWriter, r *http.Request, name string, h func(s *session) (int, any, *apiErr)) {
	s := getSession(r)
	if s == nil {
		writeErr(w, errOf(401, "unauthorized", "authentication required"))
		return
	}
	if s.ActiveRole == "" {
		writeErr(w, errOf(409, "role_not_selected", "an active role must be selected"))
		return
	}
	if !roleAllowed(name, s.ActiveRole) {
		writeErr(w, errOf(403, "forbidden", "your active role may not perform this action"))
		return
	}
	status, data, aerr := h(s)
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	writeData(w, status, data)
}

