	}
	st, err := loadSampleType(req.SampleTypeID)
	if err != nil {
		return 0, nil, errOf(400, "invalid_acceptance", "sample type not found")
	}
	if req.TemperatureMinC > req.TemperatureMaxC {
		return 0, nil, errOf(400, "invalid_sample_type", "temperatureMinC must not exceed temperatureMaxC")
	}
	if req.IncompatibleSampleTypes == nil {
		req.IncompatibleSampleTypes = []string{}
	}
	for _, other := range req.IncompatibleSampleTypes {
		if _, err := loadSampleType(other); err != nil {
			return 0, nil, errOf(400, "invalid_sample_type", "incompatible sample type does not exist")
		}
	}
	db.Exec(`UPDATE sample_types SET qualified_collector_required=$1, required_qualification=$2, container_type=$3, temperature_min_c=$4, temperature_max_c=$5, incompatible_sample_types=$6, requires_cooled_route=$7, batching_allowed=$8 WHERE id=$9`,
		req.QualifiedCollectorRequired, req.RequiredQualification, req.ContainerType, req.TemperatureMinC, req.TemperatureMaxC, mustJSON(req.IncompatibleSampleTypes), req.RequiresCooledRoute, batchingAllowed, st.ID)
	recordAudit(s.User.ID, s.ActiveRole, "update_sample_type", "sample_type", st.ID, true, map[string]any{"name": st.Name})
	bumpNetworkRevision()
	st, _ = loadSampleType(st.ID)
	return 201, sampleTypeJSON(st), nil
}

