		id, req.Name, req.QualifiedCollectorRequired, req.RequiredQualification, req.ContainerType, req.TemperatureMinC, req.TemperatureMaxC, mustJSON(req.IncompatibleSampleTypes), req.RequiresCooledRoute, batchingAllowed)
	recordAudit(s.User.ID, s.ActiveRole, "create_sample_type", "sample_type", id, true, map[string]any{"name": req.Name})
	bumpNetworkRevision()
	st, _ := loadSampleType(id)
