    req=urllib.request.Request('http://127.0.0.1:8080'+path,data=json.dumps(body).encode() if body is not None else None,headers={'Content-Type':'application/json','X-Idempotency-Key':'k1',**({'Authorization':'Bearer '+token} if token else {})})
    try:
        r=urllib.request.urlopen(req); return r.status,json.loads(r.read())
    except urllib.error.HTTPError as e:
        try: return e.code,json.loads(e.read())
        except: return e.code,{}
s,b=call('/api/authenticate-user',{'username':'admin','password':'admin123'})
tok=b['data']['sessionToken']
s,b=call('/api/search-audit-trail',{},tok)
d=b['data']
print(s,'total',d['total'],'returned',d['returned'])
for e in d['entries'][:5]: print(e['action'],e['entityType'],e['success'])
s,b=call('/api/search-audit-trail',{'action':d['entries'][0]['action'] if d['entries'] else 'x'},tok)
print('filter by action ->',b['data']['total'])
PYEOF

