package main

import (
	"time"
)

type requestInput struct {
	Origin               Coordinate `json:"origin"`
	OriginType           string     `json:"originType"`
	OriginNodeID         *string    `json:"originNodeId"`
	RequestedAt          string     `json:"requestedAt"`
	DeliveryDeadline     string     `json:"deliveryDeadline"`
	EarliestCollectionAt *string    `json:"earliestCollectionAt"`
	LatestCollectionAt   *string    `json:"latestCollectionAt"`
	SampleTypeID         string     `json:"sampleTypeId"`
	ContainerType        string     `json:"containerType"`
	TemperatureMinC      float64    `json:"temperatureMinC"`
	TemperatureMaxC      float64    `json:"temperatureMaxC"`
	IncompatibleTypes    []string   `json:"incompatibleSampleTypes"`
}

func parseRequestInput(body []byte) (*requestInput, *SampleType, time.Time, time.Time, *time.Time, *time.Time, *apiErr) {
	var req requestInput
	if aerr := decodeBody(body, &req); aerr != nil {
		return nil, nil, time.Time{}, time.Time{}, nil, nil, aerr
	}
	if req.OriginType == "" {
		req.OriginType = "home"
	}
	if !contains([]string{"home", "clinic", "node"}, req.OriginType) {
		return nil, nil, time.Time{}, time.Time{}, nil, nil, errOf(400, "invalid_request", "originType must be home, clinic or node")
	}
	if !validCoordinate(req.Origin) {
		return nil, nil, time.Time{}, time.Time{}, nil, nil, errOf(400, "invalid_request", "origin coordinate is invalid")
	}
	st, err := loadSampleType(req.SampleTypeID)
	if err != nil {
		return nil, nil, time.Time{}, time.Time{}, nil, nil, errOf(400, "invalid_request", "unknown sampleTypeId")
	}
	requestedAt, ok := parseTime(req.RequestedAt)
	if !ok {
		return nil, nil, time.Time{}, time.Time{}, nil, nil, errOf(400, "invalid_request", "requestedAt must be an RFC3339 timestamp")
	}
	deadline, ok := parseTime(req.DeliveryDeadline)
	if !ok {
		return nil, nil, time.Time{}, time.Time{}, nil, nil, errOf(400, "invalid_request", "deliveryDeadline must be an RFC3339 timestamp")
	}
	var earliest, latest *time.Time
	if req.EarliestCollectionAt != nil && *req.EarliestCollectionAt != "" {
		if t, ok := parseTime(*req.EarliestCollectionAt); ok {
			earliest = &t
		} else {
			return nil, nil, time.Time{}, time.Time{}, nil, nil, errOf(400, "invalid_request", "earliestCollectionAt must be an RFC3339 timestamp")
		}
	}
	if req.LatestCollectionAt != nil && *req.LatestCollectionAt != "" {
		if t, ok := parseTime(*req.LatestCollectionAt); ok {
			latest = &t
		} else {
			return nil, nil, time.Time{}, time.Time{}, nil, nil, errOf(400, "invalid_request", "latestCollectionAt must be an RFC3339 timestamp")
		}
	}
	if earliest != nil && latest != nil && earliest.After(*latest) {
		return nil, nil, time.Time{}, time.Time{}, nil, nil, errOf(400, "invalid_time_window", "earliestCollectionAt must not be after latestCollectionAt")
	}
	if latest != nil && latest.After(deadline) {
		return nil, nil, time.Time{}, time.Time{}, nil, nil, errOf(400, "invalid_time_window", "collection window must end before the delivery deadline")
	}
	if !deadline.After(time.Now().Add(-time.Hour)) {
		return nil, nil, time.Time{}, time.Time{}, nil, nil, errOf(400, "invalid_time_window", "deliveryDeadline is in the past")
	}
	return &req, st, requestedAt, deadline, earliest, latest, nil
}

func serviceabilityVersion() int {
	var v int
	if err := db.QueryRow(`SELECT value::int FROM app_meta WHERE key='serviceability_version'`).Scan(&v); err != nil || v < 1 {
		return 1
	}
	return v
}

func bumpServiceabilityVersion() {
	db.Exec(`INSERT INTO app_meta (key, value) VALUES ('serviceability_version','2')
		ON CONFLICT (key) DO UPDATE SET value=(app_meta.value::int+1)::text`)
}

func serviceabilityResultJSON(plan planResult, dryRun bool) map[string]any {
	reason := "serviceable"
	if !plan.serviceable {
		reason = plan.reason
	}
	out := map[string]any{
		"serviceable":          plan.serviceable,
		"reason":               reason,
		"serviceabilityVersion": serviceabilityVersion(),
	}
	if plan.lab != nil {
		out["targetLaboratoryId"] = plan.lab.ID
	}
	if !plan.estimatedDelivery.IsZero() {
		out["estimatedArrivalAt"] = plan.estimatedDelivery.UTC().Format(time.RFC3339Nano)
	}
	return out
}

