package main

import (
	"encoding/json"
	"fmt"
	"net/http"
	"strconv"
	"strings"
	"time"
)

func timelineForSample(sampleID string, statusOnly bool) []map[string]any {
	q := `SELECT id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details FROM audit_log WHERE entity_type='sample' AND entity_id=$1`
	if statusOnly {
		q += ` AND action='sample_status'`
	}
	q += ` ORDER BY id`
	rows, err := db.Query(q, sampleID)
	if err != nil {
		return []map[string]any{}
	}
	defer rows.Close()
	entries := []map[string]any{}
	for rows.Next() {
		var id int64
		var actorID, role, action, entityType, entityID string
		var success bool
		var at time.Time
		var details []byte
		rows.Scan(&id, &actorID, &role, &action, &entityType, &entityID, &success, &at, &details)
		var det map[string]any
		json.Unmarshal(details, &det)
		if det == nil {
			det = map[string]any{}
		}
		entries = append(entries, map[string]any{
			"eventId":    id,
			"action":     action,
			"actorId":    actorID,
			"role":       role,
			"entityType": entityType,
			"entityId":   entityID,
			"success":    success,
			"occurredAt": fmtTime(at),
			"details":    det,
		})
	}
	return entries
}

func sampleStateJSON(sm *Sample) map[string]any {
	r, err := loadRequest(sm.RequestID)
	if err != nil {
		return map[string]any{"sampleId": sm.ID, "state": map[string]any{"status": sm.Status}}
	}
	activeAssignmentIDs := []string{}
	rows, err := db.Query(`SELECT id FROM assignments WHERE sample_id=$1 AND status IN ('pending','offered','accepted','in_progress') ORDER BY sequence`, sm.ID)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var id string
			rows.Scan(&id)
			activeAssignmentIDs = append(activeAssignmentIDs, id)
		}
	}
	m := map[string]any{
		"sampleId":                sm.ID,
		"requestId":               r.ID,
		"requesterId":             r.RequesterID,
		"origin":                  r.Origin,
		"originType":              r.OriginType,
		"requestedAt":             fmtTime(r.RequestedAt),
		"deliveryDeadline":        fmtTime(r.DeliveryDeadline),
		"sampleTypeId":            r.SampleTypeID,
		"containerType":           r.ContainerType,
		"temperatureMinC":         r.TempMin,
		"temperatureMaxC":         r.TempMax,
		"incompatibleSampleTypes": r.Incompatible,
		"serviceability":          r.Serviceability,
		"activeAssignmentIds":     activeAssignmentIDs,
		"state":                   map[string]any{"status": sm.Status},
		"timeline":                timelineForSample(sm.ID, true),
		"locationStale":           staleLocation(sm.LocationRecordedAt),
	}
	if sm.ActiveJourneyID != nil {
		m["activeJourneyId"] = *sm.ActiveJourneyID
	}
	if sm.TargetLaboratoryID != nil {
		m["targetLaboratoryId"] = *sm.TargetLaboratoryID
	}
	if sm.LatestLocation != nil {
		m["latestLocation"] = sm.LatestLocation
	}
	if sm.LocationRecordedAt != nil {
		m["locationRecordedAt"] = fmtTime(*sm.LocationRecordedAt)
	}
	return m
}

func capacityJSON(capUnits, resUnits, coolCap, coolRes int) map[string]any {
	return map[string]any{
		"capacityUnits":        capUnits,
		"reservedUnits":        resUnits,
		"availableUnits":       capUnits - resUnits,
		"cooledCapacityUnits":  coolCap,
		"cooledReservedUnits":  coolRes,
		"cooledAvailableUnits": coolCap - coolRes,
	}
}

func opsSampleJSON(sm *Sample) map[string]any {
	r, err := loadRequest(sm.RequestID)
	if err != nil {
		return map[string]any{"sampleId": sm.ID, "status": sm.Status, "locationStale": staleLocation(sm.LocationRecordedAt)}
	}
	m := map[string]any{
		"sampleId":           sm.ID,
		"sample_id":          sm.ID,
		"status":             sm.Status,
		"requestId":          r.ID,
		"origin":             r.Origin,
		"deliveryDeadline":   fmtTime(r.DeliveryDeadline),
		"locationStale":      staleLocation(sm.LocationRecordedAt),
		"locationRecordedAt": nullTime(sm.LocationRecordedAt),
	}
	if sm.CurrentHolderID != nil {
		m["currentHolderId"] = *sm.CurrentHolderID
	}
	if sm.ActiveJourneyID != nil {
		m["activeJourneyId"] = *sm.ActiveJourneyID
	}
	if sm.LatestLocation != nil {
		m["latestLocation"] = sm.LatestLocation
	}
	return m
}

func canSeeSample(s *session, sm *Sample) bool {
	role := s.ActiveRole
	if role == "dispatcher" || role == "administrator" {
		return true
	}
	if role == "requester" {
		return sm.RequesterID == s.User.ID
	}
	// workers: involved via an assignment or custody
	if sm.CurrentHolderID != nil && *sm.CurrentHolderID == s.User.ID {
		return true
	}
	var n int
	db.QueryRow(`SELECT count(*) FROM assignments WHERE sample_id=$1 AND (worker_id=$2 OR offered_to=$2)`, sm.ID, s.User.ID).Scan(&n)
	return n > 0
}

func handleReadSampleState(s *session, sampleID string) (int, any, *apiErr) {
	sm, err := loadSample(sampleID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "sample not found")
	}
	if !canSeeSample(s, sm) {
		return 0, nil, errOf(403, "forbidden", "you may not view this sample")
	}
	return 200, sampleStateJSON(sm), nil
}

func handleReadSampleLifecycle(s *session, sampleID string) (int, any, *apiErr) {
	sm, err := loadSample(sampleID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "sample not found")
	}
	if !canSeeSample(s, sm) {
		return 0, nil, errOf(403, "forbidden", "you may not view this sample")
	}
	completedLegIDs := []string{}
	rows, err := db.Query(`SELECT id FROM assignments WHERE sample_id=$1 AND kind='transport' AND status='completed' ORDER BY sequence`, sampleID)
	if err == nil {
		defer rows.Close()
		for rows.Next() {
			var id string
			rows.Scan(&id)
			completedLegIDs = append(completedLegIDs, id)
		}
	}
	activeReplacementPlanIDs := []string{}
	if sm.ActiveJourneyID != nil {
		var repl *string
		db.QueryRow(`SELECT replacement_plan_id::text FROM journeys WHERE id=$1`, *sm.ActiveJourneyID).Scan(&repl)
		if repl != nil {
			activeReplacementPlanIDs = append(activeReplacementPlanIDs, *repl)
		}
	}
	m := map[string]any{
		"sampleId":                 sm.ID,
		"status":                   sm.Status,
		"sealed":                   sm.Sealed,
		"completedLegIds":          completedLegIDs,
		"activeReplacementPlanIds": activeReplacementPlanIDs,
		"timeline":                 timelineForSample(sampleID, false),
		"locationStale":            staleLocation(sm.LocationRecordedAt),
	}
	if sm.ActiveJourneyID != nil {
		m["activeJourneyId"] = *sm.ActiveJourneyID
	}
	if sm.CurrentHolderID != nil {
		m["currentHolderId"] = *sm.CurrentHolderID
	}
	if sm.ReceivedLaboratoryID != nil {
		m["receivedLaboratoryId"] = *sm.ReceivedLaboratoryID
	}
	if sm.Exception != nil {
		m["exception"] = sm.Exception
	}
	if sm.LatestLocation != nil {
		m["latestLocation"] = sm.LatestLocation
	}
	if sm.LocationRecordedAt != nil {
		m["locationRecordedAt"] = fmtTime(*sm.LocationRecordedAt)
	}
	var pendingHandoffID *string
	db.QueryRow(`SELECT id FROM handoffs WHERE sample_id=$1 AND status='pending' ORDER BY created_at DESC LIMIT 1`, sampleID).Scan(&pendingHandoffID)
	if pendingHandoffID != nil {
		m["pendingHandoffId"] = *pendingHandoffID
		var senderID, receiverID string
		var senderConf, receiverConf bool
		db.QueryRow(`SELECT sender_id, receiver_id, sender_confirmed, receiver_confirmed FROM handoffs WHERE id=$1`, *pendingHandoffID).Scan(&senderID, &receiverID, &senderConf, &receiverConf)
		m["pendingHandoff"] = map[string]any{
			"handoffId":         *pendingHandoffID,
			"senderId":          senderID,
			"receiverId":        receiverID,
			"senderConfirmed":   senderConf,
			"receiverConfirmed": receiverConf,
		}
	}
	return 200, m, nil
}

func assignmentWorkItemJSON(a *Assignment) map[string]any {
	return map[string]any{
		"assignmentId":   a.ID,
		"journeyId":      a.JourneyID,
		"sampleId":       a.SampleID,
		"kind":           a.Kind,
		"status":         a.Status,
		"offeredTo":      a.OfferedTo,
		"offerExpiresAt": nullTime(a.OfferExpiresAt),
	}
}

func handleListRoleWork(s *session, roleFilter string) (int, any, *apiErr) {
	role := s.ActiveRole
	if roleFilter != "" {
		if !contains(s.User.Roles, roleFilter) {
			return 0, nil, errOf(403, "role_not_held", "you do not hold this role")
		}
		role = roleFilter
	}
	pending := []any{}
	inProgress := []any{}
	completed := []any{}
	switch role {
	case "requester":
		rows, _ := db.Query(`SELECT id FROM samples WHERE requester_id=$1 ORDER BY created_at DESC`, s.User.ID)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var id string
				rows.Scan(&id)
				sm, err := loadSample(id)
				if err != nil {
					continue
				}
				item := map[string]any{
					"sampleId":         sm.ID,
					"requestId":        sm.RequestID,
					"status":           sm.Status,
					"currentHolderId":  sm.CurrentHolderID,
					"activeJourneyId":  sm.ActiveJourneyID,
					"deliveryDeadline": nil,
				}
				if r, err := loadRequest(sm.RequestID); err == nil {
					item["deliveryDeadline"] = fmtTime(r.DeliveryDeadline)
				}
				switch sm.Status {
				case "created":
					pending = append(pending, item)
				case "received", "cancelled", "expired":
					completed = append(completed, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
		}
	case "dispatcher", "administrator":
		rows, _ := db.Query(`SELECT id FROM journeys ORDER BY created_at DESC LIMIT 200`)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				var id string
				rows.Scan(&id)
				j, err := loadJourney(id)
				if err != nil {
					continue
				}
				var holder any
				if len(j.SampleIDs) > 0 {
					if sm, err := loadSample(j.SampleIDs[0]); err == nil && sm.CurrentHolderID != nil {
						holder = *sm.CurrentHolderID
					}
				}
				item := map[string]any{
					"journeyId":       j.ID,
					"planVersion":     j.PlanVersion,
					"routeMode":       j.RouteMode,
					"status":          j.Status,
					"sampleIds":       j.SampleIDs,
					"currentHolderId": holder,
				}
				switch j.Status {
				case "planned":
					pending = append(pending, item)
				case "in_progress":
					inProgress = append(inProgress, item)
				default:
					completed = append(completed, item)
				}
			}
		}
	default:
		// worker roles
		rows, _ := db.Query(`SELECT `+assignmentCols+` FROM assignments WHERE (offered_to=$1 AND status='offered') OR worker_id=$1 ORDER BY updated_at DESC LIMIT 200`, s.User.ID)
		if rows != nil {
			defer rows.Close()
			for rows.Next() {
				a, err := scanAssignment(rows)
				if err != nil {
					continue
				}
				item := assignmentWorkItemJSON(a)
				switch a.Status {
				case "offered":
					pending = append(pending, item)
				case "accepted", "in_progress":
					inProgress = append(inProgress, item)
				default:
					completed = append(completed, item)
				}
			}
		}
	}
	return 200, map[string]any{
		"role":       role,
		"pending":    pending,
		"inProgress": inProgress,
		"completed":  completed,
	}, nil
}

func handleReadJourneyPlan(s *session, journeyID string) (int, any, *apiErr) {
	j, err := loadJourney(journeyID)
	if err != nil {
		return 0, nil, errOf(404, "not_found", "journey not found")
	}
	role := s.ActiveRole
	// access checks
	if role == "requester" {
		ok := false
		for _, sid := range j.SampleIDs {
			if sm, err := loadSample(sid); err == nil && sm.RequesterID == s.User.ID {
				ok = true
			}
		}
		if !ok {
			return 0, nil, errOf(403, "forbidden", "you may not view this journey")
		}
	} else if role != "dispatcher" && role != "administrator" {
		var n int
		db.QueryRow(`SELECT count(*) FROM assignments WHERE journey_id=$1 AND (worker_id=$2 OR offered_to=$2)`, j.ID, s.User.ID).Scan(&n)
		if n == 0 {
			return 0, nil, errOf(403, "forbidden", "you may not view this journey")
		}
	}
	// load all assignments for this journey
	asgs := []*Assignment{}
	rows, _ := db.Query(`SELECT `+assignmentCols+` FROM assignments WHERE journey_id=$1 ORDER BY sequence`, j.ID)
	if rows != nil {
		for rows.Next() {
			if a, err := scanAssignment(rows); err == nil {
				asgs = append(asgs, a)
			}
		}
		rows.Close()
	}
	byID := map[string]*Assignment{}
	for _, a := range asgs {
		byID[a.ID] = a
	}
	fallbackETA := nullTime(j.EstimatedDeliveryAt)
	stops := []map[string]any{}
	for _, st := range j.Stops {
		eta := st["estimatedAt"]
		if eta == nil {
			eta = fallbackETA
		}
		stop := map[string]any{
			"stopId":      st["stopId"],
			"locationId":  st["locationId"],
			"stopType":    st["kind"],
			"sequence":    st["sequence"],
			"estimatedAt": eta,
		}
		if lid, ok := st["locationId"].(string); ok {
			if l, err := loadLocation(lid); err == nil {
				stop["coordinate"] = l.Coord
			}
		}
		stops = append(stops, stop)
	}
	legJSON := func(lg map[string]any) map[string]any {
		out := map[string]any{
			"assignmentId":   lg["assignmentId"],
			"sequence":       lg["sequence"],
			"status":         "pending",
			"fromLocationId": lg["fromLocationId"],
			"toLocationId":   lg["toLocationId"],
		}
		if aid, ok := lg["assignmentId"].(string); ok {
			if a := byID[aid]; a != nil {
				out["status"] = a.Status
				if a.WorkerID != nil {
					out["workerId"] = *a.WorkerID
				}
				if a.SampleID != nil {
					out["sampleId"] = *a.SampleID
				}
			}
		}
		return out
	}
	collectionIDs := []string{}
	nodeIDs := []string{}
	labIDs := []string{}
	transportIDs := []string{}
	assignedWorkers := []string{}
	seenW := map[string]bool{}
	workerAssignmentIDs := []string{}
	for _, a := range asgs {
		switch a.Kind {
		case "collection":
			collectionIDs = append(collectionIDs, a.ID)
		case "node":
			nodeIDs = append(nodeIDs, a.ID)
		case "laboratory":
			labIDs = append(labIDs, a.ID)
		case "transport":
			transportIDs = append(transportIDs, a.ID)
		}
		if a.WorkerID != nil && !seenW[*a.WorkerID] {
			seenW[*a.WorkerID] = true
			assignedWorkers = append(assignedWorkers, *a.WorkerID)
		}
		if (a.WorkerID != nil && *a.WorkerID == s.User.ID) || (a.OfferedTo != nil && *a.OfferedTo == s.User.ID) {
			workerAssignmentIDs = append(workerAssignmentIDs, a.ID)
		}
	}
	legs := []map[string]any{}
	for _, lg := range j.Legs {
		include := true
		if role != "dispatcher" && role != "administrator" && role != "requester" {
			include = false
			if aid, ok := lg["assignmentId"].(string); ok {
				if a := byID[aid]; a != nil {
					if (a.WorkerID != nil && *a.WorkerID == s.User.ID) || (a.OfferedTo != nil && *a.OfferedTo == s.User.ID) {
						include = true
					}
				}
			}
		}
		if include {
			legs = append(legs, legJSON(lg))
		}
	}
	valid := j.Status != "cancelled" && j.Status != "expired"
	base := map[string]any{
		"journeyId":       j.ID,
		"planVersion":     j.PlanVersion,
		"routeMode":       j.RouteMode,
		"status":          j.Status,
		"sampleIds":       j.SampleIDs,
		"orderedStops":    stops,
		"legs":            legs,
		"parentJourneyId": j.ParentJourneyID,
	}
	if role == "requester" {
		base["estimatedDeliveryAt"] = nullTime(j.EstimatedDeliveryAt)
		base["totalCostUnits"] = j.TotalCostUnits
		return 200, base, nil
	}
	if role != "dispatcher" && role != "administrator" {
		base["estimatedDeliveryAt"] = nullTime(j.EstimatedDeliveryAt)
		base["scope"] = "assigned_legs"
		base["assignmentIds"] = workerAssignmentIDs
		base["collectionAssignmentIds"] = collectionIDs
		base["nodeAssignmentIds"] = nodeIDs
		base["laboratoryAssignmentIds"] = labIDs
		base["assignedWorkerIds"] = assignedWorkers
		return 200, base, nil
	}
	base["estimatedDeliveryAt"] = nullTime(j.EstimatedDeliveryAt)
	base["totalCostUnits"] = j.TotalCostUnits
	base["capacityUsed"] = len(j.SampleIDs)
	base["capacityAvailable"] = true
	base["assignedWorkerIds"] = assignedWorkers
	base["collectionAssignmentIds"] = collectionIDs
	if len(collectionIDs) > 0 {
		base["collectionAssignmentId"] = collectionIDs[0]
	}
	base["nodeAssignmentIds"] = nodeIDs
	base["laboratoryAssignmentIds"] = labIDs
	if len(transportIDs) > 0 {
		base["firstTransportAssignmentId"] = transportIDs[0]
		base["finalTransportAssignmentId"] = transportIDs[len(transportIDs)-1]
	}
	if len(transportIDs) > 2 {
		base["middleTransportAssignmentId"] = transportIDs[1]
	}
	base["valid"] = valid
	base["replanStatus"] = j.ReplanStatus
	base["replacementJourney"] = j.ReplacementPlanID
	return 200, base, nil
}

func operationsStateJSON(audienceRole string) map[string]any {
	samples := []any{}
	rows, _ := db.Query(`SELECT id FROM samples ORDER BY created_at DESC LIMIT 500`)
	if rows != nil {
		for rows.Next() {
			var id string
			rows.Scan(&id)
			if sm, err := loadSample(id); err == nil {
				samples = append(samples, opsSampleJSON(sm))
			}
		}
		rows.Close()
	}
	workers := []any{}
	wrows, _ := db.Query(`SELECT id FROM users WHERE roles ?| ARRAY['collection_professional','delivery_partner','node_handler','laboratory_team']`)
	if wrows != nil {
		for wrows.Next() {
			var id string
			wrows.Scan(&id)
			u, err := loadUser(id)
			if err != nil {
				continue
			}
			var active int
			db.QueryRow(`SELECT count(*) FROM assignments WHERE worker_id=$1 AND status IN ('accepted','in_progress')`, u.ID).Scan(&active)
			status := "unavailable"
			if u.Available {
				status = "available"
			}
			w := map[string]any{
				"workerId":           u.ID,
				"worker_id":          u.ID,
				"fullName":           u.FullName,
				"roles":              u.Roles,
				"available":          u.Available,
				"status":             status,
				"capacityUnits":      1,
				"assignmentCount":    active,
				"locationStale":      staleLocation(u.LocationRecordedAt),
				"locationRecordedAt": nullTime(u.LocationRecordedAt),
			}
			if u.LatestLocation != nil {
				w["latestLocation"] = u.LatestLocation
				w["latest_location"] = u.LatestLocation
			}
			workers = append(workers, w)
		}
		wrows.Close()
	}
	locations := []any{}
	for _, l := range loadAllLocations() {
		locations = append(locations, map[string]any{
			"id":              l.ID,
			"locationId":      l.ID,
			"name":            l.Name,
			"coordinate":      l.Coord,
			"active":          l.Active,
			"coverageKm":      l.CoverageKm,
			"handlingMinutes": l.HandlingMinutes,
			"functions": map[string]bool{
				"collection_point": l.Functions["collection_point"],
				"transfer_point":   l.Functions["transfer_point"],
				"hub":              l.Functions["hub"],
				"laboratory":       l.Functions["laboratory"],
			},
			"capacity": capacityJSON(l.CapacityUnits, l.ReservedUnits, l.CooledCapacityUnits, l.CooledReservedUnits),
		})
	}
	connections := []any{}
	for _, c := range loadAllConnections() {
		connections = append(connections, map[string]any{
			"id":             c.ID,
			"connectionId":   c.ID,
			"fromLocationId": c.FromLocationID,
			"toLocationId":   c.ToLocationID,
			"travelMinutes":  c.TravelMinutes,
			"costUnits":      c.CostUnits,
			"cooled":         c.Cooled,
			"active":         c.Active,
			"capacity":       capacityJSON(c.CapacityUnits, c.ReservedUnits, c.CooledCapacityUnits, c.CooledReservedUnits),
		})
	}
	routes := []any{}
	jrows, _ := db.Query(`SELECT id FROM journeys ORDER BY created_at DESC LIMIT 200`)
	if jrows != nil {
		for jrows.Next() {
			var id string
			jrows.Scan(&id)
			if j, err := loadJourney(id); err == nil {
				routes = append(routes, journeySummaryJSON(j))
			}
		}
		jrows.Close()
	}
	handoffs := []any{}
	hrows, _ := db.Query(`SELECT id FROM handoffs ORDER BY created_at DESC LIMIT 100`)
	if hrows != nil {
		for hrows.Next() {
			var id string
			hrows.Scan(&id)
			if h, err := loadHandoff(id); err == nil {
				handoffs = append(handoffs, handoffJSON(h))
			}
		}
		hrows.Close()
	}
	exceptions := []any{}
	erows, _ := db.Query(`SELECT id FROM samples WHERE exception IS NOT NULL AND status IN ('exception','expired') ORDER BY created_at DESC LIMIT 100`)
	if erows != nil {
		for erows.Next() {
			var id string
			erows.Scan(&id)
			if sm, err := loadSample(id); err == nil {
				exceptions = append(exceptions, sampleStateJSON(sm))
			}
		}
		erows.Close()
	}
	var maxActive, minActive, ineligible int
	db.QueryRow(`SELECT COALESCE(max(c),0), COALESCE(min(c),0) FROM (SELECT count(*) AS c FROM assignments WHERE status IN ('accepted','in_progress') GROUP BY worker_id) t`).Scan(&maxActive, &minActive)
	db.QueryRow(`SELECT count(*) FROM assignments WHERE status='pending' AND no_eligible_since IS NOT NULL`).Scan(&ineligible)
	return map[string]any{
		"samples":                   samples,
		"workers":                   workers,
		"locations":                 locations,
		"connections":               connections,
		"routes":                    routes,
		"handoffs":                  handoffs,
		"delays":                    []any{},
		"exceptions":                exceptions,
		"assignmentCountSpread":     maxActive - minActive,
		"ineligibleAssignmentCount": ineligible,
	}
}

