func handleSearchAudit(s *session, q map[string]string) (int, any, *apiErr) {
	where := []string{"1=1"}
	args := []any{}
	i := 1
	add := func(cond string, val string) {
		where = append(where, fmt.Sprintf(cond, i))
		args = append(args, val)
		i++
	}
	if v := q["sampleId"]; v != "" {
		add(`entity_id=$%d`, v)
	}
	if v := q["requestId"]; v != "" {
		add(`entity_id=$%d`, v)
	}
	if v := q["journeyId"]; v != "" {
		add(`entity_id=$%d`, v)
	}
	if v := q["actorId"]; v != "" {
		add(`actor_id=$%d`, v)
	}
	if v := q["role"]; v != "" {
		add(`role=$%d`, v)
	}
	if v := q["action"]; v != "" {
		add(`action=$%d`, v)
	}
	if v := q["entityType"]; v != "" {
		add(`entity_type=$%d`, v)
	}
	if v := q["success"]; v != "" {
		add(`success=$%d`, v)
	}
	if v := q["from"]; v != "" {
		if t, ok := parseTime(v); ok {
			where = append(where, fmt.Sprintf("occurred_at >= $%d", i))
			args = append(args, t)
			i++
		}
	}
	if v := q["to"]; v != "" {
		if t, ok := parseTime(v); ok {
			where = append(where, fmt.Sprintf("occurred_at <= $%d", i))
			args = append(args, t)
			i++
		}
	}
	if v := q["query"]; v != "" {
		where = append(where, fmt.Sprintf("(action ILIKE $%d OR entity_id ILIKE $%d OR details::text ILIKE $%d)", i, i, i))
		args = append(args, "%"+v+"%")
		i++
	}
	limit := 500
	if v := q["limit"]; v != "" {
		if n, err := strconv.Atoi(v); err == nil && n > 0 && n <= 5000 {
			limit = n
		}
	}
	offset := 0
	if v := q["offset"]; v != "" {
		if n, err := strconv.Atoi(v); err == nil && n >= 0 {
			offset = n
		}
	}
	dir := "DESC"
	order := "newest_first"
	if q["order"] == "oldest_first" {
		dir = "ASC"
		order = "oldest_first"
	}
	whereSQL := strings.Join(where, " AND ")
	var total int
	if err := db.QueryRow(`SELECT COUNT(*) FROM audit_log WHERE `+whereSQL, args...).Scan(&total); err != nil {
		return 0, nil, errOf(500, "internal_error", err.Error())
	}
	query := `SELECT id, actor_id, role, action, entity_type, entity_id, success, occurred_at, details FROM audit_log WHERE ` + whereSQL + ` ORDER BY id ` + dir + ` LIMIT ` + strconv.Itoa(limit) + ` OFFSET ` + strconv.Itoa(offset)
	rows, err := db.Query(query, args...)
	if err != nil {
		return 0, nil, errOf(500, "internal_error", err.Error())
	}
	defer rows.Close()
	entries := []map[string]any{}
	for rows.Next() {
		var id int64
		var actorID, role, action, entityType, entityID string
		var success bool
		var at time.Time
		var details []byte
		rows.Scan(&id, &actorID, &role, &action, &entityType, &entityID, &success, &at, &details)
		var det map[string]any
		json.Unmarshal(details, &det)
		if det == nil {
			det = map[string]any{}
		}
		entries = append(entries, map[string]any{
			"auditId":    strconv.FormatInt(id, 10),
			"actorId":    actorID,
			"role":       role,
			"actorRole":  role,
			"action":     action,
			"entityType": entityType,
			"entityId":   entityID,
			"success":    success,
			"occurredAt": fmtTime(at),
			"details":    det,
		})
	}
	hasMore := offset+len(entries) < total
	result := map[string]any{
		"entries":  entries,
		"total":    total,
		"returned": len(entries),
		"offset":   offset,
		"limit":    limit,
		"order":    order,
		"hasMore":  hasMore,
	}
	if hasMore {
		result["nextOffset"] = offset + len(entries)
	}
	return 200, result, nil
}

func handleListEvents(s *session, q map[string]string) (int, any, *apiErr) {
	cursor := int64(0)
	if c := q["cursor"]; c != "" {
		if n, err := strconv.ParseInt(c, 10, 64); err == nil {
			cursor = n
		}
	}
	rows, err := db.Query(`SELECT id, type, entity_type, entity_id, payload, created_at FROM events WHERE id > $1 ORDER BY id LIMIT 200`, cursor)
	if err != nil {
		return 0, nil, errOf(500, "internal_error", err.Error())
	}
	defer rows.Close()
	events := []map[string]any{}
	var last int64 = cursor
	for rows.Next() {
		var id int64
		var typ, et, eid string
		var payload []byte
		var at time.Time
		rows.Scan(&id, &typ, &et, &eid, &payload, &at)
		var p map[string]any
		json.Unmarshal(payload, &p)
		if p == nil {
			p = map[string]any{}
		}
		events = append(events, map[string]any{
			"cursor":     strconv.FormatInt(id, 10),
			"type":       typ,
			"entityType": et,
			"entityId":   eid,
			"payload":    p,
			"createdAt":  fmtTime(at),
		})
		last = id
	}
	return 200, map[string]any{"events": events, "nextCursor": strconv.FormatInt(last, 10)}, nil
}

