		}
		for _, c := range conns {
			if c.FromLocationID != it.node || !c.Active {
				continue
			}
			to := locs[c.ToLocationID]
			if to == nil || !to.Active {
				continue
			}
			if st.RequiresCooledRoute && !c.Cooled {
				continue
			}
