	}
	for _, nid := range nodeIDs {
		aseq++
		db.Exec(`INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, node_id, status) VALUES ($1,$2,$3,'node',$4,$5,'pending')`,
			newUUID(), journeyID, sampleID, aseq, nid)
	}
	aseq++
	db.Exec(`INSERT INTO assignments (id, journey_id, sample_id, kind, sequence, laboratory_id, status) VALUES ($1,$2,$3,'laboratory',$4,$5,'pending')`,
		newUUID(), journeyID, sampleID, aseq, plan.lab.ID)

	db.Exec(`UPDATE journeys SET legs=$1 WHERE id=$2`, mustJSON(legs), journeyID)
	reserveCapacity(plan, st.RequiresCooledRoute)
	db.Exec(`UPDATE samples SET active_journey_id=$1, target_laboratory_id=$2 WHERE id=$3`, journeyID, plan.lab.ID, sampleID)

	j, _ := loadJourney(journeyID)
	// kick off offers for pending assignments
	offerPendingAssignments(journeyID)
