		requestID, s.User.ID, mustJSON(req.Origin), req.OriginType, req.OriginNodeID, requestedAt, deadline, earliest, latest, st.ID, st.ContainerType, st.TemperatureMinC, st.TemperatureMaxC, mustJSON(inc))
